        // Smaller value: ignored (pool stays at the larger of the two).
        assert_eq!(actor.gain_temp_hp(3), 5);
        assert_eq!(actor.temp_hp(), 5);
        // Bigger value: replaces.
        assert_eq!(actor.gain_temp_hp(8), 8);
