    /// Breath Weapon: once-per-short-rest feature; spending it removes
    /// the feature flag from `features_remaining`. Short rest refreshes
    /// the charge via the `SHORT_REST_FEATURES` registry.
    #[test]
    fn breath_weapon_consumes_feature_and_short_rest_refreshes() {
        use crate::actions::class_features::BREATH_WEAPON_TAG;
        use crate::actors::creatures::dragonborn::DRAGONBORN_TEMPLATE;

        let mut e = ei_with_terrain(15, 15, &[]);
        let id = e
            .instantiate_creature(&DRAGONBORN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let actor = e.actors.get_mut(&id).unwrap();
        assert!(actor.spend_feature(BREATH_WEAPON_TAG));
        assert!(!actor.feature_available(BREATH_WEAPON_TAG));
        // Short rest refreshes the breath weapon (registered in
        // SHORT_REST_FEATURES).
        let mut roller = crate::engine::dice::FastRandRoller::with_seed(0);
        actor.short_rest(&mut roller);
        assert!(actor.feature_available(BREATH_WEAPON_TAG));
    }

    /// Quickened Spell metamagic: costs 2 SP + a Bonus Action and
    /// grants the sorcerer an extra Action this turn.
    #[test]
    fn quickened_spell_spends_two_sp_and_grants_action() {
        use crate::actions::metamagic::QUICKENED_SPELL;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;

        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let actor = e.actors.get_mut(&sorcerer).unwrap();
        actor.give_resource(crate::engine::side_effects::Resource::BonusAction);
        let sp_before = actor.sorcery_points();
        let actions_before = actor.action_slots();
        assert!(sp_before >= 2);

        let effects = QUICKENED_SPELL.execute(&mut e, sorcerer, None, None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        let after = e.actors.get(&sorcerer).unwrap();
        assert_eq!(after.sorcery_points(), sp_before - 2, "2 SP spent");
        assert_eq!(
            after.action_slots(),
            actions_before + 1,
            "quickened grants an extra Action this turn"
        );
    }

    /// Heightened Spell metamagic: costs 3 SP + a Bonus Action and
    /// installs the `HeightenedSpelling` prime on the caster. The
    /// first save resolved against the caster through
    /// `roll_save_against_caster` consumes the prime and is forced to
    /// disadvantage; later saves in the same encounter fall through to
    /// the unmodified path.
    #[test]
    fn heightened_spell_spends_three_sp_and_primes() {
        use crate::actions::metamagic::HEIGHTENED_SPELL;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::conditions::Condition;

        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let actor = e.actors.get_mut(&sorcerer).unwrap();
        actor.give_resource(crate::engine::side_effects::Resource::BonusAction);
        let sp_before = actor.sorcery_points();
        assert!(sp_before >= 3);

        let effects = HEIGHTENED_SPELL.execute(&mut e, sorcerer, None, None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        let after = e.actors.get(&sorcerer).unwrap();
        assert_eq!(after.sorcery_points(), sp_before - 3, "3 SP spent");
        assert!(
            after.has_condition(Condition::HeightenedSpelling),
            "heightened prime is installed"
        );
    }

    /// Heightened Spell is gated on the sorcery-points pool: a sorcerer
    /// with fewer than 3 SP can't fire the metamagic.
    #[test]
    fn heightened_spell_blocked_without_three_sp() {
        use crate::actions::metamagic::HEIGHTENED_SPELL;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;

        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let actor = e.actors.get_mut(&sorcerer).unwrap();
        actor.give_resource(crate::engine::side_effects::Resource::BonusAction);
        // Burn the SP pool down to 2 (one short of the 3-SP cost).
        while actor.sorcery_points() > 2 {
            actor.spend_sorcery_point();
        }
        assert!(
            !HEIGHTENED_SPELL.validate_input(&e, sorcerer, None, None, None),
            "heightened gated below 3 SP"
        );
    }

    /// `roll_save_against_caster` forces disadvantage when the caster
    /// has `HeightenedSpelling` primed, then consumes the prime. A
    /// second save through the helper falls back to the normal save
    /// path. Drive with a seed sweep to verify the disadvantage
    /// distribution drops the failure-side average.
    #[test]
    fn heightened_save_forces_disadvantage_and_consumes_prime() {
        use crate::actions::metamagic::HEIGHTENED_SPELL;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::conditions::Condition;
        use crate::engine::types::AbilityScoreType;

        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let target = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(8, 8), 1, 0)
            .unwrap();
        let actor = e.actors.get_mut(&sorcerer).unwrap();
        actor.give_resource(crate::engine::side_effects::Resource::BonusAction);

        // Prime via the action so we exercise the full plumbing.
        let effects = HEIGHTENED_SPELL.execute(&mut e, sorcerer, None, None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        assert!(
            e.actors[&sorcerer].has_condition(Condition::HeightenedSpelling),
            "prime installed"
        );

        // First save against the caster consumes the prime.
        let _ = e.roll_save_against_caster(target, AbilityScoreType::Wisdom, 15, sorcerer);
        assert!(
            !e.actors[&sorcerer].has_condition(Condition::HeightenedSpelling),
            "first save consumed the prime"
        );

        // Subsequent saves don't carry the disadvantage — the helper
        // collapses to `roll_save` once the prime is gone. We re-call
        // it and expect no leftover state.
        let _ = e.roll_save_against_caster(target, AbilityScoreType::Wisdom, 15, sorcerer);
        assert!(
            !e.actors[&sorcerer].has_condition(Condition::HeightenedSpelling),
            "no prime to consume on the second save"
        );
    }

    /// End-to-end: a heightened Hold Person consumes the prime via the
    /// new caster-aware save path. Verifies the wiring at the spell
    /// side — Hold Person was updated to call
    /// `roll_save_against_caster` rather than `roll_save`.
    #[test]
    fn heightened_hold_person_consumes_prime() {
        use crate::actions::spells::HOLD_PERSON;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::conditions::{Condition, ConditionTimer};

        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let target = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(8, 8), 1, 0)
            .unwrap();
        // Zombies are immune to Charmed but not Stunned — Hold Person's
        // save-side path still runs even though Stunned might or might
        // not bite. We just need the save to be rolled to consume the
        // prime.
        e.actors
            .get_mut(&sorcerer)
            .unwrap()
            .add_condition(Condition::HeightenedSpelling, ConditionTimer::Rounds(2));
        let effects = HOLD_PERSON.side_effects(&mut e, sorcerer, Some(&vec![target]), None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        assert!(
            !e.actors[&sorcerer].has_condition(Condition::HeightenedSpelling),
            "hold person save consumed the heightened prime"
        );
    }

    /// End-to-end regression: a Fireball cast by a sorcerer with
    /// Heightened Spell primed routes the *first* save through the
    /// caster-aware helper and consumes the prime. Previously
    /// `burst_save_damage` in spells.rs used `roll_save` directly,
    /// silently bypassing the prime for ~15 burst spells. The fix
    /// promoted the call to `roll_save_against_caster`.
    #[test]
    fn heightened_fireball_consumes_prime_via_burst_save() {
        use crate::actions::spells::FIREBALL;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::conditions::ConditionTimer;

        let mut e = ei_with_terrain(20, 20, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let _ = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(8, 8), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&sorcerer)
            .unwrap()
            .add_condition(Condition::HeightenedSpelling, ConditionTimer::Rounds(2));
        let effects = FIREBALL.side_effects(
            &mut e,
            sorcerer,
            None,
            Some(&vec![Coordinate::new(8, 8)]),
            None,
        );
        for ef in effects {
            ef.apply(&mut e);
        }
        assert!(
            !e.actors[&sorcerer].has_condition(Condition::HeightenedSpelling),
            "fireball save consumed the heightened prime"
        );
    }

    /// Careful Spell metamagic: costs 1 SP + a Bonus Action and installs
    /// the `CarefulSpelling` prime on the caster. The first AoE that
    /// catches an ally consumes the prime and shields up to CHA-mod
    /// allies from the blast.
    #[test]
    fn careful_spell_spends_one_sp_and_primes() {
        use crate::actions::metamagic::CAREFUL_SPELL;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;

        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let actor = e.actors.get_mut(&sorcerer).unwrap();
        actor.give_resource(crate::engine::side_effects::Resource::BonusAction);
        let sp_before = actor.sorcery_points();
        assert!(sp_before >= 1);

        let effects = CAREFUL_SPELL.execute(&mut e, sorcerer, None, None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        let after = e.actors.get(&sorcerer).unwrap();
        assert_eq!(after.sorcery_points(), sp_before - 1, "1 SP spent");
        assert!(
            after.has_condition(Condition::CarefulSpelling),
            "careful spell prime is installed"
        );
    }

    /// `auto_pass_shielded_allies` consumes the prime and returns ally ids
    /// in the burst when the caster has Careful Spell up. Without the
    /// prime it returns empty. The shield cap is the caster's CHA mod.
    #[test]
    fn careful_spell_shields_allies_in_burst() {
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::conditions::ConditionTimer;

        let mut e = ei_with_terrain(20, 20, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // Three allies clustered near a point so the burst catches them all.
        let a1 = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(8, 8), 0, 0)
            .unwrap();
        let a2 = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(9, 9), 0, 1)
            .unwrap();
        let _a3 = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(10, 10), 0, 2)
            .unwrap();
        // No prime → empty shield list.
        let none = e.auto_pass_shielded_allies(sorcerer, Coordinate::new(9, 9), 3);
        assert!(none.is_empty(), "no prime → no shield");
        assert!(
            !e.actors[&sorcerer].has_condition(Condition::CarefulSpelling),
            "no prime to consume"
        );

        // Install prime + reverify shield list is non-empty.
        e.actors
            .get_mut(&sorcerer)
            .unwrap()
            .add_condition(Condition::CarefulSpelling, ConditionTimer::Rounds(2));
        let shielded = e.auto_pass_shielded_allies(sorcerer, Coordinate::new(9, 9), 3);
        assert!(
            !shielded.is_empty(),
            "primed careful spell shields at least one ally in the burst"
        );
        // Sorcerer template ships CHA 18 (mod +4); CHA-mod cap easily
        // covers all three allies.
        assert!(shielded.contains(&a1));
        assert!(shielded.contains(&a2));
        // Prime consumed by the shield resolution.
        assert!(
            !e.actors[&sorcerer].has_condition(Condition::CarefulSpelling),
            "shielding consumed the prime"
        );
    }

    /// End-to-end: a Careful Spell + Fireball cast spares the ally caught
    /// in the burst — the ally takes zero damage while the enemy still
    /// rolls a save and takes the blast. The prime is consumed by the
    /// cast.
    #[test]
    fn careful_fireball_spares_allies() {
        use crate::actions::spells::FIREBALL;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::conditions::ConditionTimer;

        let mut e = ei_with_terrain(20, 20, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let ally = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(8, 8), 0, 0)
            .unwrap();
        let enemy = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(9, 9), 1, 0)
            .unwrap();
        let ally_hp_before = e.actors[&ally].hitpoints();
        let enemy_hp_before = e.actors[&enemy].hitpoints();

        e.actors
            .get_mut(&sorcerer)
            .unwrap()
            .add_condition(Condition::CarefulSpelling, ConditionTimer::Rounds(2));
        let effects = FIREBALL.side_effects(
            &mut e,
            sorcerer,
            None,
            Some(&vec![Coordinate::new(8, 8)]),
            None,
        );
        for ef in effects {
            ef.apply(&mut e);
        }
        let ally_hp_after = e.actors[&ally].hitpoints();
        let enemy_hp_after = e.actors[&enemy].hitpoints();

        // Ally completely shielded; enemy still takes damage.
        assert_eq!(
            ally_hp_after, ally_hp_before,
            "careful spell zeros ally damage"
        );
        assert!(
            enemy_hp_after < enemy_hp_before,
            "enemy still takes the blast"
        );
        // Prime consumed by the Fireball cast.
        assert!(
            !e.actors[&sorcerer].has_condition(Condition::CarefulSpelling),
            "fireball consumed the careful spell prime"
        );
    }

    /// Distant Spell metamagic: costs 1 SP + a Bonus Action and installs
    /// the `DistantSpelling` prime on the caster. The first ranged action
    /// (reach > 2) consumes the prime and benefits from doubled reach.
