    /// `extra_spell_reach` returns the base reach as a bonus (doubling
    /// the effective range) when DistantSpelling is up and base reach is
    /// > 2 (ranged); melee / touch reach (<= 2) gets no bonus.
    #[test]
    fn extra_spell_reach_doubles_only_ranged() {
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::conditions::ConditionTimer;

        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // No prime → no bonus.
        let actor = e.actors.get(&sorcerer).unwrap();
        assert_eq!(actor.extra_spell_reach(48), 0, "no prime → no bonus");
        assert_eq!(actor.extra_spell_reach(1), 0, "no prime → no bonus on melee");

        // Install prime.
        e.actors
            .get_mut(&sorcerer)
            .unwrap()
            .add_condition(Condition::DistantSpelling, ConditionTimer::Rounds(2));
        let primed = e.actors.get(&sorcerer).unwrap();
        // Melee weapons (reach 1) get nothing.
        assert_eq!(primed.extra_spell_reach(1), 0, "melee gets no bonus");
        // Polearm reach (2) gets nothing — extra_melee_reach handles those.
        assert_eq!(primed.extra_spell_reach(2), 0, "polearm reach unchanged");
        // Ranged spells double via the bonus.
        assert_eq!(primed.extra_spell_reach(24), 24, "60 ft → 120 ft");
        assert_eq!(primed.extra_spell_reach(48), 48, "120 ft → 240 ft");
    }

    /// `consume_distant_spell` is a no-op when no prime is up, removes
    /// the condition when one is, and emits a log line in the latter
    /// case. Mirrors the consume-on-trigger pattern used by Empowered /
    /// Heightened Spell.
    #[test]
    fn consume_distant_spell_clears_prime_and_logs() {
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::conditions::ConditionTimer;

        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // No-op when no prime is up.
        let log_len_before = e.messages().len();
        e.consume_distant_spell(sorcerer);
        assert_eq!(
            e.messages().len(),
            log_len_before,
            "no log line when nothing to consume"
        );

        // Install + consume.
        e.actors
            .get_mut(&sorcerer)
            .unwrap()
            .add_condition(Condition::DistantSpelling, ConditionTimer::Rounds(2));
        e.consume_distant_spell(sorcerer);
        assert!(
            !e.actors[&sorcerer].has_condition(Condition::DistantSpelling),
            "prime consumed"
        );
    }

    /// Twinned Spell prime installs the condition without spending SP
    /// up front (RAW: SP is paid at consume time, when the spell's
    /// level is known). The prime is gated on a 1 SP floor — a
    /// sorcerer with an empty pool can't open the prime.
    #[test]
    fn twinned_spell_primes_without_eager_sp_debit() {
        use crate::actions::metamagic::TWINNED_SPELL;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;

        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let actor = e.actors.get_mut(&sorcerer).unwrap();
        actor.give_resource(crate::engine::side_effects::Resource::BonusAction);
        let sp_before = actor.sorcery_points();
        assert!(sp_before >= 1, "template ships SP for the test");

        let effects = TWINNED_SPELL.execute(&mut e, sorcerer, None, None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        let after = e.actors.get(&sorcerer).unwrap();
        // RAW: SP is paid at consume time, not at the prime. The cost
        // here is just the bonus action.
        assert_eq!(
            after.sorcery_points(),
            sp_before,
            "prime alone does not debit SP"
        );
        assert!(
            after.has_condition(Condition::TwinnedSpelling),
            "twinned prime is installed"
        );
    }

    /// Twinned Spell prime is blocked when the sorcerer has no SP — the
    /// 1 SP floor cost RAW (minimum cost when the next spell fires)
    /// means the prime would never pay off.
    #[test]
    fn twinned_spell_blocked_without_sp() {
        use crate::actions::metamagic::TWINNED_SPELL;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;

        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let actor = e.actors.get_mut(&sorcerer).unwrap();
        actor.give_resource(crate::engine::side_effects::Resource::BonusAction);
        while actor.spend_sorcery_point() {}
        assert_eq!(actor.sorcery_points(), 0);
        assert!(
            !TWINNED_SPELL.validate_input(&e, sorcerer, None, None, None),
            "twinned gated by empty SP pool"
        );
    }

    /// End-to-end: a Twinned Fire Bolt cast on one enemy re-fires its
    /// side_effects on a second enemy in range. Verifies the wiring
    /// from action_template.rs's execute() → consume_twinned_spell →
    /// re-issued side_effects path.
    #[test]
    fn twinned_fire_bolt_hits_two_enemies() {
        use crate::actions::spells::FIRE_BOLT;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::conditions::ConditionTimer;

        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let zombie_a = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(5, 5), 1, 0)
            .unwrap();
        let zombie_b = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(6, 6), 1, 1)
            .unwrap();
        // Sorcerer needs an Action + twinned prime for this fight.
        let actor = e.actors.get_mut(&sorcerer).unwrap();
        actor.give_resource(crate::engine::side_effects::Resource::Action);
        actor.add_condition(Condition::TwinnedSpelling, ConditionTimer::Rounds(2));
        let sp_before = actor.sorcery_points();
        assert!(sp_before >= 1);

        let hp_a_before = e.actors[&zombie_a].hitpoints();
        let hp_b_before = e.actors[&zombie_b].hitpoints();

        // Cast Fire Bolt at zombie_a — the twin should fire onto zombie_b.
        // Use a tight seed to keep the test deterministic.
        e.roller = crate::engine::dice::FastRandRoller::with_seed(42);
        let effects = FIRE_BOLT.execute(
            &mut e,
            sorcerer,
            Some(&vec![zombie_a]),
            None,
            None,
        );
        for ef in effects {
            ef.apply(&mut e);
        }

        // Cantrip → 1 SP twin debit.
        let after = e.actors.get(&sorcerer).unwrap();
        assert_eq!(
            after.sorcery_points(),
            sp_before - 1,
            "twin consumed 1 SP for a cantrip"
        );
        assert!(
            !after.has_condition(Condition::TwinnedSpelling),
            "twinned prime consumed"
        );

        // Verify *something* happened to one of the zombies. Because the
        // attack roll is involved, we can't guarantee both hit — but the
        // important invariant is that both were possible targets and
        // the second one got an attack roll.
        let total_damage = (hp_a_before.saturating_sub(e.actors[&zombie_a].hitpoints()))
            + (hp_b_before.saturating_sub(e.actors[&zombie_b].hitpoints()));
        // With a fixed seed and AC 8 zombies, at least one bolt should
        // land. This is a load-bearing assertion that the side_effects
        // path was re-issued; the exact value is seed-dependent.
        assert!(
            total_damage > 0,
            "at least one fire bolt should hit either zombie"
        );
    }

    /// Twinned Spell rejects multi-target schemas: a SinglePoint or
    /// Burst-shape action like Fireball or Sacred Burst doesn't satisfy
    /// the "targets only one creature" RAW gate, so the consume site
    /// short-circuits and the prime stays up for a future single-target
    /// cast.
    #[test]
    fn twinned_spell_does_not_consume_on_burst_spell() {
        use crate::actions::spells::FIREBALL;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::conditions::ConditionTimer;

        let mut e = ei_with_terrain(20, 20, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let _ = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(10, 10), 1, 0)
            .unwrap();
        let actor = e.actors.get_mut(&sorcerer).unwrap();
        actor.give_resource(crate::engine::side_effects::Resource::Action);
        actor.add_condition(Condition::TwinnedSpelling, ConditionTimer::Rounds(2));
        let sp_before = actor.sorcery_points();

        // Cast a Burst-targeting spell (Fireball aimed at a point).
        let effects = FIREBALL.execute(
            &mut e,
            sorcerer,
            None,
            Some(&vec![Coordinate::new(10, 10)]),
            None,
        );
        for ef in effects {
            ef.apply(&mut e);
        }
        let after = e.actors.get(&sorcerer).unwrap();
        assert_eq!(
            after.sorcery_points(),
            sp_before,
            "burst spell does not pay twin SP"
        );
        assert!(
            after.has_condition(Condition::TwinnedSpelling),
            "prime remains for a future single-target cast"
        );
    }

    /// Twinned Spell quietly degrades when no second target exists in
    /// range: a solo enemy is the original target, so the prime stays up
    /// and no SP is wasted (RAW: the SP cost is only paid if a second
    /// target is actually engaged).
    #[test]
    fn twinned_spell_no_op_with_solo_enemy() {
        use crate::actions::spells::FIRE_BOLT;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::conditions::ConditionTimer;

        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let solo = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(5, 5), 1, 0)
            .unwrap();
        let actor = e.actors.get_mut(&sorcerer).unwrap();
        actor.give_resource(crate::engine::side_effects::Resource::Action);
        actor.add_condition(Condition::TwinnedSpelling, ConditionTimer::Rounds(2));
        let sp_before = actor.sorcery_points();

        let effects = FIRE_BOLT.execute(&mut e, sorcerer, Some(&vec![solo]), None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        let after = e.actors.get(&sorcerer).unwrap();
        assert_eq!(
            after.sorcery_points(),
            sp_before,
            "no second target → no SP burnt"
        );
        assert!(
            after.has_condition(Condition::TwinnedSpelling),
            "prime stays up so the next single-target cast can twin"
        );
    }

    /// Twinned Spell debits more SP for leveled spells. Inflict Wounds is
    /// a level-1 spell — twinning it at base cost = max(1, 1) = 1 SP, but
    /// upcasting to lv3 via the CastLevel override should bump the
    /// twin cost to 3 SP (RAW).
    #[test]
    fn twinned_spell_upcast_scales_sp_cost() {
        use crate::actions::spells::INFLICT_WOUNDS;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::conditions::ConditionTimer;
        use crate::engine::action_overrides::ActionOverride;
        use std::collections::HashSet;

        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        // Touch-range spell, so place both zombies adjacent so both are
        // valid twin targets.
        let z1 = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(6, 5), 1, 0)
            .unwrap();
        let _ = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(5, 6), 1, 1)
            .unwrap();
        let actor = e.actors.get_mut(&sorcerer).unwrap();
        actor.give_resource(crate::engine::side_effects::Resource::Action);
        // Make sure the upcast slot is available.
        actor.spell_slot_manager.increase_max_spell_slot(3, 1);
        actor.add_condition(Condition::TwinnedSpelling, ConditionTimer::Rounds(2));
        let sp_before = actor.sorcery_points();
        assert!(sp_before >= 3, "need >= 3 SP for a lv3 twin");

        let mut overrides = HashSet::new();
        overrides.insert(ActionOverride::CastLevel(3));

        let effects = INFLICT_WOUNDS.execute(
            &mut e,
            sorcerer,
            Some(&vec![z1]),
            None,
            Some(&overrides),
        );
        for ef in effects {
            ef.apply(&mut e);
        }
        let after = e.actors.get(&sorcerer).unwrap();
        // Twin debit = max(1, 3) = 3 SP for an upcast lv3 cast.
        assert_eq!(
            after.sorcery_points(),
            sp_before - 3,
            "twin cost scales with the cast level"
        );
        assert!(
            !after.has_condition(Condition::TwinnedSpelling),
            "twinned prime consumed by the lv3 cast"
        );
    }

    /// Extended Spell prime installs the condition, debits 1 SP eagerly
    /// (mirroring Empowered / Heightened / Careful / Distant), and gates
    /// on a non-empty pool. Re-priming while already extended is a no-op
    /// per the shared metamagic validator.
    #[test]
    fn extended_spell_action_spends_one_sp_and_primes() {
        use crate::actions::metamagic::EXTENDED_SPELL;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;

        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let actor = e.actors.get_mut(&sorcerer).unwrap();
        actor.give_resource(crate::engine::side_effects::Resource::BonusAction);
        let sp_before = actor.sorcery_points();
        assert!(sp_before >= 1, "template ships SP for the test");

        let effects = EXTENDED_SPELL.execute(&mut e, sorcerer, None, None, None);
        assert!(!effects.is_empty(), "extended spell should queue an effect");
        for ef in effects {
            ef.apply(&mut e);
        }
        let after = e.actors.get(&sorcerer).unwrap();
        assert_eq!(after.sorcery_points(), sp_before - 1, "1 SP spent eagerly");
        assert!(
            after.has_condition(Condition::ExtendedSpelling),
            "extended prime installed"
        );

        // Re-prime is blocked while the prime is up.
        assert!(
            !EXTENDED_SPELL.validate_input(&e, sorcerer, None, None, None),
            "no-stack while ExtendedSpelling is already installed"
        );
    }

    /// End-to-end: casting Mage Armor (`Rounds(100)`) while extended
    /// produces a `Rounds(200)` install (RAW: doubled, capped at the
    /// engine's `EXTENDED_SPELL_MAX_ROUNDS`). The prime is consumed.
    #[test]
    fn extended_mage_armor_doubles_timer_and_consumes_prime() {
        use crate::actions::spells::MAGE_ARMOR;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::conditions::{Condition, ConditionTimer};

        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let actor = e.actors.get_mut(&sorcerer).unwrap();
        actor.add_condition(Condition::ExtendedSpelling, ConditionTimer::Rounds(2));
        let effects = MAGE_ARMOR.execute(&mut e, sorcerer, None, None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        let after = e.actors.get(&sorcerer).unwrap();
        assert!(
            !after.has_condition(Condition::ExtendedSpelling),
            "extended prime consumed"
        );
        let timer = after
            .conditions()
            .get(&Condition::MageArmored)
            .copied()
            .expect("mage armor installed");
        assert_eq!(
            timer,
            ConditionTimer::Rounds(200),
            "mage armor's base 100-round timer doubled to 200 (engine cap)"
        );
    }

    /// Casting a short-duration buff (`UntilStartOfNextTurn`) like Shield
    /// while extended does NOT consume the prime — RAW: Extended Spell
    /// only affects spells with a duration of 1 minute or longer.
    #[test]
    fn extended_spell_skips_short_duration_buff() {
        use crate::actions::spells::SHIELD;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::conditions::{Condition, ConditionTimer};

        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let actor = e.actors.get_mut(&sorcerer).unwrap();
        actor.give_resource(crate::engine::side_effects::Resource::Reaction);
        actor.add_condition(Condition::ExtendedSpelling, ConditionTimer::Rounds(2));
        let effects = SHIELD.execute(&mut e, sorcerer, None, None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        let after = e.actors.get(&sorcerer).unwrap();
        assert!(
            after.has_condition(Condition::ExtendedSpelling),
            "short-duration buff doesn't burn the extended prime"
        );
        // Shield is still installed — it's not blocked, just not extended.
        assert!(
            after.has_condition(Condition::Shielded),
            "shield still applied at base timer"
        );
        let timer = after
            .conditions()
            .get(&Condition::Shielded)
            .copied()
            .expect("shield installed");
        assert_eq!(
            timer,
            ConditionTimer::UntilStartOfNextTurn,
            "short-duration timer untouched"
        );
    }

    /// Twinned + Extended interaction: Extended Spell affects the
    /// *spell*, so both the primary and twinned target see the doubled
    /// duration RAW. Direct test on the helper rather than through a
    /// real spell — Twinning a concentration spell has a separately
    /// documented limitation (the second `StartConcentration` scrubs
    /// the first target's bound condition), and isolating the timer
    /// path keeps this assertion focused on the extend-propagation
    /// invariant rather than the concentration semantics.
    #[test]
    fn extended_plus_twinned_applies_doubled_timer_to_both_targets() {
        use crate::conditions::ConditionTimer;
        use crate::engine::side_effects::{
            ApplicableSideEffect, ApplyCondition, extend_side_effect_timers,
        };

        // Simulate two separately-built side_effects vecs (the original
        // cast's effects and the twin's re-issued effects).
        let mut original: Vec<Box<dyn ApplicableSideEffect>> = vec![Box::new(ApplyCondition {
            actor_id: 1,
            condition: Condition::HuntersMarked,
            timer: ConditionTimer::Rounds(10),
        })];
        let mut twin: Vec<Box<dyn ApplicableSideEffect>> = vec![Box::new(ApplyCondition {
            actor_id: 2,
            condition: Condition::HuntersMarked,
            timer: ConditionTimer::Rounds(10),
        })];

        // Extend the original — returns true.
        assert!(extend_side_effect_timers(&mut original));
        // Propagate to the twin — returns true.
        assert!(extend_side_effect_timers(&mut twin));

        // Apply both and verify the doubled timer landed on each target.
        let mut e = ei_with_terrain(15, 15, &[]);
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        let zombie_a = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(2, 2), 1, 0)
            .unwrap();
        let zombie_b = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(4, 2), 1, 1)
            .unwrap();
        // Re-assign the targets to live ids and re-build.
        let mut original: Vec<Box<dyn ApplicableSideEffect>> = vec![Box::new(ApplyCondition {
            actor_id: zombie_a,
            condition: Condition::HuntersMarked,
            timer: ConditionTimer::Rounds(10),
        })];
        let mut twin: Vec<Box<dyn ApplicableSideEffect>> = vec![Box::new(ApplyCondition {
            actor_id: zombie_b,
            condition: Condition::HuntersMarked,
            timer: ConditionTimer::Rounds(10),
        })];
        assert!(extend_side_effect_timers(&mut original));
        assert!(extend_side_effect_timers(&mut twin));
        for ef in original.into_iter().chain(twin) {
            ef.apply(&mut e);
        }
        for zid in [zombie_a, zombie_b] {
            let timer = e.actors[&zid]
                .conditions()
                .get(&Condition::HuntersMarked)
                .copied()
                .unwrap_or_else(|| panic!("zombie {} should be HuntersMarked", zid));
            assert_eq!(
                timer,
                ConditionTimer::Rounds(20),
                "twin target also gets the extended duration"
            );
        }
    }

    /// Verify the Twinned + Transmuted propagation: the same `new_type`
    /// returned by `consume_transmuted_spell` on the primary cast can be
    /// fed back through `remap_side_effect_damage_types` on the twin's
    /// separately-built side_effects so both targets see the same remap.
    #[test]
    fn transmuted_plus_twinned_remaps_both_targets() {
        use crate::engine::side_effects::{
            ApplicableSideEffect, DealDamage, remap_side_effect_damage_types,
        };
        use crate::engine::types::DamageType;

        let mut original: Vec<Box<dyn ApplicableSideEffect>> = vec![Box::new(DealDamage {
            actor_id: 1,
            amount: 10,
            damage_type: DamageType::Fire,
        })];
        let mut twin: Vec<Box<dyn ApplicableSideEffect>> = vec![Box::new(DealDamage {
            actor_id: 2,
            amount: 10,
            damage_type: DamageType::Fire,
        })];
        // Remap the original cast to Cold — returns true.
        assert!(remap_side_effect_damage_types(&mut original, DamageType::Cold));
        // Propagate to the twin — returns true.
        assert!(remap_side_effect_damage_types(&mut twin, DamageType::Cold));
        // Non-elemental damage in either vec leaves the prime up; the
        // existing path returns false. Confirm the no-op semantic.
        let mut force_only: Vec<Box<dyn ApplicableSideEffect>> = vec![Box::new(DealDamage {
            actor_id: 3,
            amount: 10,
            damage_type: DamageType::Force,
        })];
        assert!(!remap_side_effect_damage_types(&mut force_only, DamageType::Cold));
    }

