    /// Potion of Sanctuary: bonus action; self-installs Sanctuary for
    /// 10 rounds. Mirrors the other self-condition consumable tests
    /// (e.g. Potion of Mage Armor) — confirms the install lands and
    /// the consumable rejects re-drink when already up so the potion
    /// isn't burned on a no-op refresh.
    #[test]
    fn potion_of_sanctuary_installs_sanctuary_and_rejects_refresh() {
        use crate::actions::action_template::ActionExecutionInfo;
        use crate::actions::item_actions::DRINK_POTION_OF_SANCTUARY;
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::conditions::Condition;
        use crate::items::item_template::POTION_OF_SANCTUARY;

        let mut e = ei_with_terrain(10, 10, &[]);
        let fighter = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // Hand the fighter two potions so the refresh-reject path has
        // a second consumable to (correctly) refuse.
        e.actors
            .get_mut(&fighter)
            .unwrap()
            .pickup_item(&POTION_OF_SANCTUARY);
        e.actors
            .get_mut(&fighter)
            .unwrap()
            .pickup_item(&POTION_OF_SANCTUARY);
        let aei = ActionExecutionInfo::new(
            &DRINK_POTION_OF_SANCTUARY,
            fighter,
            None,
            None,
            None,
        );
        assert!(aei.validate(&e));
        e.push_action(aei);
        e.process_stack();
        assert!(e.actors[&fighter].has_condition(Condition::Sanctuary));
        // One potion consumed; the second should now reject (the buff
        // is already up — refresh would waste the consumable).
        assert_eq!(
            e.actors[&fighter].items().len(),
            1,
            "first drink should consume one potion"
        );
        let refresh = ActionExecutionInfo::new(
            &DRINK_POTION_OF_SANCTUARY,
            fighter,
            None,
            None,
            None,
        );
        assert!(
            !refresh.validate(&e),
            "drinking again while Sanctified should reject"
        );
    }

    /// 5e Wild Magic Surge wiring: the `Action::execute` chokepoint
    /// forwards the spell-slot level sniffed off the cost vec into the
    /// surge trigger. We verify the path end-to-end by casting Magic
    /// Missile (a level-1 sorcerer spell) repeatedly and looking for
    /// the surge log line. Confirms `execute()` actually calls the
    /// trigger — not just that the trigger is callable in isolation.
    #[test]
    fn wild_magic_surge_fires_through_action_execute() {
        use crate::actions::spells::MAGIC_MISSILE;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        let trials = 400u64;
        let mut surge_count = 0u32;
        for seed in 0..trials {
            let mut e = ei_with_terrain(15, 15, &[]);
            let sorcerer = e
                .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            let zombie = e
                .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(5, 5), 1, 0)
                .unwrap();
            // Grant the sorcerer an Action + a level-1 slot so the cast
            // resolves cleanly. Reseed after instantiation so the surge
            // d20 is independent of HP / initiative rolls.
            let actor = e.actors.get_mut(&sorcerer).unwrap();
            actor.give_resource(crate::engine::side_effects::Resource::Action);
            actor.spell_slot_manager.restore_spell_slots();
            e.roller = crate::engine::dice::FastRandRoller::with_seed(seed);
            let log_before = e.messages().len();
            let effects =
                MAGIC_MISSILE.execute(&mut e, sorcerer, Some(&vec![zombie]), None, None);
            for ef in effects {
                ef.apply(&mut e);
            }
            let surge_logged = e.messages()[log_before..]
                .iter()
                .any(|m| m.contains("surges with wild magic"));
            if surge_logged {
                surge_count += 1;
            }
        }
        assert!(
            surge_count > 0,
            "wild magic surge never fired across {} Magic Missile casts \
             — execute() wiring broken?",
            trials
        );
    }

    /// Steady Aim: validates only when the rogue has full movement, then
    /// drains movement and installs the Helped one-shot.
    #[test]
    fn steady_aim_primes_helped_and_zeros_movement() {
        use crate::actions::class_features::STEADY_AIM;
        use crate::actors::creatures::rogues::ROGUE_TEMPLATE;
        use crate::conditions::Condition;
        use crate::engine::side_effects::Resource;
        let mut e = ei_with_terrain(20, 20, &[]);
        let rogue = e
            .instantiate_creature(&ROGUE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // Top-of-turn: full movement, BonusAction available, no prime.
        e.actors.get_mut(&rogue).unwrap().reset_for_new_round();
        let speed_before = e.actors[&rogue].speed();
        assert!(speed_before > 0.0);
        assert!(STEADY_AIM.custom_validate_input(&e, rogue, None, None, None));
        let effects = STEADY_AIM.side_effects(&mut e, rogue, None, None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        assert!(e.actors[&rogue].has_condition(Condition::Helped));
        assert_eq!(e.actors[&rogue].remaining_movement(), 0.0);
        // Re-validate: blocked because (a) Helped already primed and
        // (b) movement is drained (the second clause matters once Helped
        // expires next turn).
        assert!(!STEADY_AIM.custom_validate_input(&e, rogue, None, None, None));

        // After a fresh round, full movement returns but if the rogue has
        // taken even one tile of movement, Steady Aim won't validate.
        let actor = e.actors.get_mut(&rogue).unwrap();
        actor.reset_for_new_round();
        actor.consume_resource(Resource::Movement(2.5));
        assert!(actor.has_moved_this_turn());
        assert!(!STEADY_AIM.custom_validate_input(&e, rogue, None, None, None));
    }

    /// Bend Luck: a hit against the sorcerer can flip to a miss when the
    /// d4 penalty drags the total below AC. Verifies the SP and reaction
    /// debits land and the swing is converted to a miss in the log.
    #[test]
    fn bend_luck_flips_hit_to_miss_and_spends_resources() {
        use crate::actions::monster_attacks::SCIMITAR;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::engine::side_effects::Resource;
        let mut bent_fires = 0u32;
        let mut bent_to_miss = 0u32;
        let trials = 200u64;
        for seed in 0..trials {
            let mut e = ei_with_terrain(15, 15, &[]);
            // Sorcerer template carries BEND_LUCK_TAG and starts with 6 SP.
            let sorcerer = e
                .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            // Zombie close enough to swing scimitar (melee reach 1 tile).
            let zombie = e
                .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(4, 2), 1, 0)
                .unwrap();
            // Reseed after instantiation so the per-trial RNG drives the
            // d20 / d4 deterministically.
            e.roller = crate::engine::dice::FastRandRoller::with_seed(seed);
            e.actors.get_mut(&sorcerer).unwrap().reset_for_new_round();
            e.actors.get_mut(&zombie).unwrap().reset_for_new_round();
            let sp_before = e.actors[&sorcerer].sorcery_points();
            let log_before = e.messages().len();
            let effects =
                SCIMITAR.side_effects(&mut e, zombie, Some(&vec![sorcerer]), None, None);
            for ef in effects {
                ef.apply(&mut e);
            }
            let bent_log = e.messages()[log_before..]
                .iter()
                .any(|m| m.contains("bend luck:"));
            if bent_log {
                bent_fires += 1;
                // SP must have dropped by 2 and reaction must be spent.
                let sp_after = e.actors[&sorcerer].sorcery_points();
                assert_eq!(sp_after, sp_before - 2, "bend luck should spend 2 SP");
                assert!(
                    !e.actors[&sorcerer].can_consume_resource(Resource::Reaction),
                    "bend luck should burn the reaction"
                );
                let miss_logged = e.messages()[log_before..]
                    .iter()
                    .any(|m| m.contains("\u{2014} miss"));
                if miss_logged {
                    bent_to_miss += 1;
                }
            }
        }
        assert!(
            bent_fires > 0,
            "bend luck never fired across {} attack swings",
            trials
        );
        assert!(
            bent_to_miss > 0,
            "bend luck never flipped a hit to a miss across {} trials \
             (fires: {})",
            trials,
            bent_fires
        );
    }

    /// Bend Luck: the sorcerer with 0 SP can't bend, even if the attack
    /// would hit and a reaction is available.
    #[test]
    fn bend_luck_skips_when_out_of_sp() {
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        let mut e = ei_with_terrain(10, 10, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // Drain all sorcery points.
        let max_sp = e.actors[&sorcerer].sorcery_points();
        e.actors
            .get_mut(&sorcerer)
            .unwrap()
            .spend_sorcery_points(max_sp);
        // Fake attacker id (sorcerer self-targeting is fine for the gate
        // check — the helper short-circuits on resource gates first).
        let penalty = e.apply_bend_luck_penalty(sorcerer, sorcerer);
        assert_eq!(penalty, 0, "0 SP should suppress Bend Luck");
    }

    /// Bend Luck's RAW "another creature you can see" clause routes
    /// through the shared `viewer_can_see` helper — a Blinded sorcerer
    /// can't spend Bend Luck. Sibling to the Warding Flare / Uncanny
    /// Dodge / Deflect Missiles sight-gate correctness fixes on the
    /// same helper — pre-refactor Bend Luck only gated on `!Blinded`
    /// (which happened to also cover the blinded-sorcerer branch), but
    /// the shared helper is the durable answer since a future
    /// concealment-fold (Fog Cloud imposing Blinded via a burst) rides
    /// through it uniformly.
    #[test]
    fn bend_luck_skips_when_sorcerer_is_blinded() {
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::conditions::{Condition, ConditionTimer};
        let mut e = ei_with_terrain(10, 10, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let zombie = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(4, 2), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&sorcerer)
            .unwrap()
            .add_condition(Condition::Blinded, ConditionTimer::Permanent);
        let penalty = e.apply_bend_luck_penalty(sorcerer, zombie);
        assert_eq!(penalty, 0, "Blinded sorcerer cannot Bend Luck");
    }

    /// Bend Luck's RAW "another creature you can see" clause also
    /// bounces an Invisible attacker — the sorcerer must actually see
    /// the attacker per RAW, and an Invisible attacker without a
    /// piercing sense (Truesight / Feral Senses / Blindsense inside
    /// range) is unseeable. Pre-refactor Bend Luck only checked
    /// `Blinded` and let an Invisible attacker still draw the 2 SP +
    /// reaction spend.
    #[test]
    fn bend_luck_skips_when_attacker_is_invisible_and_sorcerer_lacks_piercing_sense() {
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::conditions::{Condition, ConditionTimer};
        let mut e = ei_with_terrain(10, 10, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let zombie = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(4, 2), 1, 0)
            .unwrap();
        // Zombie has no Truesight / Feral Senses / Blindsense in
        // range; sorcerer likewise doesn't pierce illusions.
        e.actors
            .get_mut(&zombie)
            .unwrap()
            .add_condition(Condition::Invisible, ConditionTimer::Permanent);
        let penalty = e.apply_bend_luck_penalty(sorcerer, zombie);
        assert_eq!(
            penalty, 0,
            "Invisible unseeable attacker cannot draw the Bend Luck reaction charge"
        );
    }

    /// Search action: a successful Perception check reveals an enemy
    /// hiding within line-of-sight. We pin the d20 with a seeded roller
    /// so the test is deterministic.
    #[test]
    fn search_reveals_hidden_enemy() {
        use crate::actions::default_actions::SEARCH;
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::conditions::{Condition, ConditionTimer};
        let mut e = ei_with_terrain(15, 15, &[]);
        let searcher = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let hider = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(5, 5), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&hider)
            .unwrap()
            .add_condition(Condition::Hidden, ConditionTimer::Permanent);
        // Drive the perception roll high so it definitely beats the
        // zombie's 12 + DEX(-2) = 10 stealth DC. The roller is seeded;
        // sweep until we get a search that reveals.
        let mut revealed = false;
        for _ in 0..50 {
            // Re-add the Hidden flag each iteration so a failed sweep
            // doesn't leave it stripped.
            e.actors
                .get_mut(&hider)
                .unwrap()
                .add_condition(Condition::Hidden, ConditionTimer::Permanent);
            let effects = SEARCH.side_effects(&mut e, searcher, None, None, None);
            for ef in effects {
                ef.apply(&mut e);
            }
            if !e.actors[&hider].has_condition(Condition::Hidden) {
                revealed = true;
                break;
            }
        }
        assert!(revealed, "search should eventually reveal the hidden enemy");
    }

    /// Search action: a blinded searcher auto-fails — no perception
    /// roll, no reveal.
    #[test]
    fn search_blinded_auto_fails() {
        use crate::actions::default_actions::SEARCH;
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::conditions::{Condition, ConditionTimer};
        let mut e = ei_with_terrain(15, 15, &[]);
        let searcher = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let hider = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(5, 5), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&hider)
            .unwrap()
            .add_condition(Condition::Hidden, ConditionTimer::Permanent);
        e.actors
            .get_mut(&searcher)
            .unwrap()
            .add_condition(Condition::Blinded, ConditionTimer::Permanent);
        let effects = SEARCH.side_effects(&mut e, searcher, None, None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        // Blind searcher returns no effects, hider stays hidden.
        assert!(
            e.actors[&hider].has_condition(Condition::Hidden),
            "blinded searcher should not reveal"
        );
    }

    /// Cunning Strike (Poison) bonus action installs the prime condition
    /// on the rogue and is mutually exclusive with the other variants.
    #[test]
    fn cunning_strike_poison_primes_rogue() {
        use crate::actions::class_features::{
            CUNNING_STRIKE_POISON, CUNNING_STRIKE_TRIP,
        };
        use crate::actors::creatures::rogues::ROGUE_TEMPLATE;
        use crate::conditions::Condition;
        let mut e = ei_with_terrain(10, 10, &[]);
        let rogue = e
            .instantiate_creature(&ROGUE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let aei = ActionExecutionInfo::new(&*CUNNING_STRIKE_POISON, rogue, None, None, None);
        assert!(aei.validate(&e), "fresh rogue should be able to prime");
        let effects = CUNNING_STRIKE_POISON.side_effects(&mut e, rogue, None, None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        assert!(e.actors[&rogue].has_condition(Condition::CunningStrikePoison));
        // Second variant should be refused while the first prime is up.
        let aei2 = ActionExecutionInfo::new(&*CUNNING_STRIKE_TRIP, rogue, None, None, None);
        assert!(
            !aei2.validate(&e),
            "second prime should be refused while another is active"
        );
    }

    /// Cunning Strike (Daze) requires the rogue's sneak attack pool to
    /// hold at least 2 dice. Level-1 rogues only have 1d6, so the prime
    /// is refused; promoting to lv3+ unlocks it.
    #[test]
    fn cunning_strike_daze_gated_on_sneak_pool() {
        use crate::actions::class_features::CUNNING_STRIKE_DAZE;
        use crate::actors::creatures::rogues::ROGUE_TEMPLATE;
        let mut e = ei_with_terrain(10, 10, &[]);
        let rogue = e
            .instantiate_creature(&ROGUE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // Rogue spawns at level 1 → sneak pool 1d6 → Daze refused.
        let aei = ActionExecutionInfo::new(&*CUNNING_STRIKE_DAZE, rogue, None, None, None);
        assert!(!aei.validate(&e), "level-1 rogue: pool too small for Daze");
        // Bump the rogue to level 3 (sneak pool 2d6). Use the public
        // level-up path so the test doesn't poke at private fields.
        e.actors.get_mut(&rogue).unwrap().award_xp(10_000);
        let mut roller = crate::engine::dice::FastRandRoller::with_seed(0);
        while e
            .actors
            .get_mut(&rogue)
            .unwrap()
            .try_level_up(&mut roller)
            .is_some()
            && e.actors[&rogue].level() < 3
        {}
        // Re-validate — now the daze pool gate should pass.
        let aei2 = ActionExecutionInfo::new(&*CUNNING_STRIKE_DAZE, rogue, None, None, None);
        assert!(aei2.validate(&e), "level-3 rogue: Daze unlocked");
    }

    /// End-to-end: with the Cunning Strike (Withdraw) prime up and a
    /// sneak-eligible hit landing, the rogue ends the swing with a
    /// fresh Movement budget AND the Disengaging condition installed.
    /// The Disengaging install is the load-bearing OA-bypass.
    #[test]
    fn cunning_strike_withdraw_grants_oa_free_movement() {
        use crate::actions::class_attacks::ROGUE_SHORTSWORD;
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::actors::creatures::rogues::ROGUE_TEMPLATE;
        use crate::conditions::{Condition, ConditionTimer};
        let mut withdraw_fired = false;
        for seed in 0..200 {
            let mut e = ei_seeded(15, 15, &[], seed);
            let rogue = e
                .instantiate_creature(&ROGUE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            // Level the rogue to 3 so the sneak pool can spare a die.
            e.actors.get_mut(&rogue).unwrap().award_xp(10_000);
            let mut roller = crate::engine::dice::FastRandRoller::with_seed(seed);
            while e.actors[&rogue].level() < 3
                && e.actors
                    .get_mut(&rogue)
                    .unwrap()
                    .try_level_up(&mut roller)
                    .is_some()
            {}
            let _ally = e
                .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(4, 3), 0, 0)
                .unwrap();
            let target = e
                .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(3, 2), 1, 0)
                .unwrap();
            let max = e.actors[&target].max_hitpoints();
            e.actors.get_mut(&target).unwrap().heal(max);
            e.actors.get_mut(&rogue).unwrap().add_condition(
                Condition::CunningStrikeWithdraw,
                ConditionTimer::UntilStartOfNextTurn,
            );
            let targets = vec![target];
            let effects = ROGUE_SHORTSWORD.side_effects(
                &mut e,
                rogue,
                Some(&targets),
                None,
                None,
            );
            for ef in effects {
                ef.apply(&mut e);
            }
            // Withdraw is no-save: if the prime consumed, the rogue must
            // hold Disengaging now and the prime must be gone.
            let prime_consumed = !e.actors[&rogue].has_condition(Condition::CunningStrikeWithdraw);
            let disengaging = e
                .actors
                .get(&rogue)
                .is_some_and(|a| a.has_condition(Condition::Disengaging));
            if prime_consumed && disengaging {
                withdraw_fired = true;
                break;
            }
        }
        assert!(
            withdraw_fired,
            "cunning strike (withdraw): should install Disengaging on a sneak hit at least once",
        );
    }

    /// End-to-end: with the Cunning Strike (Poison) prime up and a hit
    /// landing on a target that fails the CON save, the target ends the
    /// swing both damaged AND Poisoned. The prime is consumed regardless.
    /// We give the rogue a friendly adjacent ally so sneak attack
    /// triggers without rolling for advantage.
    #[test]
    fn cunning_strike_poison_applies_on_sneak_hit() {
        use crate::actions::class_attacks::ROGUE_SHORTSWORD;
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::actors::creatures::rogues::ROGUE_TEMPLATE;
        use crate::conditions::{Condition, ConditionTimer};
        // 200 swings is overkill: hit-rate ~50% × poison-save fail ~50%
        // = ~25% per swing; one in 200 is a 0.99999999 floor. We swing
        // at a fighter rather than a zombie because zombies are immune
        // to Poisoned (the condition won't land even on a save fail).
        let mut sneak_landed_with_poison = false;
        for seed in 0..200 {
            let mut e = ei_seeded(15, 15, &[], seed);
            let rogue = e
                .instantiate_creature(&ROGUE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            // Level the rogue to 3 so the sneak pool is 2d6 — a level-1
            // rogue's 1d6 pool gets refused by `consume_cunning_strike`
            // (can't reduce dice below 1 RAW).
            e.actors.get_mut(&rogue).unwrap().award_xp(10_000);
            let mut roller = crate::engine::dice::FastRandRoller::with_seed(seed);
            while e.actors[&rogue].level() < 3
                && e.actors
                    .get_mut(&rogue)
                    .unwrap()
                    .try_level_up(&mut roller)
                    .is_some()
            {}
            // Ally adjacent to target → ally-adjacency sneak trigger.
            let _ally = e
                .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(4, 3), 0, 0)
                .unwrap();
            let target = e
                .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(3, 2), 1, 0)
                .unwrap();
            // Heal the target up so the hit can't down it before the
            // poison rider lands.
            let max = e.actors[&target].max_hitpoints();
            e.actors.get_mut(&target).unwrap().heal(max);
            // Install the Cunning Strike (Poison) prime.
            e.actors.get_mut(&rogue).unwrap().add_condition(
                Condition::CunningStrikePoison,
                ConditionTimer::UntilStartOfNextTurn,
            );
            let targets = vec![target];
            let effects = ROGUE_SHORTSWORD.side_effects(
                &mut e,
                rogue,
                Some(&targets),
                None,
                None,
            );
            for ef in effects {
                ef.apply(&mut e);
            }
            // Prime is consumed only when sneak actually fired.
            let prime_consumed = !e.actors[&rogue].has_condition(Condition::CunningStrikePoison);
            let poisoned = e
                .actors
                .get(&target)
                .is_some_and(|a| a.has_condition(Condition::Poisoned));
            if prime_consumed && poisoned {
                sneak_landed_with_poison = true;
                break;
            }
        }
        assert!(
            sneak_landed_with_poison,
            "cunning strike (poison): rider should land at least once across 200 swings",
        );
    }

    /// Investiture of Ice: self-buff installs InvestedInIce + a
    /// concentration mark; the holder takes half cold damage while up.
    /// Symmetric to `investiture_of_flame_installs_self_buff_and_resists_fire`.
    #[test]
    fn investiture_of_ice_installs_self_buff_and_resists_cold() {
        use crate::actions::spells::INVESTITURE_OF_ICE;
        use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
        let mut e = ei_with_terrain(10, 10, &[]);
        let wiz = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        for ef in INVESTITURE_OF_ICE.side_effects(&mut e, wiz, None, None, None) {
            ef.apply(&mut e);
        }
        assert!(e.actors[&wiz].has_condition(Condition::InvestedInIce));
        assert!(e.actors[&wiz].is_concentrating());
        // Half-cold-damage check: with the buff up, 20 cold damage
        // should land as 10 HP loss.
        let actor = &e.actors[&wiz];
        assert_eq!(actor.effective_damage(20, DamageType::Cold), 10);
        // Non-cold damage is untouched (fire is unaffected).
        assert_eq!(actor.effective_damage(20, DamageType::Fire), 20);
    }

    /// Investiture of Ice's retaliation rider: a melee swing against the
    /// invested caster deals 1d10 cold damage back to the attacker.
    /// Mirrors `fire_shield_reflects_melee_damage` shape.
    #[test]
    fn investiture_of_ice_reflects_cold_on_melee_hit() {
        use crate::actions::spells::INVESTITURE_OF_ICE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
        // Sweep seeds — the rider rolls 1d10 + the attacker may miss
        // the swing entirely. We assert the rider lands at least once.
        let mut reflected = false;
        for seed in 0..40u64 {
            let mut e = ei_seeded(10, 10, &[], seed);
            let wiz = e
                .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(5, 5), 0, 0)
                .unwrap();
            let gob = e
                .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(6, 5), 1, 0)
                .unwrap();
            // Invest the wizard so the retaliation rider is armed.
            for ef in INVESTITURE_OF_ICE.side_effects(&mut e, wiz, None, None, None) {
                ef.apply(&mut e);
            }
            let gob_hp_before = e.actors[&gob].hitpoints();
            // Goblin swings melee at the wizard. Use the scimitar attack
            // which is the goblin's melee weapon.
            let scimitar = e.actors[&gob].find_action("scimitar").unwrap();
            for ef in scimitar.side_effects(&mut e, gob, Some(&vec![wiz]), None, None) {
                ef.apply(&mut e);
            }
            // If the goblin's HP dropped, the rider lands (the attack
            // itself doesn't deal damage TO the goblin, so any drop on
            // the goblin's side is the cold rider).
            if e.actors
                .get(&gob)
                .is_some_and(|a| a.hitpoints() < gob_hp_before)
            {
                reflected = true;
                break;
            }
        }
        assert!(
            reflected,
            "Investiture of Ice should reflect cold damage on at least one melee hit across seeds"
        );
    }

    /// Wall of Stone: lv5 concentration burst. Verifies the lv5 slot cost,
    /// that failed-save enemies eventually pick up Restrained across
    /// seeds, and that the caster picks up concentration.
    #[test]
    fn wall_of_stone_restrains_enemies_in_burst() {
        use crate::actions::spells::WALL_OF_STONE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
        use crate::engine::side_effects::Resource;

        let mut concentrated = false;
        let mut restrained = false;
        for seed in 0..40u64 {
            let mut e = ei_seeded(30, 30, &[], seed);
            let wiz = e
                .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 5), 0, 0)
                .unwrap();
            let g = e
                .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(15, 5), 1, 0)
                .unwrap();
            let center = Coordinate::new(15, 5);
            let costs = WALL_OF_STONE.cost(&e, wiz, None, Some(&vec![center]), None);
            assert!(
                costs.iter().any(|c| matches!(c, Resource::SpellSlot(5))),
                "Wall of Stone should cost a lv5 spell slot"
            );
            for ef in WALL_OF_STONE.side_effects(&mut e, wiz, None, Some(&vec![center]), None) {
                ef.apply(&mut e);
            }
            if e.actors[&wiz].is_concentrating() {
                concentrated = true;
            }
            if e.actors
                .get(&g)
                .is_some_and(|a| a.has_condition(Condition::Restrained))
            {
                restrained = true;
            }
            if concentrated && restrained {
                break;
            }
        }
        assert!(concentrated, "Wall of Stone should anchor caster concentration");
        assert!(
            restrained,
            "Wall of Stone should restrain at least one enemy across seeds"
        );
    }

    /// Wall of Stone spares allies in the burst (uses enemy_burst_targets
    /// so friendly fire is impossible). Verifies an ally in the same
    /// radius never picks up Restrained.
    #[test]
    fn wall_of_stone_spares_allies_in_burst() {
        use crate::actions::spells::WALL_OF_STONE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
        for seed in 0..20u64 {
            let mut e = ei_seeded(30, 30, &[], seed);
            let wiz = e
                .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 5), 0, 0)
                .unwrap();
            // Ally on team 0 — same team as the wizard.
            let ally = e
                .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(15, 5), 0, 0)
                .unwrap();
            let center = Coordinate::new(15, 5);
            for ef in WALL_OF_STONE.side_effects(&mut e, wiz, None, Some(&vec![center]), None) {
                ef.apply(&mut e);
            }
            assert!(
                !e.actors[&ally].has_condition(Condition::Restrained),
                "Wall of Stone should never restrain allies (seed {})",
                seed
            );
        }
    }

    /// Tasha's Caustic Brew: failed-save enemies pick up the CausticBrewed
    /// flag, and the caster starts concentrating. Allies are excluded by
    /// the `enemy`/`neutral` partitioning at the resolver — we test the
    /// enemy-side install lane here.
    #[test]
    fn caustic_brew_installs_dot_on_failed_save() {
        use crate::actions::spells::TASHAS_CAUSTIC_BREW;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
        let mut saw_install = false;
        for seed in 0..40u64 {
            let mut e = ei_seeded(20, 20, &[], seed);
            let wiz = e
                .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            let enemy = e
                .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(10, 10), 1, 0)
                .unwrap();
            let center = Coordinate::new(10, 10);
            for ef in TASHAS_CAUSTIC_BREW
                .side_effects(&mut e, wiz, None, Some(&vec![center]), None)
            {
                ef.apply(&mut e);
            }
            // Concentration always starts regardless of save outcome —
            // even a fully-passed cast still installs the concentration
            // marker (RAW: concentration begins on cast, drops if no
            // targets stuck the rider).
            assert!(
                e.actors[&wiz].is_concentrating(),
                "Caustic Brew should start concentration (seed {})",
                seed
            );
            if e.actors.contains_key(&enemy)
                && e.actors[&enemy].has_condition(Condition::CausticBrewed)
            {
                saw_install = true;
                break;
            }
        }
        assert!(
            saw_install,
            "Caustic Brew never installed the DoT condition across 40 seeds"
        );
    }

    /// Wipe Acid: actor with the CausticBrewed flag spends an action and
