    /// Darkened actors swing with disadvantage AND attackers targeting
    /// them get disadvantage too. Mirrors `Blinded`'s symmetric
    /// envelope but distinct so cleanse / dispel sweeps can target just
    /// the Darkness install.
    #[test]
    fn darkened_actor_swings_and_is_attacked_at_disadvantage() {
        use crate::actors::creatures::clerics::CLERIC_TEMPLATE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::engine::encounter::RollMode;
        let mut e = ei_with_terrain(15, 15, &[]);
        let attacker = e
            .instantiate_creature(&CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let target = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(3, 2), 1, 0)
            .unwrap();
        // Baseline: a non-Darkened attacker rolls normally.
        assert_eq!(
            e.compute_attack_mode(attacker, target, true),
            RollMode::Normal,
            "baseline attack mode is Normal"
        );
        // Attacker-side Darkened → disadvantage on swings.
        e.actors
            .get_mut(&attacker)
            .unwrap()
            .add_condition(Condition::Darkened, crate::conditions::ConditionTimer::Rounds(10));
        assert_eq!(
            e.compute_attack_mode(attacker, target, true),
            RollMode::Disadvantage,
            "Darkened attacker swings with disadvantage"
        );
        // Clear and test target-side Darkened.
        e.actors
            .get_mut(&attacker)
            .unwrap()
            .remove_condition(Condition::Darkened);
        e.actors
            .get_mut(&target)
            .unwrap()
            .add_condition(Condition::Darkened, crate::conditions::ConditionTimer::Rounds(10));
        assert_eq!(
            e.compute_attack_mode(attacker, target, true),
            RollMode::Disadvantage,
            "attacks against a Darkened target also have disadvantage"
        );
    }

    /// Darkness: concentration-bound burst installs the `Darkened`
    /// condition on every actor caught in the radius. Dropping
    /// concentration strips the install from every caught target.
    #[test]
    fn darkness_installs_darkened_under_concentration() {
        use crate::actions::spells::DARKNESS;
        use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let wiz = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let enemy = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(6, 6), 1, 0)
            .unwrap();
        let pt = vec![Coordinate::new(6, 6)];
        let effs = DARKNESS.side_effects(&mut e, wiz, None, Some(&pt), None);
        for ef in effs {
            ef.apply(&mut e);
        }
        assert!(
            e.actors[&enemy].has_condition(Condition::Darkened),
            "Darkness installs Darkened on a burst target"
        );
        assert!(
            e.actors[&wiz].is_concentrating(),
            "Darkness is concentration-bound"
        );
        e.drop_concentration(wiz);
        assert!(
            !e.actors[&enemy].has_condition(Condition::Darkened),
            "Dropping concentration strips Darkened from caught targets"
        );
    }

    #[test]
    fn sahuagin_blood_frenzy_grants_advantage_on_wounded_target() {
        use crate::actors::creatures::sahuagins::SAHUAGIN_TEMPLATE;
        let mut e = ei_with_terrain(20, 20, &[]);
        let sah = e
            .instantiate_creature(&SAHUAGIN_TEMPLATE, Coordinate::new(3, 3), 0, 0)
            .unwrap();
        let enemy = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(5, 3), 1, 0)
            .unwrap();
        // Full-HP target — no Blood Frenzy yet.
        let baseline = e.compute_attack_mode(sah, enemy, true);
        assert_eq!(
            baseline,
            crate::engine::dice::RollMode::Normal,
            "blood frenzy should NOT fire vs a full-HP target",
        );
        // Wound the enemy by chipping one HP.
        e.actors.get_mut(&enemy).unwrap().take_damage(1);
        // Now the next melee swing should land with advantage.
        let frenzy = e.compute_attack_mode(sah, enemy, true);
        assert_eq!(
            frenzy,
            crate::engine::dice::RollMode::Advantage,
            "blood frenzy should grant advantage vs a wounded target",
        );
    }

    #[test]
    fn sahuagin_blood_frenzy_does_not_apply_to_ranged_attacks() {
        use crate::actors::creatures::sahuagins::SAHUAGIN_TEMPLATE;
        let mut e = ei_with_terrain(30, 20, &[]);
        // Far apart so the ranged "adjacent hostile = disadvantage" clause
        // can't fire and muddle the assertion.
        let sah = e
            .instantiate_creature(&SAHUAGIN_TEMPLATE, Coordinate::new(3, 3), 0, 0)
            .unwrap();
        let enemy = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(25, 3), 1, 0)
            .unwrap();
        // Wound the enemy by chipping one HP.
        e.actors.get_mut(&enemy).unwrap().take_damage(1);
        // Ranged swing: blood frenzy is melee-only per RAW.
        let mode = e.compute_attack_mode(sah, enemy, false);
        assert_eq!(
            mode,
            crate::engine::dice::RollMode::Normal,
            "blood frenzy should NOT apply to ranged attacks",
        );
    }

    /// Horn of Blasting: self-centered thunder burst that damages enemies
    /// in radius, spares the wielder, and consumes the trinket. Sweeps
    /// seeds to confirm at least one fail (Deafened install on a tough
    /// enemy that survives the damage) lands across runs.
    #[test]
    fn horn_of_blasting_damages_enemies_and_deafens_on_fail() {
        use crate::actions::item_actions::BLOW_HORN_OF_BLASTING;
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::actors::creatures::ogres::OGRE_TEMPLATE;
        use crate::items::item_template::HORN_OF_BLASTING;
        let mut saw_damage = false;
        let mut saw_deaf = false;
        for seed in 0..30u64 {
            let mut e = ei_seeded(15, 15, &[], seed);
            let user = e
                .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            // Ogre is tough enough (~59 HP) to survive 5d6 thunder so we
            // can observe the Deafened rider — a Goblin would die first.
            let ogre = e
                .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(5, 2), 1, 0)
                .unwrap();
            e.actors
                .get_mut(&user)
                .unwrap()
                .pickup_item(&HORN_OF_BLASTING);
            let user_hp_pre = e.actors[&user].hitpoints();
            let ogre_hp_pre = e.actors[&ogre].hitpoints();
            let aei = ActionExecutionInfo::new(&BLOW_HORN_OF_BLASTING, user, None, None, None);
            assert!(aei.validate(&e));
            e.push_action(aei);
            e.process_stack();
            // Horn consumed regardless of save outcomes.
            assert!(
                !e.actors[&user].has_item_named("Horn of Blasting"),
                "horn should be consumed on use"
            );
            // Wielder must never eat their own burst — neutral_burst_targets
            // excludes the caster.
            assert_eq!(
                e.actors[&user].hitpoints(),
                user_hp_pre,
                "Horn of Blasting must not damage its wielder"
            );
            let ogre_hp_post = e
                .actors
                .get(&ogre)
                .map(|a| a.hitpoints())
                .unwrap_or(0);
            if ogre_hp_post < ogre_hp_pre {
                saw_damage = true;
            }
            if e.actors
                .get(&ogre)
                .is_some_and(|a| a.has_condition(Condition::Deafened))
            {
                saw_deaf = true;
            }
            if saw_damage && saw_deaf {
                break;
            }
        }
        assert!(saw_damage, "horn should damage the ogre across seeds");
        assert!(saw_deaf, "horn should deafen the ogre on at least one fail");
    }

