    /// Magnify Gravity is a friend-or-foe burst — every actor in the
    /// 1-tile radius (caster excluded) takes 2d8 force on a failed STR
    /// save. We scan multiple instances; across enough runs at least one
    /// low-STR goblin should fail their save and pick up the Slowed
    /// rider AND take some damage. This catches regressions to either
    /// half of the spell (burst damage OR rider install).
    #[test]
    fn magnify_gravity_damages_burst_and_slows_on_fail() {
        use crate::actions::spells::MAGNIFY_GRAVITY;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
        let mut slowed_landed = false;
        let mut damaged = false;
        for _ in 0..32 {
            let mut e = ei_with_terrain(20, 20, &[]);
            let wizard = e
                .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            let goblin = e
                .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(5, 2), 1, 0)
                .unwrap();
            let pre_hp = e.actors[&goblin].hitpoints();
            let tl = vec![Coordinate::new(5, 2)];
            let effs = MAGNIFY_GRAVITY.side_effects(&mut e, wizard, None, Some(&tl), None);
            for ef in effs {
                ef.apply(&mut e);
            }
            let post_hp = e.actors.get(&goblin).map(|a| a.hitpoints()).unwrap_or(0);
            assert!(
                post_hp <= pre_hp,
                "Magnify Gravity must never heal: pre={}, post={}",
                pre_hp,
                post_hp
            );
            if post_hp < pre_hp {
                damaged = true;
            }
            if e.actors
                .get(&goblin)
                .is_some_and(|a| a.has_condition(Condition::Slowed))
            {
                slowed_landed = true;
            }
            if slowed_landed && damaged {
                break;
            }
        }
        assert!(damaged, "Magnify Gravity should deal force damage across 32 runs");
        assert!(
            slowed_landed,
            "Magnify Gravity should land Slowed on at least one failed-save \
             goblin across 32 runs"
        );
    }

    /// Water Elemental shares the elemental damage-modifier base (BPS
    /// resistance + poison immunity) and overlays acid resistance.
    /// Regression guard for the new `elemental_damage_modifiers`
    /// helper: each variant must still expose the BPS triple after
    /// the refactor extracted the base.
    #[test]
    fn water_elemental_inherits_elemental_damage_base() {
        use crate::actors::creatures::water_elementals::WATER_ELEMENTAL_TEMPLATE;
        use crate::engine::types::DamageType;
        let mut e = ei_with_terrain(20, 20, &[]);
        let el = e
            .instantiate_creature(&WATER_ELEMENTAL_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        let actor = e.actors.get_mut(&el).unwrap();
        // Overlay: water-specific acid resistance.
        assert!(actor.is_resistant_to(DamageType::Acid));
        // Inherited from the elemental base.
        assert!(actor.is_immune_to(DamageType::Poison));
        assert!(actor.is_resistant_to(DamageType::Bludgeoning));
        assert!(actor.is_resistant_to(DamageType::Piercing));
        assert!(actor.is_resistant_to(DamageType::Slashing));
    }

