    /// Psionic Strike lays +1d8 Force on the Psi Warrior's first hit of
    /// the turn and no more: the shared once-per-turn ledger gates it,
    /// so a template carrying the tag out-damages the baseline Fighter
    /// but by a bounded amount.
    #[test]
    fn psionic_strike_fires_once_per_turn() {
        use crate::actions::class_features::PSIONIC_STRIKE_TAG;
        use crate::actors::creatures::fighters::PSI_WARRIOR_FIGHTER_TEMPLATE;
        use crate::actors::creatures::ogres::OGRE_TEMPLATE;
        use crate::engine::attack::{
            AttackParams, ONCE_PER_TURN_WEAPON_DIE_RIDERS, try_fire_once_per_turn_weapon_die_rider,
        };
        let spec = ONCE_PER_TURN_WEAPON_DIE_RIDERS
            .iter()
            .find(|s| s.tag == PSIONIC_STRIKE_TAG)
            .expect("psionic strike should be a row on the shared rider cohort");
        let mut e = ei_with_terrain(20, 20, &[]);
        let psi = e
            .instantiate_creature(&PSI_WARRIOR_FIGHTER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        let ogre = e
            .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(6, 5), 1, 0)
            .unwrap();
        let params = AttackParams {
            caster_id: psi,
            target_id: ogre,
            action_name: "scimitar",
            attack_bonus: 5,
            damage_dice: Dice::new(1, 6),
            damage_bonus: 3,
            damage_type: DamageType::Slashing,
            is_melee: true,
            long_range: None,
            is_spell: false,
        };
        let mut effects = Vec::new();
        assert!(
            try_fire_once_per_turn_weapon_die_rider(&mut e, &mut effects, &params, false, spec),
            "the first hit of the turn carries the strike"
        );
        assert_eq!(effects.len(), 1, "one Force payload queued");
        assert!(
            !try_fire_once_per_turn_weapon_die_rider(&mut e, &mut effects, &params, false, spec),
            "the second hit of the same turn does not"
        );
        assert_eq!(effects.len(), 1);
        // Turn-start clears the shared ledger, re-arming the rider.
        let _ = e.actors.get_mut(&psi).unwrap().reset_for_new_round();
        assert!(try_fire_once_per_turn_weapon_die_rider(
            &mut e,
            &mut effects,
            &params,
            false,
            spec
        ));
    }

    /// Eldritch Knight template drift pin. The subclass adds three tags,
    /// five spells, one bonus action, a slot table and an INT bump — and
    /// must still inherit the whole baseline Fighter kit through the
    /// `..FIGHTER_TEMPLATE.clone()` tail. Any of those going missing is
    /// a silent regression, since the missing half only shows up as
    /// "the knight is weaker than expected" in play.
    #[test]
    fn eldritch_knight_ships_its_kit_and_inherits_the_fighter_chassis() {
        use crate::actions::class_features::{
            ACTION_SURGE_TAG, ELDRITCH_STRIKE_TAG, INDOMITABLE_TAG, PARRY_TAG, RIPOSTE_TAG,
            SECOND_WIND_TAG, TRIP_ATTACK_TAG, WAR_MAGIC_TAG, WEAPON_BOND_TAG,
        };
        use crate::actors::creatures::fighters::{
            ELDRITCH_KNIGHT_FIGHTER_TEMPLATE, FIGHTER_TEMPLATE,
        };
        let mut e = ei_with_terrain(15, 15, &[]);
        let knight = e
            .instantiate_creature(&ELDRITCH_KNIGHT_FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // The three subclass tells.
        for tag in [WEAPON_BOND_TAG, WAR_MAGIC_TAG, ELDRITCH_STRIKE_TAG] {
            assert!(
                e.actors[&knight].has_passive_feature(tag),
                "Eldritch Knight should carry its own subclass tag {}",
                tag
            );
        }
        // Baseline chassis, inherited wholesale.
        for tag in [
            SECOND_WIND_TAG,
            ACTION_SURGE_TAG,
            INDOMITABLE_TAG,
            PARRY_TAG,
            RIPOSTE_TAG,
            TRIP_ATTACK_TAG,
        ] {
            assert!(
                e.actors[&knight].has_passive_feature(tag),
                "Eldritch Knight should inherit baseline Fighter tag {}",
                tag
            );
        }
        assert!(e.actors[&knight].has_extra_attack());
        // The spell kit, plus the bonus action that cashes War Magic.
        for name in [
            "fire bolt",
            "booming blade",
            "shield",
            "magic missile",
            "misty step",
            "war magic",
        ] {
            assert!(
                e.actors[&knight].find_action(name).is_some(),
                "Eldritch Knight should carry the {} action",
                name
            );
        }
        // Third-caster slot table and the INT bump that anchors the DC —
        // both distinguish this template from the baseline, which has
        // neither.
        assert_eq!(
            ELDRITCH_KNIGHT_FIGHTER_TEMPLATE.spell_slots_by_level,
            vec![4, 3],
            "third-caster progression"
        );
        assert!(
            ELDRITCH_KNIGHT_FIGHTER_TEMPLATE.intelligence
                > FIGHTER_TEMPLATE.intelligence,
            "the knight's INT rises above the baseline fighter's to anchor the spell DC"
        );
        assert!(
            FIGHTER_TEMPLATE.spell_slots_by_level.is_empty(),
            "the baseline fighter stays slotless"
        );
    }

    /// Eldritch Strike stamps the mark plus its back-link on any
    /// connecting weapon hit. Driven over a seed sweep so at least one
    /// swing lands; a knight without the tag never stamps.
    #[test]
    fn eldritch_strike_marks_the_target_on_a_weapon_hit() {
        use crate::actors::creatures::fighters::{
            ELDRITCH_KNIGHT_FIGHTER_TEMPLATE, FIGHTER_TEMPLATE,
        };
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::conditions::Condition;
        use crate::engine::attack::{AttackParams, resolve_attack_outcome};

        // (hits, marks) — a nat 1 auto-misses, so the sweep can't assume
        // every swing connects; what's under test is that the mark
        // tracks hits exactly.
        let run = |template: &'static CreatureTemplate| -> (usize, usize) {
            let (mut hits, mut marked) = (0usize, 0usize);
            for seed in 0..40u64 {
                let mut e = ei_with_terrain(15, 15, &[]);
                e.roller = crate::engine::dice::FastRandRoller::with_seed(seed);
                let knight = e
                    .instantiate_creature(template, Coordinate::new(2, 2), 0, 0)
                    .unwrap();
                let target = e
                    .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(3, 2), 1, 0)
                    .unwrap();
                let (effects, dealt) = resolve_attack_outcome(
                    &mut e,
                    AttackParams {
                        caster_id: knight,
                        target_id: target,
                        action_name: "scimitar",
                        attack_bonus: 20, // force the hit; the mark is what's under test
                        damage_dice: Dice::new(1, 6),
                        damage_bonus: 3,
                        damage_type: DamageType::Slashing,
                        is_melee: true,
                        long_range: None,
                        is_spell: false,
                    },
                );
                if dealt > 0 {
                    hits += 1;
                }
                for ef in effects {
                    ef.apply(&mut e);
                }
                if e.actors[&target].has_condition(Condition::EldritchStruck) {
                    assert_eq!(
                        e.actors[&target].linked_by(Condition::EldritchStruck),
                        Some(knight),
                        "the mark carries the striking knight's id"
                    );
                    marked += 1;
                }
            }
            (hits, marked)
        };
        let (knight_hits, knight_marks) = run(&ELDRITCH_KNIGHT_FIGHTER_TEMPLATE);
        assert!(knight_hits > 0, "attack_bonus 20 should connect most swings");
        assert_eq!(
            knight_marks, knight_hits,
            "every connecting swing stamps the mark, and only a connecting one"
        );
        let (plain_hits, plain_marks) = run(&FIGHTER_TEMPLATE);
        assert!(plain_hits > 0, "control arm should also be landing swings");
        assert_eq!(
            plain_marks, 0,
            "a fighter without the tag never stamps the mark"
        );
    }

    /// The mark is caster-specific. A save against a *different*
    /// caster's spell reads clean and leaves the mark standing; the save
    /// against the knight who placed it consumes the mark and clears the
    /// back-link with it.
    #[test]
    fn eldritch_strike_bends_only_the_marking_knights_spell_save() {
        use crate::actors::creatures::fighters::ELDRITCH_KNIGHT_FIGHTER_TEMPLATE;
        use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::conditions::{Condition, ConditionTimer};
        use crate::engine::side_effects::{ApplicableSideEffect, SetConditionLink};
        use crate::engine::types::AbilityScoreType;

        let mut e = ei_with_terrain(15, 15, &[]);
        let knight = e
            .instantiate_creature(&ELDRITCH_KNIGHT_FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let wizard = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(3, 2), 0, 1)
            .unwrap();
        let target = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(8, 8), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&target)
            .unwrap()
            .add_condition(Condition::EldritchStruck, ConditionTimer::Rounds(2));
        SetConditionLink {
            target_id: target,
            condition: Condition::EldritchStruck,
            source: Some(knight),
        }
        .apply(&mut e);

        // The team's wizard casting at the same target gets nothing —
        // the mark belongs to the knight who swung.
        let _ = e.roll_save_against_caster(target, AbilityScoreType::Wisdom, 15, wizard);
        assert!(
            e.actors[&target].has_condition(Condition::EldritchStruck),
            "another caster's spell neither fires nor consumes the mark"
        );

        // The knight's own spell cashes it, once.
        let _ = e.roll_save_against_caster(target, AbilityScoreType::Wisdom, 15, knight);
        assert!(
            !e.actors[&target].has_condition(Condition::EldritchStruck),
            "the marking knight's spell consumes the mark"
        );
        assert_eq!(
            e.actors[&target].linked_by(Condition::EldritchStruck),
            None,
            "removing the condition clears the back-link"
        );
    }

    /// War Magic's prime is cantrip-only: `spell_level == 0` arms it,
    /// any levelled cast leaves it alone, and a fighter without the tag
    /// never arms it at all.
    #[test]
    fn war_magic_primes_on_cantrips_only() {
        use crate::actors::creatures::fighters::{
            ELDRITCH_KNIGHT_FIGHTER_TEMPLATE, FIGHTER_TEMPLATE,
        };
        use crate::conditions::Condition;

        let mut e = ei_with_terrain(15, 15, &[]);
        let knight = e
            .instantiate_creature(&ELDRITCH_KNIGHT_FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let plain = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(4, 2), 0, 1)
            .unwrap();

        // A levelled cast is not a cantrip.
        let _ = e.dispatch_post_cast_triggers(knight, 2, &[], Some(SpellSchool::Evocation), None);
        assert!(
            !e.actors[&knight].has_condition(Condition::WarMagicPrimed),
            "a levelled spell doesn't arm War Magic"
        );
        // Neither is a non-spell action: `Action::execute` opens a
        // level-0 cast frame for every action it runs, and only the
        // school tag separates a Fire Bolt from a scimitar swing. A
        // knight who could arm the prime by swinging would get the
        // War Magic follow-up for free.
        let _ = e.dispatch_post_cast_triggers(knight, 0, &[], None, None);
        assert!(
            !e.actors[&knight].has_condition(Condition::WarMagicPrimed),
            "an untagged level-0 action is a weapon swing, not a cantrip"
        );
        // A cantrip is.
        let _ = e.dispatch_post_cast_triggers(knight, 0, &[], Some(SpellSchool::Evocation), None);
        assert!(
            e.actors[&knight].has_condition(Condition::WarMagicPrimed),
            "a cantrip arms War Magic"
        );
        // No tag, no prime.
        let _ = e.dispatch_post_cast_triggers(plain, 0, &[], Some(SpellSchool::Evocation), None);
        assert!(
            !e.actors[&plain].has_condition(Condition::WarMagicPrimed),
            "a fighter without the tag never arms War Magic"
        );
    }

    /// The War Magic bonus action is gated on the prime, hands back an
    /// Action token, and burns the prime so it can't be cashed twice.
    #[test]
    fn war_magic_strike_trades_the_prime_for_an_action() {
        use crate::actions::class_features::WAR_MAGIC_STRIKE;
        use crate::actors::creatures::fighters::ELDRITCH_KNIGHT_FIGHTER_TEMPLATE;
        use crate::conditions::Condition;
        use crate::engine::side_effects::Resource;

        let mut e = ei_with_terrain(15, 15, &[]);
        let knight = e
            .instantiate_creature(&ELDRITCH_KNIGHT_FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // Unprimed: the bonus action isn't available at all.
        assert!(
            !WAR_MAGIC_STRIKE.validate_input(&e, knight, None, None, None),
            "War Magic needs a cantrip cast first"
        );

        let _ = e.dispatch_post_cast_triggers(knight, 0, &[], Some(SpellSchool::Evocation), None);
        let actor = e.actors.get_mut(&knight).unwrap();
        actor.give_resource(Resource::BonusAction);
        // Spend the Action the (notional) cantrip cost so the grant is
        // observable rather than masked by an unspent token.
        actor.consume_resource(Resource::Action);
        assert!(!e.actors[&knight].can_consume_resource(Resource::Action));

        assert!(WAR_MAGIC_STRIKE.validate_input(&e, knight, None, None, None));
        let effects = WAR_MAGIC_STRIKE.execute(&mut e, knight, None, None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        assert!(
            e.actors[&knight].can_consume_resource(Resource::Action),
            "War Magic hands back an Action for the follow-up swing"
        );
        assert!(
            !e.actors[&knight].has_condition(Condition::WarMagicPrimed),
            "the prime is one-shot"
        );
        assert!(
            !WAR_MAGIC_STRIKE.validate_input(&e, knight, None, None, None),
            "and can't be cashed a second time"
        );
    }

    /// Every actor the engine prompts has had `start_turn_for` run for
    /// them first. That is the invariant `ensure_turn_started` exists to
    /// hold, and it used to have two holes.
    ///
    /// **Hole one — the first actor of the encounter.** `initialize`
    /// leaves the initiative slot at index 0 and nothing calls
    /// `start_turn_for`; the only two production callers both sat
    /// *after* an `advance_initiative`. So the actor who won initiative
    /// was prompted without their turn ever starting — no
    /// `mark_taken_turn_in_combat` (an Assassin got Assassinate
    /// advantage against them all round, after they had already acted),
    /// no `UntilStartOfNextTurn` expiry, no recharge roll.
    ///
    /// **Hole two — an actor who dies on their own turn.**
    /// `InitiativeTracker::remove_actor` deliberately lets the next
    /// actor slide into the vacated index, on the documented assumption
    /// that the caller won't advance. But the actor who slid in is then
    /// prompted through the same no-advance path, so they too were
    /// prompted with no turn start — inheriting whatever resources they
    /// had left from their *previous* turn. Reachable through every
    /// damage-reflect lane (Fire Shield, Armor of Agathys, a
    /// salamander's Heated Body) and through Hellish Rebuke.
    ///
    /// This pins the first hole directly, which is the one that needs no
    /// setup: initiative order is seed-dependent, so the test asserts
    /// against whoever won rather than a fixed id.
    #[test]
    fn the_first_actor_prompted_has_had_their_turn_started() {
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::actors::creatures::skeletons::SKELETON_TEMPLATE;

        // `ei_with_terrain` builds an already-initialized encounter, so
        // spawn into it and let `instantiate_creature` wire the queue.
        let mut e = ei_with_terrain(15, 15, &[]);
        let a = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let b = e
            .instantiate_creature(&SKELETON_TEMPLATE, Coordinate::new(8, 8), 1, 0)
            .unwrap();
        for id in [a, b] {
            assert!(
                !e.actors[&id].has_taken_turn_in_combat(),
                "latch starts clear"
            );
        }
        e.process_stack();
        let prompted = e.peek_prompt().map(|p| p.actor_id()).expect("a prompt");
        assert!(
            e.actors[&prompted].has_taken_turn_in_combat(),
            "the actor being prompted has had their turn started"
        );
        // And the one who hasn't been prompted still hasn't — the latch
        // is per-actor, not a blanket flip.
        let other = if prompted == a { b } else { a };
        assert!(
            !e.actors[&other].has_taken_turn_in_combat(),
            "an actor whose slot hasn't come up is untouched"
        );
    }

    /// 5e Thief Rogue **Thief's Reflexes**: two turns in round 1, one
    /// per round after that.
    ///
    /// Driven by walking the whole queue twice and counting how often
    /// each id comes up. Round 1 should name the Thief twice and the
    /// goblin once; round 2 should name each of them once. Counting is
    /// the assertion rather than checking a flag because the feature's
    /// whole claim is about *how many turns happen* — a version that
    /// handed out a spare Action instead would pass a flag check and
    /// fail this one.
    #[test]
    fn thiefs_reflexes_grants_a_second_turn_only_in_round_one() {
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::actors::creatures::rogues::THIEF_ROGUE_TEMPLATE;

        let mut e = ei_with_terrain(15, 15, &[]);
        let thief = e
            .instantiate_creature(&THIEF_ROGUE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let goblin = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(9, 9), 1, 0)
            .unwrap();

        let round_one = e.initiative_actor_ids();
        assert_eq!(
            round_one.iter().filter(|&&id| id == thief).count(),
            2,
            "the Thief holds two slots in round 1: {:?}",
            round_one
        );
        assert_eq!(
            round_one.iter().filter(|&&id| id == goblin).count(),
            1,
            "nobody else gains a slot"
        );
        // The extra slot sits below the Thief's own rather than beside
        // it — that gap is what the enemies act in.
        let first = round_one.iter().position(|&id| id == thief).unwrap();
        let second = round_one.iter().rposition(|&id| id == thief).unwrap();
        assert!(
            second > first + 1 || round_one.len() == 2,
            "the second slot should not sit immediately behind the first: {:?}",
            round_one
        );

        // Walk out of round 1. `skip_turn` advances one slot at a time,
        // so the queue length is exactly the number of steps to a wrap.
        assert_eq!(e.round(), 1);
        for _ in 0..round_one.len() {
            e.skip_turn();
        }
        assert_eq!(e.round(), 2, "one full pass is one round");

        let round_two = e.initiative_actor_ids();
        assert_eq!(
            round_two.iter().filter(|&&id| id == thief).count(),
            1,
            "the extra slot retires with round 1: {:?}",
            round_two
        );
        assert_eq!(round_two.len(), 2, "and nothing else changed shape");
    }

    /// A Thief who dies during round 1 takes their extra slot with them.
    ///
    /// The queue is keyed by position and the Thief owns two of them, so
    /// a removal that stopped at the first match would leave a corpse
    /// holding a turn — `start_turn_for` would find no actor, and the
    /// slot would sit in the order forever. `remove_actor` sweeps every
    /// slot an actor owns, which is what this pins.
    #[test]
    fn a_dead_thief_keeps_neither_of_their_slots() {
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::actors::creatures::rogues::THIEF_ROGUE_TEMPLATE;

        let mut e = ei_with_terrain(15, 15, &[]);
        let thief = e
            .instantiate_creature(&THIEF_ROGUE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        e.instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(9, 9), 1, 0)
            .unwrap();
        assert_eq!(
            e.initiative_actor_ids()
                .iter()
                .filter(|&&id| id == thief)
                .count(),
            2
        );

        e.remove_actor(thief);
        assert!(
            !e.initiative_actor_ids().contains(&thief),
            "no slot survives the actor: {:?}",
            e.initiative_actor_ids()
        );
    }

    /// 5e Thief Rogue **Fast Hands**: a potion costs the Thief their
    /// bonus action while they still have one, and their Action once
    /// they don't.
    ///
    /// The fallback half is the interesting one. `cost()` hands back a
    /// list of resources that must *all* be paid, so a static swap to
    /// "bonus action" would have silently taken the Action price away —
    /// a Thief who had already spent their bonus action on Cunning Dash
    /// would find the potion unusable, which is strictly worse than the
    /// baseline rogue and the opposite of what the feature says.
    #[test]
    fn fast_hands_prices_a_potion_against_what_the_thief_has_left() {
        use crate::actions::item_actions::DRINK_HEALING_POTION;
        use crate::actors::creatures::rogues::{ROGUE_TEMPLATE, THIEF_ROGUE_TEMPLATE};
        use crate::engine::side_effects::Resource;

        let mut e = ei_with_terrain(15, 15, &[]);
        let thief = e
            .instantiate_creature(&THIEF_ROGUE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let plain = e
            .instantiate_creature(&ROGUE_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();

        let price = |e: &EncounterInstance, id: usize| {
            DRINK_HEALING_POTION.cost(e, id, None, None, None)
        };
        assert_eq!(
            price(&e, thief),
            vec![Resource::BonusAction],
            "Fast Hands moves the potion onto the bonus action"
        );
        assert_eq!(
            price(&e, plain),
            vec![Resource::Action],
            "and leaves every other rogue paying an Action"
        );

        // Spend the bonus action; the price falls back rather than
        // becoming unpayable.
        e.actors
            .get_mut(&thief)
            .unwrap()
            .consume_resource(Resource::BonusAction);
        assert_eq!(
            price(&e, thief),
            vec![Resource::Action],
            "with no bonus action left, the Action price comes back"
        );
    }

    /// Conditions that bar casting bar *cantrips* too. The only gate for
    /// this used to live on the `SpellSlot` resource lane, which
    /// cantrips never touch — so a Silenced caster could Fire Bolt out
    /// of a zone of magical silence, and a wild-shaped druid (a bear)
    /// could cast Poison Spray. Both conditions' RAW text is
    /// unqualified.
    ///
    /// Driven from both sides of the split so the fix can't regress by
    /// half: a levelled spell (Fireball, which the old resource gate
    /// already caught) and a cantrip (Fire Bolt, which it didn't).
    #[test]
    fn silence_and_wild_shape_block_cantrips_not_just_slots() {
        use crate::actions::spells::{FIRE_BOLT, FIREBALL};
        use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::conditions::{Condition, ConditionTimer};

        for blocker in [Condition::Silenced, Condition::WildShaped] {
            let mut e = ei_with_terrain(20, 20, &[]);
            let caster = e
                .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            let target = e
                .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(6, 2), 1, 0)
                .unwrap();
            let ids = vec![target];
            let point = vec![Coordinate::new(6, 2)];
            // Baseline: both casts are legal.
            assert!(
                FIRE_BOLT.validate_input(&e, caster, Some(&ids), None, None),
                "{:?}: cantrip legal before the block",
                blocker
            );
            assert!(
                FIREBALL.validate_input(&e, caster, None, Some(&point), None),
                "{:?}: levelled spell legal before the block",
                blocker
            );

            e.actors
                .get_mut(&caster)
                .unwrap()
                .add_condition(blocker, ConditionTimer::Rounds(5));

            assert!(
                !FIREBALL.validate_input(&e, caster, None, Some(&point), None),
                "{:?} should block a levelled spell",
                blocker
            );
            assert!(
                !FIRE_BOLT.validate_input(&e, caster, Some(&ids), None, None),
                "{:?} should block a cantrip too",
                blocker
            );
            // Non-spell actions are untouched — the gate keys off
            // `school()`, not off being an action.
            assert!(
                e.actors[&caster].find_action("dodge").is_some_and(|a| a
                    .validate_input(&e, caster, None, None, None)),
                "{:?} shouldn't stop the caster from Dodging",
                blocker
            );
        }
    }

    /// A per-target Help grant reaches *weapon* attacks, not just spell
    /// attacks.
    ///
    /// The engine has two advantage-from-help lanes: the `Helped`
    /// condition, read by `compute_attack_mode`, and the per-target
    /// `HelpGrant` ledger, read only by `attack_mode_with_riders`.
    /// `spell_attack_outcome` called the latter; `resolve_attack_outcome`
    /// called `compute_attack_mode` directly and then cleared the
    /// one-shot rider stack — which *consumes* the grant. So a grant
    /// installed without the condition was silently eaten by the next
    /// weapon swing without ever granting advantage.
    ///
    /// Three shipped features install only the grant: the Battle
    /// Master's Feinting Attack, Commander's Strike (on the ordered
    /// ally), and the Arcane Trickster's Versatile Trickster. All three
    /// exist to make a *weapon* swing land, so all three did nothing on
    /// the lane they were written for. The `Help` action itself was
    /// unaffected because it installs both.
    ///
    /// Driven through `resolve_attack_outcome` on the log line, which is
    /// where the mode is rendered, over both polarities: with the grant
    /// naming this target, and with it naming somebody else.
    #[test]
    fn a_help_grant_grants_advantage_on_a_weapon_swing() {
        use crate::actors::actor_template::HelpGrant;
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::engine::attack::{AttackParams, resolve_attack_outcome};

        let swing = |grant_against: Option<usize>| -> bool {
            let mut e = ei_with_terrain(15, 15, &[]);
            let fighter = e
                .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            let target = e
                .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(4, 2), 1, 0)
                .unwrap();
            let decoy = e
                .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(9, 9), 1, 1)
                .unwrap();
            let against = grant_against.map(|_| decoy).unwrap_or(target);
            // `None` means "grant names the real target"; `Some` means
            // "grant names the decoy" — read that way so the closure
            // takes one flag rather than an id the caller can't know yet.
            let named = if grant_against.is_some() {
                against
            } else {
                target
            };
            e.actors
                .get_mut(&fighter)
                .unwrap()
                .set_help_grant(Some(HelpGrant {
                    helper_id: fighter,
                    against: named,
                }));
            let before = e.messages().len();
            let _ = resolve_attack_outcome(
                &mut e,
                AttackParams {
                    caster_id: fighter,
                    target_id: target,
                    action_name: "scimitar",
                    attack_bonus: 5,
                    damage_dice: Dice::new(1, 6),
                    damage_bonus: 3,
                    damage_type: DamageType::Slashing,
                    is_melee: true,
                    long_range: None,
                    is_spell: false,
                },
            );
            e.messages()[before..]
                .iter()
                .any(|m| m.contains("scimitar") && m.contains("(adv)"))
        };
        assert!(
            swing(None),
            "a grant naming this target should read as advantage on the swing"
        );
        assert!(
            !swing(Some(0)),
            "a grant naming somebody else should not"
        );
    }

    /// `peek_attack_mode` sees the per-target Help grant and leaves it
    /// standing; `attack_mode_with_riders` sees it and spends it.
    ///
    /// The pair matters because the AI's target ranking only has
    /// `&EncounterInstance` and so used to call `compute_attack_mode` —
    /// the only read-only option — which doesn't read the grant at all.
    /// A fighter who spent a bonus action feinting then ranked that
    /// target no higher than any other.
    #[test]
    fn peeking_the_attack_mode_reads_the_help_grant_without_spending_it() {
        use crate::actors::actor_template::HelpGrant;
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;

        let mut e = ei_with_terrain(15, 15, &[]);
        let fighter = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let target = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(4, 2), 1, 0)
            .unwrap();
        let other = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(9, 9), 1, 1)
            .unwrap();
        e.actors
            .get_mut(&fighter)
            .unwrap()
            .set_help_grant(Some(HelpGrant {
                helper_id: fighter,
                against: target,
            }));

        assert_eq!(
            e.peek_attack_mode(fighter, target, true),
            RollMode::Advantage,
            "the grant is visible to a read-only peek"
        );
        assert_eq!(
            e.peek_attack_mode(fighter, other, true),
            RollMode::Normal,
            "and only against the target it names"
        );
        // Peeking twice still reads Advantage — nothing was spent.
        assert_eq!(
            e.peek_attack_mode(fighter, target, true),
            RollMode::Advantage,
            "peeking is idempotent"
        );

        // The mutating twin spends it.
        assert_eq!(
            e.attack_mode_with_riders(fighter, target, true),
            RollMode::Advantage
        );
        assert_eq!(
            e.peek_attack_mode(fighter, target, true),
            RollMode::Normal,
            "the swing consumed the grant"
        );
    }

    /// Typing a spell's own name casts *that* spell, even when another
    /// action on the same sheet claims the name as an alias.
    ///
    /// The wizard is the live case: Maddening Darkness (level 8) is
    /// pushed onto the action list before Darkness (level 2) and aliases
    /// "darkness". Under the old single-pass search — which tested
    /// canonical name and alias in one `find`, and so resolved by
    /// action-list order — typing `darkness` burned the wizard's only
    /// 8th-level slot on the wrong spell, with nothing in the log to say
    /// so. `every_pc_action_is_reachable_by_its_canonical_name` sweeps
    /// the invariant across every class; this is the one case driven
    /// end-to-end through the parser.
    #[test]
    fn typing_a_spell_name_beats_another_actions_alias() {
        use crate::actions::spells::{DARKNESS, MADDENING_DARKNESS};
        use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
        use crate::engine::prompt::Prompt;

        let mut e = ei_with_terrain(20, 20, &[]);
        let wiz = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(4, 4), 0, 0)
            .unwrap();
        // The collision, in the order `WIZARD_TEMPLATE` builds it.
        let prompt = Prompt::new(wiz, vec![&*MADDENING_DARKNESS, &*DARKNESS]);
        let resolved = prompt
            .process_input("darkness 8,4", &e)
            .expect("darkness should parse and validate for a wizard");
        assert_eq!(
            resolved.action().name(),
            "darkness",
            "the canonical name wins over another action's alias"
        );
        // And the alias still resolves when nothing shadows it.
        let by_alias = prompt
            .process_input("maddening 8,4", &e)
            .expect("maddening should parse and validate");
        assert_eq!(by_alias.action().name(), "maddening darkness");
    }

    /// Every PC class family renders unambiguously *within itself*: no
    /// two templates in a family share a name or a map glyph.
    ///
    /// This replaces five near-identical per-family checks that had
    /// accumulated one subclass at a time (the wizard traditions, plus
    /// an inline block inside each of the fighter / monk / rogue / druid
    /// drift pins). Each was the same twelve lines with a different
    /// import list, and each only covered the family whose newest member
    /// prompted it — so barbarian, bard, cleric, paladin, ranger,
    /// sorcerer and warlock were never checked at all despite carrying
    /// thirteen, five, eight, seven, seven, six and ten templates.
    ///
    /// The scope is deliberately per-family rather than global.
    /// Cross-family glyph collisions are an explicit policy of the
    /// template docs — Samurai Fighter 'S' shares with Tempest Cleric
    /// 'S', Scout Rogue 'K' with Killer Whale, Assassin Rogue 'A' with
    /// Ape — because the team colour and team id disambiguate them on
    /// the map. What is *not* acceptable is two members of one class
    /// family colliding, since those are exactly the templates a player
    /// sets against each other by name and reads side by side in an
    /// initiative list.
    ///
    /// A new subclass template lands as one row on the family it joins.
    #[test]
    fn every_pc_class_family_renders_unambiguously() {
        let families = crate::actors::creatures::pc_template_families();
        for (label, family) in families {
            let names: std::collections::HashSet<&str> =
                family.iter().map(|t| t.name).collect();
            assert_eq!(
                names.len(),
                family.len(),
                "two {} templates share a name",
                label
            );
            let glyphs: std::collections::HashSet<char> =
                family.iter().map(|t| t.glyph).collect();
            assert_eq!(
                glyphs.len(),
                family.len(),
                "two {} templates share a glyph: {:?}",
                label,
                family.iter().map(|t| (t.name, t.glyph)).collect::<Vec<_>>()
            );
        }
    }

    /// The second hole in the same invariant: an actor who dies on their
    /// own turn vacates their initiative index without an
    /// `advance_initiative`, and `InitiativeTracker::remove_actor` lets
    /// the next actor slide into it. That actor gets prompted off a slot
    /// change nothing announced, so before `ensure_turn_started` they
    /// acted with no turn start — carrying whatever action economy was
    /// left from their previous turn, with `UntilStartOfNextTurn`
    /// conditions unexpired and recharge abilities un-rolled.
    ///
    /// Four actors, two per team, so killing the leader leaves both
    /// teams standing and the encounter still wants a prompt. Which
    /// actor leads is seed-dependent, so the test kills whoever it is.
    #[test]
    fn dying_on_your_own_turn_still_starts_the_next_actors_turn() {
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::actors::creatures::skeletons::SKELETON_TEMPLATE;

        let mut e = ei_with_terrain(20, 20, &[]);
        let mut ids = Vec::new();
        for (i, (tpl, team)) in [
            (&*GOBLIN_TEMPLATE, 0usize),
            (&*GOBLIN_TEMPLATE, 0),
            (&*SKELETON_TEMPLATE, 1),
            (&*SKELETON_TEMPLATE, 1),
        ]
        .into_iter()
        .enumerate()
        {
            ids.push(
                e.instantiate_creature(
                    tpl,
                    Coordinate::new(2 + (i as isize) * 4, 2),
                    team,
                    i,
                )
                .unwrap(),
            );
        }
        e.process_stack();
        let leader = e.peek_prompt().map(|p| p.actor_id()).expect("a prompt");
        e.pop_prompt();
        // The actor next in line hasn't had a turn yet.
        let next = e.initiative_actor_ids()[1];
        assert_ne!(next, leader);
        assert!(!e.actors[&next].has_taken_turn_in_combat());

        // Kill the leader from *inside* a `process_stack` drain, the way
        // a damage reflect resolving off the leader's own swing does.
        // Queueing the damage as a side-effect rather than mutating HP
        // directly is what makes this exercise the pre-prompt half of
        // the fix: the slot changes after `process_stack` has already
        // opened the leader's turn, so only the second
        // `ensure_turn_started` can catch it.
        let hp = e.actors[&leader].max_hitpoints() + 1;
        e.enqueue_event(StackElementEntry::SideEffect(Box::new(
            crate::engine::side_effects::DealDamage {
                actor_id: leader,
                amount: hp,
                damage_type: DamageType::Slashing,
            },
        )));
        e.process_stack();
        assert!(!e.actors.contains_key(&leader), "leader is gone");
        let prompted = e
            .peek_prompt()
            .map(|p| p.actor_id())
            .expect("the next actor is prompted");
        assert_eq!(prompted, next, "the slot passes to the next actor in line");
        assert!(
            e.actors[&next].has_taken_turn_in_combat(),
            "and their turn is actually opened rather than inherited"
        );
    }

