    /// Wild Shape hands over the beast body and takes the spell list in
    /// exchange: temp HP lands, the claws unlock, and every levelled
    /// spell stops being affordable. Reverting restores all three.
    #[test]
    fn wild_shape_trades_the_spell_list_for_a_beast_body() {
        use crate::actions::class_features::WILD_SHAPE;
        use crate::actions::spells::MOONBEAM;
        use crate::actors::creatures::druids::MOON_DRUID_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::conditions::Condition;
        use crate::engine::side_effects::Resource;

        let mut e = ei_with_terrain(15, 15, &[]);
        let druid = e
            .instantiate_creature(&MOON_DRUID_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let target = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(4, 2), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&druid)
            .unwrap()
            .give_resource(Resource::BonusAction);

        // Out of form: the claws are refused and the spell list works.
        let targets = vec![target];
        assert!(
            !crate::actions::class_attacks::BEAST_FORM_CLAWS
                .validate_input(&e, druid, Some(&targets), None, None),
            "no claws without a beast body"
        );
        assert!(
            e.actors[&druid].can_consume_resource(Resource::SpellSlot(2)),
            "a druid out of shape casts normally"
        );

        assert!(WILD_SHAPE.validate_input(&e, druid, None, None, None));
        let effects = WILD_SHAPE.execute(&mut e, druid, None, None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        assert!(e.actors[&druid].has_condition(Condition::WildShaped));
        assert_eq!(
            e.actors[&druid].temp_hp(),
            34,
            "the brown bear's hit points arrive as the form's pool"
        );
        assert!(
            crate::actions::class_attacks::BEAST_FORM_CLAWS
                .validate_input(&e, druid, Some(&targets), None, None),
            "the form unlocks its natural weapon"
        );
        // The cost: RAW's "you can't cast spells", via the same
        // `blocks_spell_slots` gate the Silence spell uses.
        assert!(
            !e.actors[&druid].can_consume_resource(Resource::SpellSlot(2)),
            "a bear casts nothing"
        );
        assert!(
            !MOONBEAM.validate_input(
                &e,
                druid,
                None,
                Some(&vec![Coordinate::new(6, 2)]),
                None
            ),
            "and the spell list refuses at the action layer too"
        );
        // The charge is spent, so the button doesn't re-fire.
        assert!(!WILD_SHAPE.validate_input(&e, druid, None, None, None));

        // Reverting gives everything back.
        e.actors
            .get_mut(&druid)
            .unwrap()
            .remove_condition(Condition::WildShaped);
        assert!(e.actors[&druid].can_consume_resource(Resource::SpellSlot(2)));
        assert!(
            !crate::actions::class_attacks::BEAST_FORM_CLAWS
                .validate_input(&e, druid, Some(&targets), None, None)
        );
    }

    /// Wild Heal burns the lowest slot for `level`d8 HP, and does it
    /// *through* the can't-cast gate the form imposes — the whole point
    /// of draining the slot manager directly rather than declaring a
    /// `SpellSlot` cost.
    #[test]
    fn wild_heal_spends_a_slot_the_form_would_otherwise_block() {
        use crate::actions::class_features::WILD_HEAL;
        use crate::actors::creatures::druids::MOON_DRUID_TEMPLATE;
        use crate::conditions::Condition;
        use crate::engine::side_effects::Resource;

        let mut e = ei_with_terrain(15, 15, &[]);
        let druid = e
            .instantiate_creature(&MOON_DRUID_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        {
            let a = e.actors.get_mut(&druid).unwrap();
            a.give_resource(Resource::BonusAction);
            a.give_resource(Resource::BonusAction);
        }
        // Install the form directly rather than through `WILD_SHAPE`:
        // the real button also grants 34 temp HP, which would absorb
        // the wound this test needs to be healing. What's under test is
        // the conversion, not the transform.
        {
            let a = e.actors.get_mut(&druid).unwrap();
            a.add_condition(Condition::WildShaped, ConditionTimer::Rounds(10));
            let _ = a.take_damage(20);
        }
        let hp_before = e.actors[&druid].hitpoints();
        assert!(hp_before < e.actors[&druid].max_hitpoints());
        let slots_before = e.actors[&druid].lowest_available_spell_slot();
        assert_eq!(slots_before, Some(1), "lowest slot first");

        assert!(WILD_HEAL.validate_input(&e, druid, None, None, None));
        let effects = WILD_HEAL.execute(&mut e, druid, None, None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        assert!(
            e.actors[&druid].hitpoints() > hp_before,
            "the conversion actually heals"
        );
        assert_eq!(
            e.actors[&druid]
                .spell_slot_manager
                .spell_slots(1)
                .spell_slots,
            MOON_DRUID_TEMPLATE.spell_slots_by_level[0] - 1,
            "exactly one level-1 slot burned"
        );
    }

    /// Wild Heal is form-gated and full-HP-gated: a druid out of shape
    /// can't reach it at all, and a druid at full HP shouldn't burn a
    /// slot for nothing.
    #[test]
    fn wild_heal_declines_out_of_form_and_at_full_health() {
        use crate::actions::class_features::WILD_HEAL;
        use crate::actors::creatures::druids::MOON_DRUID_TEMPLATE;
        use crate::conditions::Condition;
        use crate::engine::side_effects::Resource;

        let mut e = ei_with_terrain(15, 15, &[]);
        let druid = e
            .instantiate_creature(&MOON_DRUID_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        e.actors
            .get_mut(&druid)
            .unwrap()
            .give_resource(Resource::BonusAction);
        e.actors
            .get_mut(&druid)
            .unwrap()
            .take_damage(20);
        assert!(
            !WILD_HEAL.validate_input(&e, druid, None, None, None),
            "wounded but not in form"
        );

        {
            let a = e.actors.get_mut(&druid).unwrap();
            a.add_condition(Condition::WildShaped, ConditionTimer::Rounds(10));
        }
        assert!(WILD_HEAL.validate_input(&e, druid, None, None, None));

        // Top back up: nothing to convert a slot into.
        let max = e.actors[&druid].max_hitpoints();
        e.actors.get_mut(&druid).unwrap().heal(max);
        assert!(
            !WILD_HEAL.validate_input(&e, druid, None, None, None),
            "in form but at full HP"
        );
    }

    /// Shadow Monk template drift pin. Name / glyph uniqueness across
    /// the monk family is covered family-wide by
    /// `every_pc_class_family_renders_unambiguously`.
    #[test]
    fn shadow_monk_ships_its_kit_and_inherits_the_monk_chassis() {
        use crate::actions::class_features::{
            EMPTY_BODY_TAG, SHADOW_ARTS_TAG, SHADOW_STEP_TAG, STUNNING_STRIKE_TAG,
            UNARMORED_MOVEMENT_TAG,
        };
        use crate::actors::creatures::monks::{
            MONK_TEMPLATE, SHADOW_MONK_TEMPLATE,
        };
        let mut e = ei_with_terrain(15, 15, &[]);
        let monk = e
            .instantiate_creature(&SHADOW_MONK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        for tag in [SHADOW_ARTS_TAG, SHADOW_STEP_TAG] {
            assert!(
                e.actors[&monk].has_passive_feature(tag),
                "Shadow Monk should carry {}",
                tag
            );
        }
        // Baseline chassis rides through the clone tail.
        for tag in [STUNNING_STRIKE_TAG, EMPTY_BODY_TAG, UNARMORED_MOVEMENT_TAG] {
            assert!(
                e.actors[&monk].has_passive_feature(tag),
                "Shadow Monk should inherit baseline Monk tag {}",
                tag
            );
        }
        assert!(e.actors[&monk].has_evasion());
        assert!(e.actors[&monk].has_extra_attack());
        for name in ["shadow step", "silence", "pass without trace", "flurry of blows"] {
            assert!(
                e.actors[&monk].find_action(name).is_some(),
                "Shadow Monk should carry the {} action",
                name
            );
        }
        // The slot table is Shadow Arts' ki budget: no level-1 slots,
        // two level-2s — exactly two casts and no other magic.
        assert_eq!(
            SHADOW_MONK_TEMPLATE.spell_slots_by_level,
            vec![0, 2],
            "two level-2 slots, no level-1"
        );
        assert!(
            MONK_TEMPLATE.spell_slots_by_level.is_empty(),
            "the baseline monk stays slotless"
        );

    }

    /// Shadow Step teleports the monk and arms the melee-only advantage
    /// prime — which reads as Advantage on a melee swing, Normal on a
    /// ranged one, and is gone after the first attack either way.
    #[test]
    fn shadow_step_teleports_and_arms_a_melee_only_prime() {
        use crate::actions::class_features::SHADOW_STEP;
        use crate::actors::creatures::monks::SHADOW_MONK_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::conditions::Condition;
        use crate::engine::side_effects::Resource;

        let mut e = ei_with_terrain(20, 20, &[]);
        let monk = e
            .instantiate_creature(&SHADOW_MONK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let target = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(12, 2), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&monk)
            .unwrap()
            .give_resource(Resource::BonusAction);

        // Medium creatures are 2x2 on this 2.5 ft grid. Land clear of
        // the zombie rather than beside it: the point of the assertions
        // below is the Shadow Step prime alone, and standing in contact
        // would fold the "ranged attacks while a hostile is adjacent"
        // disadvantage into the ranged reading.
        let dest = vec![Coordinate::new(6, 2)];
        assert!(SHADOW_STEP.validate_input(&e, monk, None, Some(&dest), None));
        let effects = SHADOW_STEP.execute(&mut e, monk, None, Some(&dest), None);
        for ef in effects {
            ef.apply(&mut e);
        }
        assert_eq!(
            e.actors[&monk].location(),
            Coordinate::new(6, 2),
            "the monk arrives where they aimed"
        );
        assert!(e.actors[&monk].has_condition(Condition::Shadowstepping));
        // Melee reads Advantage; ranged reads Normal — the whole reason
        // this rides its own melee-gated cohort rather than the broader
        // `grants_self_attack_advantage` one its siblings use.
        assert_eq!(
            e.compute_attack_mode(monk, target, false),
            RollMode::Normal,
            "a ranged swing collects nothing from Shadow Step"
        );
        assert_eq!(
            e.compute_attack_mode(monk, target, true),
            RollMode::Advantage,
            "a melee swing collects the prime"
        );
        // One-shot.
        e.clear_attack_advantage_riders(monk, target);
        assert!(!e.actors[&monk].has_condition(Condition::Shadowstepping));
        assert_eq!(e.compute_attack_mode(monk, target, true), RollMode::Normal);
    }

