    /// Magical Ambush bends the first save against a Hidden trickster's
    /// spell and spends the concealment doing it. A trickster who isn't
    /// hidden, and a hidden rogue without the tag, both read clean.
    #[test]
    fn magical_ambush_fires_only_while_hidden_and_spends_the_hiding() {
        use crate::actors::creatures::rogues::{ARCANE_TRICKSTER_ROGUE_TEMPLATE, ROGUE_TEMPLATE};
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::conditions::{Condition, ConditionTimer};
        use crate::engine::types::AbilityScoreType;

        let mut e = ei_with_terrain(15, 15, &[]);
        let trickster = e
            .instantiate_creature(&ARCANE_TRICKSTER_ROGUE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let plain = e
            .instantiate_creature(&ROGUE_TEMPLATE, Coordinate::new(3, 2), 0, 1)
            .unwrap();
        let target = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(8, 8), 1, 0)
            .unwrap();

        // Not hidden: nothing fires.
        let _ = e.roll_save_against_caster(target, AbilityScoreType::Wisdom, 15, trickster);

        // Hidden trickster: the rider fires and burns the concealment,
        // the same way an attack roll would.
        e.actors
            .get_mut(&trickster)
            .unwrap()
            .add_condition(Condition::Hidden, ConditionTimer::Rounds(5));
        let _ = e.roll_save_against_caster(target, AbilityScoreType::Wisdom, 15, trickster);
        assert!(
            !e.actors[&trickster].has_condition(Condition::Hidden),
            "casting from hiding gives the position away"
        );

        // Hidden, but no tag: the concealment survives, because nothing
        // consumed it.
        e.actors
            .get_mut(&plain)
            .unwrap()
            .add_condition(Condition::Hidden, ConditionTimer::Rounds(5));
        let _ = e.roll_save_against_caster(target, AbilityScoreType::Wisdom, 15, plain);
        assert!(
            e.actors[&plain].has_condition(Condition::Hidden),
            "a rogue without the tag doesn't fire the rider, so nothing is spent"
        );
    }

    /// Versatile Trickster installs the self-help-grant that
    /// `attack_mode_with_riders` turns into advantage on the next swing,
    /// and the grant is single-use.
    #[test]
    fn versatile_trickster_grants_advantage_on_the_next_swing() {
        use crate::actions::class_features::VERSATILE_TRICKSTER;
        use crate::actors::creatures::rogues::ARCANE_TRICKSTER_ROGUE_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        use crate::engine::side_effects::Resource;

        let mut e = ei_with_terrain(15, 15, &[]);
        let rogue = e
            .instantiate_creature(&ARCANE_TRICKSTER_ROGUE_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let target = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(4, 2), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&rogue)
            .unwrap()
            .give_resource(Resource::BonusAction);
        let targets = vec![target];
        assert!(VERSATILE_TRICKSTER.validate_input(&e, rogue, Some(&targets), None, None));
        let effects = VERSATILE_TRICKSTER.execute(&mut e, rogue, Some(&targets), None, None);
        for ef in effects {
            ef.apply(&mut e);
        }
        assert!(
            e.actors[&rogue].help_grant(target),
            "the designation lands as a self-help-grant"
        );
        assert_eq!(
            e.attack_mode_with_riders(rogue, target, true),
            RollMode::Advantage,
            "and reads as advantage on the swing that follows"
        );
        assert!(
            !e.actors[&rogue].help_grant_any(),
            "consumed by the swing — a second attack doesn't re-use it"
        );
    }

    /// Weapon Bond bounces the Disarmed install — but only while the
    /// knight is on their feet. Incapacitating them (RAW's carve-out)
    /// hands the disarm straight back.
    #[test]
    fn weapon_bond_blocks_disarm_unless_incapacitated() {
        use crate::actors::creatures::fighters::{
            ELDRITCH_KNIGHT_FIGHTER_TEMPLATE, FIGHTER_TEMPLATE,
        };
        use crate::conditions::{Condition, ConditionTimer};

        let mut e = ei_with_terrain(15, 15, &[]);
        let knight = e
            .instantiate_creature(&ELDRITCH_KNIGHT_FIGHTER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let plain = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(4, 2), 0, 1)
            .unwrap();

        // Bonded: the disarm bounces.
        e.actors
            .get_mut(&knight)
            .unwrap()
            .add_condition(Condition::Disarmed, ConditionTimer::Rounds(1));
        assert!(!e.actors[&knight].has_condition(Condition::Disarmed));

        // Control: a fighter without the bond eats it.
        e.actors
            .get_mut(&plain)
            .unwrap()
            .add_condition(Condition::Disarmed, ConditionTimer::Rounds(1));
        assert!(e.actors[&plain].has_condition(Condition::Disarmed));

        // RAW carve-out: an incapacitated knight loses the bond.
        {
            let a = e.actors.get_mut(&knight).unwrap();
            a.add_condition(Condition::Stunned, ConditionTimer::Rounds(1));
            a.add_condition(Condition::Disarmed, ConditionTimer::Rounds(1));
        }
        assert!(
            e.actors[&knight].has_condition(Condition::Disarmed),
            "a stunned knight can be disarmed"
        );
    }

    /// 5e Paladin Oath of the Ancients Nature's Ward (lv15): passive
    /// self-immunity to Charmed AND Frightened installs. Baseline
    /// paladin doesn't get it — a plain paladin still takes both.
    #[test]
    fn natures_ward_grants_charm_and_frighten_immunity() {
        use crate::actors::creatures::paladins::{
            ANCIENTS_PALADIN_TEMPLATE, PALADIN_TEMPLATE,
        };
        use crate::conditions::ConditionTimer;
        use crate::engine::side_effects::{ApplicableSideEffect, ApplyCondition};
        let mut e = ei_with_terrain(15, 15, &[]);
        let ancients = e
            .instantiate_creature(&ANCIENTS_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let baseline = e
            .instantiate_creature(&PALADIN_TEMPLATE, Coordinate::new(12, 12), 1, 0)
            .unwrap();
        // Ancients Paladin: both Charmed and Frightened bounce.
        ApplyCondition {
            actor_id: ancients,
            condition: Condition::Charmed,
            timer: ConditionTimer::Rounds(3),
        }
        .apply(&mut e);
        assert!(!e.actors[&ancients].has_condition(Condition::Charmed));
        ApplyCondition {
            actor_id: ancients,
            condition: Condition::Frightened,
            timer: ConditionTimer::Rounds(3),
        }
        .apply(&mut e);
        assert!(!e.actors[&ancients].has_condition(Condition::Frightened));
        // Baseline paladin has Aura of Courage (self-in-aura → Frightened
        // suppressed), but NOT Nature's Ward — Charmed still lands (Aura
        // of Devotion is Devotion-subclass-only, not on baseline).
        ApplyCondition {
            actor_id: baseline,
            condition: Condition::Charmed,
            timer: ConditionTimer::Rounds(3),
        }
        .apply(&mut e);
        assert!(e.actors[&baseline].has_condition(Condition::Charmed));
    }

    /// Ancients Paladin's Nature's Ward is self-only — it does NOT
    /// project to allies (unlike Aura of Devotion which extends Charmed
    /// immunity to a 10ft ally bubble). An ally standing right next to
    /// the Ancients Paladin still catches a Charmed install.
    #[test]
    fn natures_ward_does_not_cover_allies() {
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::actors::creatures::paladins::ANCIENTS_PALADIN_TEMPLATE;
        use crate::conditions::ConditionTimer;
        use crate::engine::side_effects::{ApplicableSideEffect, ApplyCondition};
        let mut e = ei_with_terrain(15, 15, &[]);
        let _pal = e
            .instantiate_creature(&ANCIENTS_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let ally = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(3, 3), 0, 0)
            .unwrap();
        // Adjacent ally still picks up Charmed — Nature's Ward is
        // self-only, not aura-projected. The paladin's Aura of Courage
        // WOULD block Frightened on this ally (baseline paladin auras
        // still fire), so test with Charmed which the baseline paladin
        // doesn't aura-suppress.
        ApplyCondition {
            actor_id: ally,
            condition: Condition::Charmed,
            timer: ConditionTimer::Rounds(3),
        }
        .apply(&mut e);
        assert!(e.actors[&ally].has_condition(Condition::Charmed));
    }

    /// 5e Monk Empty Body (lv18): action, once per long rest. Installs
    /// Invisible and DamageResistant on the monk for 10 rounds. Both
    /// installs land in a single side-effect batch; the feature charge
    /// is consumed the moment the effects fire.
    #[test]
    fn empty_body_installs_invisible_and_damage_resistant() {
        use crate::actions::action_template::Action;
        use crate::actions::class_features::{EMPTY_BODY, EMPTY_BODY_TAG};
        use crate::actors::creatures::monks::MONK_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let monk = e
            .instantiate_creature(&MONK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        assert!(e.actors[&monk].feature_available(EMPTY_BODY_TAG));
        // Validate the gate and drive the side effects manually — same
        // shape the encounter loop uses for every other action.
        let action: &dyn Action = &*EMPTY_BODY;
        assert!(action.custom_validate_input(&e, monk, None, None, None));
        let effects = action.side_effects(&mut e, monk, None, None, None);
        for eff in effects {
            eff.apply(&mut e);
        }
        assert!(e.actors[&monk].has_condition(Condition::Invisible));
        assert!(e.actors[&monk].has_condition(Condition::DamageResistant));
        // Feature charge consumed — the gate must now fail so a
        // duplicate queued use doesn't slip through.
        assert!(!e.actors[&monk].feature_available(EMPTY_BODY_TAG));
        assert!(!action.custom_validate_input(&e, monk, None, None, None));
    }

    /// 5e Fighting Style: **Archery** (Ranger lv2 pick): passive +2 to
    /// attack rolls with ranged weapons. Ships on the RANGER_TEMPLATE.
    /// The flag reads at `resolve_attack` gated on `!is_melee && !is_spell`
    /// so a longbow shot picks up the bonus but a spell attack doesn't.
    #[test]
    fn archery_style_ships_on_ranger_template() {
        use crate::actors::creatures::rangers::{HUNTER_RANGER_TEMPLATE, RANGER_TEMPLATE};
        use crate::actors::creatures::rogues::ROGUE_TEMPLATE;
        let ranger = ActorInstance::from_creature_template(
            &RANGER_TEMPLATE,
            Coordinate::new(0, 0),
            0,
            &mut FastRandRoller::with_seed(1),
            0,
        )
        .unwrap();
        assert!(
            ranger.has_archery_style(),
            "baseline ranger ships archery style"
        );
        let hunter = ActorInstance::from_creature_template(
            &HUNTER_RANGER_TEMPLATE,
            Coordinate::new(0, 0),
            0,
            &mut FastRandRoller::with_seed(1),
            0,
        )
        .unwrap();
        assert!(
            hunter.has_archery_style(),
            "Hunter Ranger subclass inherits archery style from base"
        );
        // The rogue (a DEX-primary shortsword user) doesn't get archery
        // — the style is a Ranger / Fighter / Paladin pick per RAW, not
        // a rogue class feature.
        let rogue = ActorInstance::from_creature_template(
            &ROGUE_TEMPLATE,
            Coordinate::new(0, 0),
            0,
            &mut FastRandRoller::with_seed(1),
            0,
        )
        .unwrap();
        assert!(
            !rogue.has_archery_style(),
            "rogue must not read as archery-styled"
        );
    }

    /// 5e Fighting Style: **Defense** (Fighter / Paladin lv1 pick):
    /// passive +1 AC. Ships on CHAMPION + PALADIN. The read chokepoint
    /// is `ActorInstance::armor_class` — the +1 folds into the base AC
    /// lane before the AC-floor comparison, so a Champion's baseline
    /// AC 18 (plate) becomes AC 19 with the style pick.
    #[test]
    fn defense_style_bumps_armor_class_by_one() {
        use crate::actors::creatures::fighters::CHAMPION_TEMPLATE;
        let mut e = ei_with_terrain(10, 10, &[]);
        let champ = e
            .instantiate_creature(&CHAMPION_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        assert!(
            e.actors[&champ].has_defense_style(),
            "champion template ships defense style"
        );
        // Champion template's base_ac field is 18 (plate). The +1 from
        // Defense pushes the read to 19. Read via the same chokepoint
        // that attack rolls hit — `armor_class`.
        assert_eq!(e.actors[&champ].armor_class(), 19);
    }

    /// Defense style read is INDEPENDENT of any condition-side AC bonus:
    /// a Champion Fighter with Shield of Faith (+2) reads AC 21, not 20,
    /// because Defense is a base-AC lane and Shield of Faith is a
    /// condition-AC lane — they stack additively.
    #[test]
    fn defense_style_stacks_with_condition_ac_sources() {
        use crate::actors::creatures::fighters::CHAMPION_TEMPLATE;
        let mut e = ei_with_terrain(10, 10, &[]);
        let champ = e
            .instantiate_creature(&CHAMPION_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let base = e.actors[&champ].armor_class();
        // Install Shield of Faith (a +2 condition-lane AC bonus).
        e.actors.get_mut(&champ).unwrap().add_condition(
            Condition::ShieldOfFaith,
            ConditionTimer::Rounds(3),
        );
        assert_eq!(e.actors[&champ].armor_class(), base + 2);
    }

