    /// 5e Warlock Fiend Patron **Dark One's Blessing** (lv1 subclass):
    /// passive: when the warlock's swing reduces a hostile to 0 HP,
    /// they gain `max(1, CHA mod + level)` temp HP. Verifies the temp
    /// HP grant lands on kill via a direct DealDamage burn (side-steps
    /// the seed sweep of the attack pipeline — the trigger fires on
    /// the outcome, not on a specific attack path).
    #[test]
    fn dark_ones_blessing_grants_temp_hp_on_hostile_kill() {
        use crate::actions::class_features::DARK_ONES_BLESSING_TAG;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::actors::creatures::warlocks::FIEND_WARLOCK_TEMPLATE;
        use crate::engine::side_effects::{ApplicableSideEffect, DealDamage};
        let mut e = ei_with_terrain(15, 15, &[]);
        let w = e
            .instantiate_creature(&FIEND_WARLOCK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        assert!(e.actors[&w].has_passive_feature(DARK_ONES_BLESSING_TAG));
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(3, 2), 1, 0)
            .unwrap();
        // Seed the initiative slot so `current_turn_actor_id` returns
        // the warlock — the trigger keys off whose turn it is at the
        // damage-apply site. `ei_with_terrain` already initialized the
        // encounter; the instantiate calls above wired both actors
        // into the initiative tracker at their rolled slots.
        // Advance until the warlock's slot is up. In a two-actor
        // encounter the tracker will land on the warlock after at
        // most one advance.
        while e.current_turn_actor_id() != Some(w) {
            e.skip_turn();
        }
        assert_eq!(e.actors[&w].temp_hp(), 0);
        let goblin_hp = e.actors[&g].hitpoints();
        DealDamage {
            actor_id: g,
            amount: goblin_hp + 100,
            damage_type: crate::engine::types::DamageType::Force,
        }
        .apply(&mut e);
        // Expected temp HP = max(1, CHA mod + level). Warlock CHA 18
        // → +4; the template's HP dice give the warlock ~level 8 in
        // our engine (8d8+8 = 8 dice). Compute against the actual
        // template to stay resilient to level shifts.
        let expected = {
            let a = &e.actors[&w];
            let mod_ = a.ability_modifier(crate::engine::types::AbilityScoreType::Charisma);
            let lvl = a.level() as i32;
            (mod_ + lvl).max(1) as u32
        };
        // Use >= to accommodate any future template level bump making
        // the pool larger; the load-bearing check is "temp HP > 0".
        assert!(
            e.actors[&w].temp_hp() >= expected,
            "expected at least {} temp HP (CHA + level), got {}",
            expected,
            e.actors[&w].temp_hp()
        );
    }

    /// Dark One's Blessing does NOT fire on a same-team kill —
    /// friendly-fire drops shouldn't reward the warlock. RAW gates
    /// the temp-HP grant on "hostile creature" — the team-distinct
    /// filter is our closest engine proxy.
    #[test]
    fn dark_ones_blessing_does_not_fire_on_friendly_kill() {
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::actors::creatures::warlocks::FIEND_WARLOCK_TEMPLATE;
        use crate::engine::side_effects::{ApplicableSideEffect, DealDamage};
        let mut e = ei_with_terrain(15, 15, &[]);
        let w = e
            .instantiate_creature(&FIEND_WARLOCK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // Ally goblin on team 0 (same team as warlock).
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(3, 2), 0, 1)
            .unwrap();
        // ei_with_terrain already initialized the encounter; the
        // instantiate_creature calls above wired the warlock + target
        // into the initiative tracker at their rolled slots. Advance
        // the tracker until the warlock's slot is up.
        while e.current_turn_actor_id() != Some(w) {
            e.skip_turn();
        }
        assert_eq!(e.actors[&w].temp_hp(), 0);
        let goblin_hp = e.actors[&g].hitpoints();
        DealDamage {
            actor_id: g,
            amount: goblin_hp + 100,
            damage_type: crate::engine::types::DamageType::Force,
        }
        .apply(&mut e);
        assert_eq!(
            e.actors[&w].temp_hp(),
            0,
            "Dark One's Blessing should NOT fire on a same-team kill"
        );
    }

    /// The shared once-per-turn rider ledger cleanly separates its
    /// registered tags — a Sneak Attack mark doesn't accidentally
    /// suppress a Colossus Slayer / Foe Slayer / Divine Fury / Dreadful
    /// Strikes / Psychic Blades / Planar Warrior / Slayer's Prey /
    /// Gathered Swarm / Psionic Strike / Ancestral Protectors swing (and
    /// vice versa). Locks the HashSet-backed
    /// decoupling that the pre-refactor bool cohort trivially had by
    /// construction.
    #[test]
    fn once_per_turn_rider_ledger_tags_are_independent() {
        use crate::actions::class_features::{
            ANCESTRAL_PROTECTORS_TAG, COLOSSUS_SLAYER_TAG, DEFT_STRIKE_TAG, DIVINE_FURY_TAG,
            DREADFUL_STRIKES_TAG, FOE_SLAYER_TAG, FORM_OF_DREAD_TAG, GATHERED_SWARM_TAG,
            GIANTS_MIGHT_RIDER_TAG, ONCE_PER_TURN_RIDER_TAGS, PLANAR_WARRIOR_TAG,
            PSIONIC_STRIKE_TAG, PSYCHIC_BLADES_TAG, SLAYERS_PREY_TAG, SNEAK_ATTACK_TAG,
        };
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        // Sanity: the registry lists every named tag we're checking so
        // this test also pins the cohort inventory.
        assert_eq!(
            ONCE_PER_TURN_RIDER_TAGS.len(),
            14,
            "once-per-turn rider tag registry drifted"
        );
        assert!(ONCE_PER_TURN_RIDER_TAGS.contains(&ANCESTRAL_PROTECTORS_TAG));
        assert!(ONCE_PER_TURN_RIDER_TAGS.contains(&FORM_OF_DREAD_TAG));
        assert!(ONCE_PER_TURN_RIDER_TAGS.contains(&DEFT_STRIKE_TAG));
        assert!(ONCE_PER_TURN_RIDER_TAGS.contains(&GIANTS_MIGHT_RIDER_TAG));
        assert!(ONCE_PER_TURN_RIDER_TAGS.contains(&SNEAK_ATTACK_TAG));
        assert!(ONCE_PER_TURN_RIDER_TAGS.contains(&COLOSSUS_SLAYER_TAG));
        assert!(ONCE_PER_TURN_RIDER_TAGS.contains(&FOE_SLAYER_TAG));
        assert!(ONCE_PER_TURN_RIDER_TAGS.contains(&DIVINE_FURY_TAG));
        assert!(ONCE_PER_TURN_RIDER_TAGS.contains(&DREADFUL_STRIKES_TAG));
        assert!(ONCE_PER_TURN_RIDER_TAGS.contains(&PSYCHIC_BLADES_TAG));
        assert!(ONCE_PER_TURN_RIDER_TAGS.contains(&PSIONIC_STRIKE_TAG));
        assert!(ONCE_PER_TURN_RIDER_TAGS.contains(&PLANAR_WARRIOR_TAG));
        assert!(ONCE_PER_TURN_RIDER_TAGS.contains(&SLAYERS_PREY_TAG));
        assert!(ONCE_PER_TURN_RIDER_TAGS.contains(&GATHERED_SWARM_TAG));

        let mut e = ei_with_terrain(15, 15, &[]);
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();

        // Every tag starts unmarked.
        for tag in ONCE_PER_TURN_RIDER_TAGS {
            assert!(!e.actors[&g].once_per_turn_used(tag));
        }
        // Marking Sneak Attack does not leak into the other three tags.
        e.actors.get_mut(&g).unwrap().mark_sneak_attack_used();
        assert!(e.actors[&g].sneak_attack_used());
        assert!(!e.actors[&g].colossus_slayer_used());
        assert!(!e.actors[&g].foe_slayer_used());
        assert!(!e.actors[&g].divine_fury_used());

        // Adding Foe Slayer preserves the earlier Sneak Attack mark.
        e.actors.get_mut(&g).unwrap().mark_foe_slayer_used();
        assert!(e.actors[&g].sneak_attack_used());
        assert!(e.actors[&g].foe_slayer_used());
        assert!(!e.actors[&g].colossus_slayer_used());
        assert!(!e.actors[&g].divine_fury_used());

        // `reset_for_new_round` clears the whole cohort in one call.
        e.actors.get_mut(&g).unwrap().reset_for_new_round();
        for tag in ONCE_PER_TURN_RIDER_TAGS {
            assert!(
                !e.actors[&g].once_per_turn_used(tag),
                "reset_for_new_round should clear {}",
                tag
            );
        }
    }

    /// Drift-prevention: every tag that drives a row in the shared
    /// `ONCE_PER_TURN_WEAPON_DIE_RIDERS` cohort in `engine::attack` MUST
    /// also be registered in the sibling `ONCE_PER_TURN_RIDER_TAGS`
    /// ledger list in `class_features`. Without this invariant, a new
    /// rider-spec row (Colossus Slayer / Dreadful Strikes / Psychic
    /// Blades / Planar Warrior / Slayer's Prey / Gathered Swarm today
    /// — and any future addition) could be added to the cohort without
    /// its tag reaching the `reset_for_new_round` clear-all loop, and
    /// the ledger would stay flipped across turns after the first fire
    /// (silent "once per encounter" instead of "once per turn"). The
    /// two arrays live in different modules for good reason (the spec
    /// carries a `Dice` type that lives in `engine`, while the tag
    /// list has to be readable by `ActorInstance` in `actors`), so a
    /// hard invariant test pins the two halves together at the compile-
    /// check level.
    #[test]
    fn every_weapon_die_rider_tag_is_registered_in_the_ledger_list() {
        use crate::actions::class_features::ONCE_PER_TURN_RIDER_TAGS;
        use crate::engine::attack::ONCE_PER_TURN_WEAPON_DIE_RIDERS;
        for spec in ONCE_PER_TURN_WEAPON_DIE_RIDERS {
            assert!(
                ONCE_PER_TURN_RIDER_TAGS.contains(&spec.tag),
                "rider spec tag {} missing from ONCE_PER_TURN_RIDER_TAGS — \
                 reset_for_new_round would not clear it",
                spec.tag,
            );
        }
    }

    /// Dark One's Blessing does NOT fire when the swinging actor
    /// lacks the tag. Verifies a baseline WARLOCK_TEMPLATE (which
    /// doesn't ship the Fiend patron feature) doesn't accidentally
    /// get the temp-HP well.
    #[test]
    fn dark_ones_blessing_does_not_fire_on_baseline_warlock_kill() {
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::actors::creatures::warlocks::WARLOCK_TEMPLATE;
        use crate::engine::side_effects::{ApplicableSideEffect, DealDamage};
        let mut e = ei_with_terrain(15, 15, &[]);
        let w = e
            .instantiate_creature(&WARLOCK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(3, 2), 1, 0)
            .unwrap();
        // ei_with_terrain already initialized the encounter; the
        // instantiate_creature calls above wired the warlock + target
        // into the initiative tracker at their rolled slots. Advance
        // the tracker until the warlock's slot is up.
        while e.current_turn_actor_id() != Some(w) {
            e.skip_turn();
        }
        let goblin_hp = e.actors[&g].hitpoints();
        DealDamage {
            actor_id: g,
            amount: goblin_hp + 100,
            damage_type: crate::engine::types::DamageType::Force,
        }
        .apply(&mut e);
        assert_eq!(
            e.actors[&w].temp_hp(),
            0,
            "baseline Warlock (no Fiend patron tag) shouldn't get temp HP on kill"
        );
    }

    /// 5e Long Death Monk **Touch of Death** (lv3 subclass tell):
    /// passive: when the monk's swing reduces a hostile to 0 HP, they
    /// gain `max(1, 1 + CON mod + monk level)` temp HP. Sibling to the
    /// Dark One's Blessing coverage above on the shared
    /// `KILL_TRIGGERED_TEMP_HP_SOURCES` cohort — verifies the temp HP
    /// grant lands on kill via a direct DealDamage burn (same
    /// side-step of the seed sweep of the attack pipeline the sibling
    /// test uses — the trigger fires on the outcome, not on a
    /// specific attack path).
    #[test]
    fn touch_of_death_grants_temp_hp_on_hostile_kill() {
        use crate::actions::class_features::TOUCH_OF_DEATH_TAG;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::actors::creatures::monks::LONG_DEATH_MONK_TEMPLATE;
        use crate::engine::side_effects::{ApplicableSideEffect, DealDamage};
        let mut e = ei_with_terrain(15, 15, &[]);
        let m = e
            .instantiate_creature(&LONG_DEATH_MONK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        assert!(e.actors[&m].has_passive_feature(TOUCH_OF_DEATH_TAG));
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(3, 2), 1, 0)
            .unwrap();
        while e.current_turn_actor_id() != Some(m) {
            e.skip_turn();
        }
        assert_eq!(e.actors[&m].temp_hp(), 0);
        let goblin_hp = e.actors[&g].hitpoints();
        DealDamage {
            actor_id: g,
            amount: goblin_hp + 100,
            damage_type: crate::engine::types::DamageType::Force,
        }
        .apply(&mut e);
        // Expected temp HP = max(1, 1 + CON mod + monk level). Compute
        // against the actual template to stay resilient to level shifts.
        let expected = {
            let a = &e.actors[&m];
            let con = a.ability_modifier(crate::engine::types::AbilityScoreType::Constitution);
            let lvl = a.level() as i32;
            (1 + con + lvl).max(1) as u32
        };
        // Use >= to accommodate any future template level bump making
        // the pool larger; the load-bearing check is "temp HP > 0".
        assert!(
            e.actors[&m].temp_hp() >= expected,
            "expected at least {} temp HP (1 + CON + level), got {}",
            expected,
            e.actors[&m].temp_hp()
        );
    }

    /// Touch of Death does NOT fire on a same-team kill — friendly
