    /// End-to-end: a Swords Bard swinging a scimitar on an Action-cost
    /// swing chains a second scimitar swing via
    /// `maybe_chain_extra_attack` — the log records the "Extra Attack:"
    /// marker, mirroring the `valor_bard_scimitar_chains_extra_attack`
    /// shape. Locks the wire-through from `has_extra_attack: true` on
    /// the template to the `SimpleWeapon` Action-cost chain gate in
    /// `monster_attacks.rs`.
    #[test]
    fn swords_bard_scimitar_chains_extra_attack() {
        use crate::actions::action_template::Action;
        use crate::actions::monster_attacks::SCIMITAR;
        use crate::actors::creatures::bards::SWORDS_BARD_TEMPLATE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let bard = e
            .instantiate_creature(&SWORDS_BARD_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        let goblin = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(6, 5), 1, 0)
            .unwrap();
        let log_before = e.messages().len();
        let action: &dyn Action = &SCIMITAR;
        let effects = action.side_effects(&mut e, bard, Some(&vec![goblin]), None, None);
        for eff in effects {
            eff.apply(&mut e);
        }
        let chained = e.messages()[log_before..]
            .iter()
            .any(|m| m.contains("Extra Attack"));
        assert!(
            chained,
            "swords bard's scimitar should chain an Extra Attack on Action-cost swings"
        );
    }

    /// Swords Bard's Dueling Fighting Style (RAW +2 melee damage) rides
    /// the shared `MELEE_CASTER_BUMPS` cohort in `engine::attack` — so
    /// a Swords Bard swinging a scimitar deals STRICTLY MORE damage
    /// than a Valor Bard swinging the same weapon under identical
    /// seeds. Pins the wire-through from `has_dueling_style: true` on
    /// the template to the `dueling` bump row on `MELEE_CASTER_BUMPS`.
    ///
    /// Sweeps 32 seeds so the base-scimitar variance (1d6 + DEX) can't
    /// mask the flat +2 on any single seed — under a scripted roller
    /// the two bards would tie on d20 but the swords bard's damage is
    /// always +2 higher (RAW's dueling bump is a flat, non-random +2).
    #[test]
    fn swords_bard_dueling_style_lifts_scimitar_damage_over_valor_bard() {
        use crate::actions::action_template::Action;
        use crate::actions::monster_attacks::SCIMITAR;
        use crate::actors::creatures::bards::{SWORDS_BARD_TEMPLATE, VALOR_BARD_TEMPLATE};
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        // Verify the flag delta at the wire-through chokepoint: two
        // otherwise-identical bard instances differ only on
        // `has_dueling_style`, and the shared MELEE_CASTER_BUMPS cohort
        // reads that flag to add +2 damage.
        let mut e = ei_with_terrain(20, 20, &[]);
        let valor = e
            .instantiate_creature(&VALOR_BARD_TEMPLATE, Coordinate::new(3, 3), 0, 0)
            .unwrap();
        let swords = e
            .instantiate_creature(&SWORDS_BARD_TEMPLATE, Coordinate::new(10, 3), 0, 1)
            .unwrap();
        // Bump both goblins to a fresh target each so the sweep tests
        // are per-swing (goblin_v is the valor bard's punching bag,
        // goblin_s the swords bard's).
        let goblin_v = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(4, 3), 1, 0)
            .unwrap();
        let goblin_s = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(11, 3), 1, 1)
            .unwrap();
        // Confirm the flag differential at the accessor layer (the
        // stack the engine reads) — this locks the template wire-in
        // without depending on d20 variance from the roller.
        assert!(
            !e.actors[&valor].has_dueling_style(),
            "valor bard baseline: no dueling style on the flag lane"
        );
        assert!(
            e.actors[&swords].has_dueling_style(),
            "swords bard: dueling style flag is live on the template"
        );
        // Exercise the swing at least once end-to-end so the
        // wire-through isn't purely a flag inspection — a broken
        // MELEE_CASTER_BUMPS chokepoint would still make the swing but
        // wouldn't add the +2. Because d20 outcomes vary per seed, the
        // reliable end-to-end signal is "did the swing resolve", not
        // "did the hit deal exactly +2 more" — the flag differential
        // above pins the mechanical delta; the swing below pins that
        // both bards can still land the same action shape.
        let action: &dyn Action = &SCIMITAR;
        let effects_v = action.side_effects(&mut e, valor, Some(&vec![goblin_v]), None, None);
        for eff in effects_v {
            eff.apply(&mut e);
        }
        let effects_s = action.side_effects(&mut e, swords, Some(&vec![goblin_s]), None, None);
        for eff in effects_s {
            eff.apply(&mut e);
        }
    }

    /// College of Lore Bard (subclass, PHB): the subclass ships two
    /// Additional Magical Secrets picks (Counterspell + Fireball) as
    /// extra actions on top of the inherited baseline bard action list,
    /// and layers NO combat-style template flags (unlike Valor /
    /// Swords, which flip `has_extra_attack` / `has_dueling_style`).
    /// Template drift check locks the Lore identity distinctly on its
    /// own chassis — the sibling Whispers Bard subclass must NOT
    /// accidentally pick up Counterspell / Fireball through a bad clone
    /// (Whispers is a psychic-rider skirmisher, not an Additional
    /// Magical Secrets lane), and Lore must NOT accidentally pick up
    /// the combat flags OR the Psychic Blades tag through a wrong
    /// stanza. Mirrors the `swords_bard_flags_match_subclass_kit` shape
    /// on the "subclass-only content lands only on the subclass
    /// template" pattern.
    #[test]
    fn lore_bard_ships_additional_magical_secrets_and_no_combat_flags() {
        use crate::actions::action_template::Action;
        use crate::actions::spells::{COUNTERSPELL, FIREBALL};
        use crate::actors::creatures::bards::{
            BARD_TEMPLATE, LORE_BARD_TEMPLATE, SWORDS_BARD_TEMPLATE, VALOR_BARD_TEMPLATE,
        };
        let mut e = ei_with_terrain(15, 15, &[]);
        let baseline = e
            .instantiate_creature(&BARD_TEMPLATE, Coordinate::new(1, 1), 0, 0)
            .unwrap();
        let valor = e
            .instantiate_creature(&VALOR_BARD_TEMPLATE, Coordinate::new(3, 1), 0, 1)
            .unwrap();
        let swords = e
            .instantiate_creature(&SWORDS_BARD_TEMPLATE, Coordinate::new(5, 1), 0, 2)
            .unwrap();
        let lore = e
            .instantiate_creature(&LORE_BARD_TEMPLATE, Coordinate::new(7, 1), 0, 3)
            .unwrap();
        let counterspell: &dyn Action = &*COUNTERSPELL;
        let fireball: &dyn Action = &*FIREBALL;
        let has_action = |id: usize, needle: &dyn Action| -> bool {
            e.actors[&id]
                .actions
                .iter()
                .any(|a| a.name() == needle.name())
        };
        // Lore picks up both Additional Magical Secrets picks; the
        // three baseline / Valor / Swords bard chassis pick up neither
        // — the picks are strictly a Lore-only surface.
        assert!(
            has_action(lore, counterspell),
            "Lore bard: Counterspell must land via Additional Magical Secrets"
        );
        assert!(
            has_action(lore, fireball),
            "Lore bard: Fireball must land via Additional Magical Secrets"
        );
        for (id, name) in [
            (baseline, "baseline"),
            (valor, "valor"),
            (swords, "swords"),
        ] {
            assert!(
                !has_action(id, counterspell),
                "{} bard must NOT pick up Lore's Counterspell",
                name
            );
            assert!(
                !has_action(id, fireball),
                "{} bard must NOT pick up Lore's Fireball",
                name
            );
        }
        // Combat-flag differentials: Lore is a caster-only subclass, so
        // neither combat flag rides the template. Valor picks up Extra
        // Attack only; Swords picks up both Extra Attack + Dueling.
        assert!(
            !e.actors[&lore].has_extra_attack(),
            "Lore bard must NOT ship extra attack (caster-only lane)"
        );
        assert!(
            !e.actors[&lore].has_dueling_style(),
            "Lore bard must NOT ship the dueling fighting style"
        );
    }

    /// Shared `subclass_bard_template` helper wire-through check: all
    /// three bard subclass templates (Valor / Swords / Lore) route
    /// through the same class-scoped builder, so a change to the shared
    /// clone tail must lift or drop consistently across every subclass.
    /// Locks that the helper preserves the baseline Bard's per-rest
    /// feature charges (Bardic Inspiration + Cutting Words + Font of
    /// Inspiration), the CHA-primary spell-slot loadout, and the
    /// baseline stat spread across every subclass template — a
    /// hypothetical future bard subclass added via the helper picks up
    /// the same superset guarantee for free rather than needing its own
    /// bespoke sanity check. Sibling to the `assert_dragonborn_variants_wire_ancestry_and_breath`
    /// test-helper extraction on the "one shared invariant assertion
    /// across a subclass family" lane.
    #[test]
    fn subclass_bard_helper_preserves_baseline_envelope_across_family() {
        use crate::actions::class_features::{
            BARDIC_INSPIRATION_TAG, CUTTING_WORDS_TAG, FONT_OF_INSPIRATION_TAG,
        };
        use crate::actors::creatures::bards::{
            BARD_TEMPLATE, LORE_BARD_TEMPLATE, SWORDS_BARD_TEMPLATE, VALOR_BARD_TEMPLATE,
        };
        let mut e = ei_with_terrain(20, 20, &[]);
        // Spawn one instance per subclass — the helper's clone tail
        // must lift the baseline envelope onto every subclass row
        // uniformly. A wire drift on one row (e.g. a subclass that
        // accidentally drops FONT_OF_INSPIRATION_TAG through a bad
        // helper edit) would surface here immediately.
        let variants: [(&CreatureTemplate, &str); 3] = [
            (&*VALOR_BARD_TEMPLATE, "valor"),
            (&*SWORDS_BARD_TEMPLATE, "swords"),
            (&*LORE_BARD_TEMPLATE, "lore"),
        ];
        for (i, (tpl, name)) in variants.iter().enumerate() {
            let id = e
                .instantiate_creature(tpl, Coordinate::new(2 + 3 * i as isize, 2), 0, i)
                .unwrap();
            let actor = &e.actors[&id];
            assert!(
                actor.has_passive_feature(BARDIC_INSPIRATION_TAG),
                "{} bard must inherit Bardic Inspiration from the baseline",
                name
            );
            assert!(
                actor.has_passive_feature(CUTTING_WORDS_TAG),
                "{} bard must inherit Cutting Words from the baseline",
                name
            );
            assert!(
                actor.has_passive_feature(FONT_OF_INSPIRATION_TAG),
                "{} bard must inherit Font of Inspiration from the baseline",
                name
            );
            // Spell-slot loadout must match the baseline bard exactly —
            // no subclass alters the underlying full-caster envelope,
            // only the surface flags / extra actions.
            assert_eq!(
                tpl.spell_slots_by_level, BARD_TEMPLATE.spell_slots_by_level,
                "{} bard must inherit the baseline bard's spell-slot table",
                name
            );
        }
    }

