    /// FAILED_SAVE_ADD_DIE_SOURCES cohort cleanup: with the cohort row
    /// simplified from a `consume: fn(&mut ActorInstance) -> bool`
    /// closure to a bare `tag: &'static str`, the tag-based
    /// `spend_feature` semantics still fire cleanly end-to-end. A
    /// Divine Soul Sorcerer holding an unspent Favored by the Gods
    /// charge on a failed save picks up +2d4 (avg +5) from the cohort
    /// and the charge lands spent — locks the wire-through of the
    /// tag-based row shape into `roll_save_with_extra_mode`.
    #[test]
    fn add_die_cohort_spends_tag_directly() {
        use crate::actions::class_features::FAVORED_BY_THE_GODS_TAG;
        use crate::actors::creatures::sorcerers::DIVINE_SOUL_SORCERER_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&DIVINE_SOUL_SORCERER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        // The cohort promotes the row to a `tag` field; the loop body
        // calls `spend_feature(source.tag)` directly. Verifying the
        // template still ships the tag (pre-condition for the cohort
        // to fire the tag-based branch).
        assert!(e.actors[&sorcerer].feature_available(FAVORED_BY_THE_GODS_TAG));
        // A high-DC WIS save on a low-WIS caster forces a fail with
        // high probability; the cohort's boost consumes the charge.
        // The concrete pass/fail outcome depends on the die roll, but
        // the FBTG charge should be consumed after any failing initial
        // roll — verify by rolling many saves at a DC so high the
        // initial roll always fails.
        let dc = 40;
        let _ = e.roll_save_with_extra_mode(
            sorcerer,
            crate::engine::types::AbilityScoreType::Wisdom,
            dc,
            RollMode::Normal,
        );
        assert!(
            !e.actors[&sorcerer].feature_available(FAVORED_BY_THE_GODS_TAG),
            "cohort's tag-based spend should consume the Favored by the Gods charge on a failed save"
        );
    }

    /// 5e Warlock Archfey Patron **Beguiling Defenses** (lv10): passive
    /// self-immunity to `Charmed` installs. Baseline warlock eats the
    /// install; Archfey warlock bounces it. `Frightened` (out of scope
    /// for the Archfey patron's Beguiling Defenses — Psychic Defenses
    /// on the Aberrant Mind sorcerer covers both, but Archfey covers
    /// only Charmed RAW) still installs normally on the Archfey chassis.
    /// Locks the FLAG_DRIVEN_IMMUNITIES cohort row wire-through from
    /// `has_passive_feature(BEGUILING_DEFENSES_TAG)` to the shared
    /// `dynamic_immunity_to` install-bounce site.
    #[test]
    fn beguiling_defenses_bounces_charmed_install_only() {
        use crate::actors::creatures::warlocks::{ARCHFEY_WARLOCK_TEMPLATE, WARLOCK_TEMPLATE};
        use crate::conditions::ConditionTimer;
        use crate::engine::side_effects::{ApplicableSideEffect, ApplyCondition};

        let mut e = ei_with_terrain(15, 15, &[]);
        let archfey = e
            .instantiate_creature(&ARCHFEY_WARLOCK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let baseline = e
            .instantiate_creature(&WARLOCK_TEMPLATE, Coordinate::new(12, 12), 1, 0)
            .unwrap();
        // Archfey warlock: Charmed install bounces.
        ApplyCondition {
            actor_id: archfey,
            condition: Condition::Charmed,
            timer: ConditionTimer::Rounds(3),
        }
        .apply(&mut e);
        assert!(
            !e.actors[&archfey].has_condition(Condition::Charmed),
            "archfey warlock bounces Charmed install via Beguiling Defenses"
        );
        // Frightened still installs on the Archfey chassis — RAW-scoped
        // to Charmed only, unlike the Aberrant Mind sorcerer's Psychic
        // Defenses (both Charmed AND Frightened).
        ApplyCondition {
            actor_id: archfey,
            condition: Condition::Frightened,
            timer: ConditionTimer::Rounds(3),
        }
        .apply(&mut e);
        assert!(
            e.actors[&archfey].has_condition(Condition::Frightened),
            "archfey warlock still catches Frightened install — Beguiling Defenses is Charmed-only"
        );
        // Baseline warlock eats both — no Beguiling Defenses tag.
        ApplyCondition {
            actor_id: baseline,
            condition: Condition::Charmed,
            timer: ConditionTimer::Rounds(3),
        }
        .apply(&mut e);
        assert!(
            e.actors[&baseline].has_condition(Condition::Charmed),
            "baseline warlock catches Charmed install"
        );
    }

    /// Template drift check: only the Archfey Warlock ships the
    /// `BEGUILING_DEFENSES_TAG` passive feature. The baseline / Fiend /
    /// Undying / Great Old One warlock chassis do NOT carry the tag —
    /// keeps the subclass tell scoped to the Archfey chassis so a future
    /// regression (e.g., accidental tag insertion on `WARLOCK_TEMPLATE`
    /// bleeding into every subclass build via the `..base.clone()`
    /// tail) is caught here.
    #[test]
    fn beguiling_defenses_lands_only_on_archfey_warlock() {
        use crate::actions::class_features::BEGUILING_DEFENSES_TAG;
        use crate::actors::creatures::warlocks::{
            ARCHFEY_WARLOCK_TEMPLATE, FIEND_WARLOCK_TEMPLATE, GREAT_OLD_ONE_WARLOCK_TEMPLATE,
            UNDYING_WARLOCK_TEMPLATE, WARLOCK_TEMPLATE,
        };
        let mut e = ei_with_terrain(15, 15, &[]);
        let baseline = e
            .instantiate_creature(&WARLOCK_TEMPLATE, Coordinate::new(1, 1), 0, 0)
            .unwrap();
        let fiend = e
            .instantiate_creature(&FIEND_WARLOCK_TEMPLATE, Coordinate::new(3, 1), 0, 0)
            .unwrap();
        let undying = e
            .instantiate_creature(&UNDYING_WARLOCK_TEMPLATE, Coordinate::new(5, 1), 0, 0)
            .unwrap();
        let great_old_one = e
            .instantiate_creature(&GREAT_OLD_ONE_WARLOCK_TEMPLATE, Coordinate::new(7, 1), 0, 0)
            .unwrap();
        let archfey = e
            .instantiate_creature(&ARCHFEY_WARLOCK_TEMPLATE, Coordinate::new(9, 1), 0, 0)
            .unwrap();
        // Only the Archfey warlock ships the tag.
        assert!(e.actors[&archfey].has_passive_feature(BEGUILING_DEFENSES_TAG));
        assert!(!e.actors[&baseline].has_passive_feature(BEGUILING_DEFENSES_TAG));
        assert!(!e.actors[&fiend].has_passive_feature(BEGUILING_DEFENSES_TAG));
        assert!(!e.actors[&undying].has_passive_feature(BEGUILING_DEFENSES_TAG));
        assert!(!e.actors[&great_old_one].has_passive_feature(BEGUILING_DEFENSES_TAG));
    }

    /// Sanity: the Archfey Warlock inherits the baseline Warlock envelope
    /// through the `..WARLOCK_TEMPLATE.clone()` tail — Eldritch Blast's
    /// signature invocations (Agonizing / Repelling / Eldritch Mind) all
    /// carry through, alongside the subclass-only Beguiling Defenses
    /// tag. Guards against a regression where a subclass template's
    /// explicit `features` builder drops the baseline invocation set on
    /// its way to inserting the new tag.
    #[test]
    fn archfey_warlock_inherits_baseline_warlock_features() {
        use crate::actions::class_features::{
            AGONIZING_BLAST_TAG, BEGUILING_DEFENSES_TAG, ELDRITCH_MIND_TAG, REPELLING_BLAST_TAG,
        };
        use crate::actors::creatures::warlocks::ARCHFEY_WARLOCK_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let archfey = e
            .instantiate_creature(&ARCHFEY_WARLOCK_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        // Baseline invocations still carry through the clone.
        assert!(e.actors[&archfey].has_passive_feature(AGONIZING_BLAST_TAG));
        assert!(e.actors[&archfey].has_passive_feature(REPELLING_BLAST_TAG));
        assert!(e.actors[&archfey].has_passive_feature(ELDRITCH_MIND_TAG));
        // Subclass tag lands on top.
        assert!(e.actors[&archfey].has_passive_feature(BEGUILING_DEFENSES_TAG));
    }

    /// FLAG_DRIVEN_IMMUNITIES cohort wire-through: a Drow (Fey Ancestry
    /// racial, no Beguiling Defenses tag) still bounces Charmed installs
    /// through the sibling Fey Ancestry row on the same cohort. This is
    /// the "the two rows are OR'd — either flag alone suffices" sanity
    /// check documented in the Beguiling Defenses row's rationale
    /// comment; regressions on the OR-of-cohort-hits semantics (say, a
    /// refactor that changes the cohort walk to AND the rows) would
    /// land here.
    #[test]
    fn fey_ancestry_still_bounces_charmed_without_beguiling_defenses() {
        use crate::actions::class_features::BEGUILING_DEFENSES_TAG;
        use crate::actors::creatures::drow::DROW_TEMPLATE;
        use crate::conditions::ConditionTimer;
        use crate::engine::side_effects::{ApplicableSideEffect, ApplyCondition};

        let mut e = ei_with_terrain(15, 15, &[]);
        let drow = e
            .instantiate_creature(&DROW_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        // Precondition: the drow chassis does NOT ship Beguiling
        // Defenses (it's a Warlock subclass tag, not a racial trait) —
        // so any Charmed bounce here rides on the Fey Ancestry row
        // alone, exercising the "sibling row is an independent hit"
        // arm of the OR-of-cohort-hits semantics.
        assert!(!e.actors[&drow].has_passive_feature(BEGUILING_DEFENSES_TAG));
        ApplyCondition {
            actor_id: drow,
            condition: Condition::Charmed,
            timer: ConditionTimer::Rounds(3),
        }
        .apply(&mut e);
        assert!(
            !e.actors[&drow].has_condition(Condition::Charmed),
            "Fey Ancestry alone bounces Charmed install — sibling row on the FLAG_DRIVEN_IMMUNITIES cohort still fires without Beguiling Defenses"
        );
    }

    /// 5e Warlock Celestial Patron **Radiant Soul** (lv6): passive radiant
    /// damage resistance. Baseline Warlock eats full radiant; Celestial
    /// Warlock halves the incoming hit. Other damage types (Fire / Cold /
    /// Poison / Necrotic) land at full magnitude — the RAW subclass grant
    /// is scoped to Radiant alone even though the sibling +CHA-mod
    /// damage-boost clause covers both fire and radiant (that clause is
    /// left as future work; only the passive resistance rides on the
    /// CR-4 chassis). Locks the `PASSIVE_TYPED_RESISTANCES` cohort row
    /// wire-through from `has_passive_feature(RADIANT_SOUL_TAG)` to the
    /// shared `effective_damage` halving site.
    #[test]
    fn radiant_soul_halves_radiant_damage_on_celestial_warlock() {
        use crate::actors::creatures::warlocks::{CELESTIAL_WARLOCK_TEMPLATE, WARLOCK_TEMPLATE};
        use crate::engine::types::DamageType;

        let mut e = ei_with_terrain(15, 15, &[]);
        let celestial = e
            .instantiate_creature(&CELESTIAL_WARLOCK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let baseline = e
            .instantiate_creature(&WARLOCK_TEMPLATE, Coordinate::new(4, 2), 0, 0)
            .unwrap();
        assert!(e.actors[&celestial].has_passive_feature(
            crate::actions::class_features::RADIANT_SOUL_TAG,
        ));
        assert!(!e.actors[&baseline].has_passive_feature(
            crate::actions::class_features::RADIANT_SOUL_TAG,
        ));
        // 20 radiant → 10 (halved by Radiant Soul) on the Celestial
        // Warlock.
        assert_eq!(
            e.actors[&celestial].effective_damage(20, DamageType::Radiant),
            10,
            "celestial warlock halves radiant damage"
        );
        // Baseline warlock eats the full 20 radiant.
        assert_eq!(
            e.actors[&baseline].effective_damage(20, DamageType::Radiant),
            20,
            "baseline warlock takes full radiant damage"
        );
        // Other damage types still take full damage on the Celestial
        // Warlock — the RAW subclass grant is scoped to Radiant. Fire
        // (the sibling half of the +CHA-mod damage-boost clause) still
        // lands full; Cold / Poison / Necrotic all pass through
        // unchanged.
        assert_eq!(
            e.actors[&celestial].effective_damage(20, DamageType::Fire),
            20,
        );
        assert_eq!(
            e.actors[&celestial].effective_damage(20, DamageType::Cold),
            20,
        );
        assert_eq!(
            e.actors[&celestial].effective_damage(20, DamageType::Poison),
            20,
        );
        assert_eq!(
            e.actors[&celestial].effective_damage(20, DamageType::Necrotic),
            20,
        );
    }

    /// Radiant Soul plugs into `has_own_typed_reduction(Radiant)` — the
    /// "does this actor already scale this type?" gate used by Aura of
    /// Warding to enforce the "one halving per damage instance" rule.
    /// Locks the shared read chokepoint so a hypothetical Celestial
    /// Warlock / Ancients Paladin party sees the aura no-op cleanly on
    /// radiant hits (the /2 already fires via Radiant Soul; the aura
    /// would otherwise stack a second /2 for /4 unless
    /// `has_own_typed_reduction` picked it up here). Sibling to the
    /// Draconic Resilience registration test on the same helper.
    #[test]
    fn radiant_soul_registers_own_typed_reduction_for_radiant() {
        use crate::actors::creatures::warlocks::{CELESTIAL_WARLOCK_TEMPLATE, WARLOCK_TEMPLATE};
        use crate::engine::types::DamageType;

        let mut e = ei_with_terrain(15, 15, &[]);
        let celestial = e
            .instantiate_creature(&CELESTIAL_WARLOCK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let baseline = e
            .instantiate_creature(&WARLOCK_TEMPLATE, Coordinate::new(4, 2), 0, 0)
            .unwrap();
        // Celestial warlock's Radiant Soul flag registers as an own
        // typed reduction on the Radiant lane so aura-style stacking
        // no-ops.
        assert!(
            e.actors[&celestial].has_own_typed_reduction(DamageType::Radiant),
            "Radiant Soul registers as own typed reduction on Radiant"
        );
        // Baseline warlock without the tag has no own reduction on
        // Radiant — aura stacking would apply cleanly.
        assert!(
            !e.actors[&baseline].has_own_typed_reduction(DamageType::Radiant),
            "baseline warlock has no own radiant reduction"
        );
    }

    /// Template drift check: only the Celestial Warlock ships the
    /// `RADIANT_SOUL_TAG` passive feature. The baseline / Fiend / Undying
    /// / Great Old One / Archfey warlock chassis do NOT carry the tag —
    /// keeps the subclass tell scoped to the Celestial chassis so a
    /// future regression (e.g., accidental tag insertion on
    /// `WARLOCK_TEMPLATE` bleeding into every subclass build via the
    /// `..base.clone()` tail) is caught here.
    #[test]
    fn radiant_soul_lands_only_on_celestial_warlock() {
        use crate::actions::class_features::RADIANT_SOUL_TAG;
        use crate::actors::creatures::warlocks::{
            ARCHFEY_WARLOCK_TEMPLATE, CELESTIAL_WARLOCK_TEMPLATE, FIEND_WARLOCK_TEMPLATE,
            GREAT_OLD_ONE_WARLOCK_TEMPLATE, UNDYING_WARLOCK_TEMPLATE, WARLOCK_TEMPLATE,
        };
        let mut e = ei_with_terrain(15, 15, &[]);
        let baseline = e
            .instantiate_creature(&WARLOCK_TEMPLATE, Coordinate::new(1, 1), 0, 0)
            .unwrap();
        let fiend = e
            .instantiate_creature(&FIEND_WARLOCK_TEMPLATE, Coordinate::new(3, 1), 0, 0)
            .unwrap();
        let undying = e
            .instantiate_creature(&UNDYING_WARLOCK_TEMPLATE, Coordinate::new(5, 1), 0, 0)
            .unwrap();
        let great_old_one = e
            .instantiate_creature(&GREAT_OLD_ONE_WARLOCK_TEMPLATE, Coordinate::new(7, 1), 0, 0)
            .unwrap();
        let archfey = e
            .instantiate_creature(&ARCHFEY_WARLOCK_TEMPLATE, Coordinate::new(9, 1), 0, 0)
            .unwrap();
        let celestial = e
            .instantiate_creature(&CELESTIAL_WARLOCK_TEMPLATE, Coordinate::new(11, 1), 0, 0)
            .unwrap();
        // Only the Celestial warlock ships the tag.
        assert!(e.actors[&celestial].has_passive_feature(RADIANT_SOUL_TAG));
        assert!(!e.actors[&baseline].has_passive_feature(RADIANT_SOUL_TAG));
        assert!(!e.actors[&fiend].has_passive_feature(RADIANT_SOUL_TAG));
        assert!(!e.actors[&undying].has_passive_feature(RADIANT_SOUL_TAG));
        assert!(!e.actors[&great_old_one].has_passive_feature(RADIANT_SOUL_TAG));
        assert!(!e.actors[&archfey].has_passive_feature(RADIANT_SOUL_TAG));
    }

