        // (lv5), Brutal Critical(1d) (lv9 melee crit rider).
        assert!(e.actors[&sea].has_danger_sense());
        assert!(e.actors[&sea].has_feral_instinct());
        assert!(e.actors[&sea].has_persistent_rage());
