    /// 5e Gloom Stalker Ranger Iron Mind (subclass level 7, XGtE) —
    /// adds WIS to the ranger's baseline STR / DEX save-proficiency
    /// set. Pins the placement so a future refactor that drops WIS
    /// from the Gloom Stalker's `proficient_saves` (or promotes it
    /// onto baseline ranger) trips this assertion before the
    /// save-proficiency chokepoint reads it back on the wrong chassis.
    #[test]
    fn gloom_stalker_iron_mind_grants_wis_save_proficiency() {
        use crate::actors::creatures::rangers::{
            GLOOM_STALKER_RANGER_TEMPLATE, RANGER_TEMPLATE,
        };
        use crate::engine::types::AbilityScoreType;
        let mut e = ei_with_terrain(15, 15, &[]);
        let baseline = e
            .instantiate_creature(&RANGER_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let gloom = e
            .instantiate_creature(&GLOOM_STALKER_RANGER_TEMPLATE, Coordinate::new(5, 2), 0, 1)
            .unwrap();
        // Baseline ranger has STR / DEX save proficiency but NOT WIS.
        assert!(e.actors[&baseline].is_save_proficient(AbilityScoreType::Strength));
        assert!(e.actors[&baseline].is_save_proficient(AbilityScoreType::Dexterity));
        assert!(!e.actors[&baseline].is_save_proficient(AbilityScoreType::Wisdom));
        // Gloom Stalker keeps STR / DEX and adds WIS.
        assert!(e.actors[&gloom].is_save_proficient(AbilityScoreType::Strength));
        assert!(e.actors[&gloom].is_save_proficient(AbilityScoreType::Dexterity));
        assert!(e.actors[&gloom].is_save_proficient(AbilityScoreType::Wisdom));
    }

    /// Arcane Ward is dormant until the abjurer's first abjuration cast:
    /// the pool exists on the template but absorbs nothing, and the UI
    /// gauge stays hidden (`arcane_ward_formed` false). Pins the RAW
    /// "you weave the ward when you cast an abjuration spell" gate — a
    /// template flag alone must not hand out free absorption.
    #[test]
    fn arcane_ward_is_dormant_until_first_abjuration_cast() {
        use crate::engine::side_effects::DealDamage;
        use crate::actors::creatures::wizards::{ABJURATION_WIZARD_TEMPLATE, WIZARD_TEMPLATE};
        let mut e = ei_with_terrain(15, 15, &[]);
        let abjurer = e
            .instantiate_creature(&ABJURATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let baseline = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(4, 2), 0, 1)
            .unwrap();
        // The abjurer holds the feature; the baseline wizard does not.
        assert!(e.actors[&abjurer].has_arcane_ward());
        assert!(!e.actors[&baseline].has_arcane_ward());
        // Dormant: no pool, no gauge, but a known maximum waiting.
        assert_eq!(e.actors[&abjurer].arcane_ward(), 0);
        assert!(!e.actors[&abjurer].arcane_ward_formed());
        // 6 (RAW twice-wizard-level term) + 3 (INT 16) = 9.
        assert_eq!(e.actors[&abjurer].arcane_ward_max(), 9);
        assert_eq!(e.actors[&baseline].arcane_ward_max(), 0);
        // A dormant ward absorbs nothing — damage lands on HP in full.
        let before = e.actors[&abjurer].hitpoints();
        DealDamage {
            actor_id: abjurer,
            amount: 3,
            damage_type: DamageType::Force,
        }
        .apply(&mut e);
        assert_eq!(e.actors[&abjurer].hitpoints() + 3, before);
    }

    /// End-to-end through `Action::execute`: casting Mage Armor (an
    /// abjuration spell of 1st level) weaves the ward at full strength,
    /// and the ward then eats damage ahead of HP. Confirms the
    /// post-cast trigger registry is actually wired to `school()` —
    /// not just that `weave_or_recharge_arcane_ward` works in isolation.
    #[test]
    fn abjuration_cast_weaves_ward_that_absorbs_damage() {
        use crate::engine::side_effects::DealDamage;
        use crate::actions::spells::MAGE_ARMOR;
        use crate::actors::creatures::wizards::ABJURATION_WIZARD_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let abjurer = e
            .instantiate_creature(&ABJURATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        {
            let actor = e.actors.get_mut(&abjurer).unwrap();
            actor.give_resource(crate::engine::side_effects::Resource::Action);
            actor.spell_slot_manager.restore_spell_slots();
        }
        // Mage Armor is a NoArgs self-buff — no target list.
        for ef in MAGE_ARMOR.execute(&mut e, abjurer, None, None, None) {
            ef.apply(&mut e);
        }
        assert!(e.actors[&abjurer].arcane_ward_formed());
        assert_eq!(e.actors[&abjurer].arcane_ward(), 9);
        // The ward soaks the first 9 points; the 10th lands on HP.
        let hp_before = e.actors[&abjurer].hitpoints();
        DealDamage {
            actor_id: abjurer,
            amount: 4,
            damage_type: DamageType::Force,
        }
        .apply(&mut e);
        assert_eq!(e.actors[&abjurer].arcane_ward(), 5);
        assert_eq!(e.actors[&abjurer].hitpoints(), hp_before);
        DealDamage {
            actor_id: abjurer,
            amount: 7,
            damage_type: DamageType::Force,
        }
        .apply(&mut e);
        // Ward drains to 0 and the 2-point remainder spills onto HP.
        assert_eq!(e.actors[&abjurer].arcane_ward(), 0);
        assert_eq!(e.actors[&abjurer].hitpoints() + 2, hp_before);
        // Drained is not gone: RAW keeps the ward's magic alive.
        assert!(e.actors[&abjurer].arcane_ward_formed());
    }

    /// The ward drains ahead of temp HP. Both pools are "absorb before
    /// HP" layers, and RAW orders the ward first ("the ward takes the
    /// damage instead of you" resolves before the damage is damage *to
    /// you*, which is what temp HP soaks). Pins the ordering so a future
    /// refactor of `take_typed_damage` can't silently swap them — the
    /// swap is invisible on total damage taken but changes which pool
    /// survives to soak the next hit.
    #[test]
    fn arcane_ward_drains_before_temp_hp() {
        use crate::engine::side_effects::DealDamage;
        use crate::actors::creatures::wizards::ABJURATION_WIZARD_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let abjurer = e
            .instantiate_creature(&ABJURATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        {
            let actor = e.actors.get_mut(&abjurer).unwrap();
            actor.weave_or_recharge_arcane_ward(1);
            actor.gain_temp_hp(5);
        }
        let hp_before = e.actors[&abjurer].hitpoints();
        DealDamage {
            actor_id: abjurer,
            amount: 4,
            damage_type: DamageType::Force,
        }
        .apply(&mut e);
        // Ward ate all 4; temp HP is untouched.
        assert_eq!(e.actors[&abjurer].arcane_ward(), 5);
        assert_eq!(e.actors[&abjurer].temp_hp(), 5);
        assert_eq!(e.actors[&abjurer].hitpoints(), hp_before);
    }

    /// Recharge arithmetic: the first abjuration cast fills the ward
    /// regardless of slot level, later casts add twice the slot level,
    /// the pool caps at the maximum, and cantrips (`spell_level == 0`)
    /// contribute nothing. Also pins the "already full" no-op so the
    /// post-cast hook stays quiet instead of logging a 0-point top-up.
    #[test]
    fn arcane_ward_recharges_by_twice_the_slot_level() {
        use crate::actors::creatures::wizards::ABJURATION_WIZARD_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let abjurer = e
            .instantiate_creature(&ABJURATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let actor = e.actors.get_mut(&abjurer).unwrap();
        // Cantrips never weave the ward.
        assert_eq!(actor.weave_or_recharge_arcane_ward(0), None);
        assert!(!actor.arcane_ward_formed());
        // First cast weaves at full strength even off a level-1 slot.
        assert_eq!(actor.weave_or_recharge_arcane_ward(1), Some((9, 9)));
        // A full ward is a no-op — nothing to log.
        assert_eq!(actor.weave_or_recharge_arcane_ward(3), None);
        // Drain it, then top up by 2 x slot level, capped at the max.
        actor.take_typed_damage(9, DamageType::Force);
        assert_eq!(actor.arcane_ward(), 0);
        assert_eq!(actor.weave_or_recharge_arcane_ward(2), Some((4, 4)));
        assert_eq!(actor.weave_or_recharge_arcane_ward(4), Some((5, 9)));
    }

    /// A long rest un-weaves the ward entirely (RAW: "once you create
    /// the ward, you can't create it again until you finish a long
    /// rest"), so the next encounter's first abjuration cast rebuilds it
    /// at full strength rather than trickling 2 points onto a stale
    /// pool. The multi-encounter dungeon loop rests between fights, so
    /// this is the live path, not a corner case.
    #[test]
    fn long_rest_unweaves_arcane_ward() {
        use crate::actors::creatures::wizards::ABJURATION_WIZARD_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let abjurer = e
            .instantiate_creature(&ABJURATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let actor = e.actors.get_mut(&abjurer).unwrap();
        actor.weave_or_recharge_arcane_ward(1);
        actor.take_typed_damage(6, DamageType::Force);
        assert_eq!(actor.arcane_ward(), 3);
        actor.long_rest();
        assert!(!actor.arcane_ward_formed());
        assert_eq!(actor.arcane_ward(), 0);
        // Re-weaving after the rest lands the full pool again.
        assert_eq!(actor.weave_or_recharge_arcane_ward(1), Some((9, 9)));
    }

    /// Non-abjuration casts leave the ward alone. Fire Bolt (evocation
    /// cantrip) and Fireball (evocation, level 3) both route through the
    /// same post-cast trigger registry, so this pins the school gate
    /// rather than an accidental "any spell recharges" reading.
    #[test]
    fn non_abjuration_casts_do_not_feed_the_ward() {
        use crate::actions::spells::{FIREBALL, MAGE_ARMOR};
        use crate::actors::creatures::wizards::ABJURATION_WIZARD_TEMPLATE;
        use crate::actors::creatures::zombies::ZOMBIE_TEMPLATE;
        let mut e = ei_with_terrain(20, 20, &[]);
        let abjurer = e
            .instantiate_creature(&ABJURATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        e.instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(9, 9), 1, 0)
            .unwrap();
        {
            let actor = e.actors.get_mut(&abjurer).unwrap();
            actor.spell_slot_manager.restore_spell_slots();
        }
        // Weave the ward, then spend it down to 1.
        e.actors
            .get_mut(&abjurer)
            .unwrap()
            .give_resource(crate::engine::side_effects::Resource::Action);
        for ef in MAGE_ARMOR.execute(&mut e, abjurer, None, None, None) {
            ef.apply(&mut e);
        }
        e.actors
            .get_mut(&abjurer)
            .unwrap()
            .take_typed_damage(8, DamageType::Force);
        assert_eq!(e.actors[&abjurer].arcane_ward(), 1);
        // A level-3 evocation cast must not top it up.
        e.actors
            .get_mut(&abjurer)
            .unwrap()
            .give_resource(crate::engine::side_effects::Resource::Action);
        let point = vec![Coordinate::new(9, 9)];
        for ef in FIREBALL.execute(&mut e, abjurer, None, Some(&point), None) {
            ef.apply(&mut e);
        }
        assert_eq!(
            e.actors[&abjurer].arcane_ward(),
            1,
            "an evocation cast fed the abjuration ward — school gate broken"
        );
    }

    /// Every spell the engine tags as Abjuration must actually be one,
    /// and the tag must survive on the `&dyn Action` the engine holds
    /// (not just on the concrete type). Drift-prevention for the
    /// `school()` lane: a future spell added to the abjurer's loadout
    /// without a `school()` override silently stops feeding the ward,
    /// and this list is where that gets noticed.
    #[test]
    fn abjuration_spells_report_their_school() {
        use crate::actions::action_template::Action;
        use crate::actions::spells::{
            AID, BANISHMENT, COUNTERSPELL, DEATH_WARD, DISPEL_MAGIC, MAGE_ARMOR, SANCTUARY,
            SHIELD, STONESKIN,
        };
        let tagged: Vec<&dyn Action> = vec![
            &*SHIELD,
            &*MAGE_ARMOR,
            &*SANCTUARY,
            &*AID,
            &*DEATH_WARD,
            &*STONESKIN,
            &*BANISHMENT,
            &*COUNTERSPELL,
            &*DISPEL_MAGIC,
        ];
        for action in tagged {
            assert_eq!(
                action.school(),
                Some(SpellSchool::Abjuration),
                "{} lost its abjuration school tag",
                action.name()
            );
        }
    }

    /// Non-spell actions report no school, so every school-keyed feature
    /// fails closed on them. Pins the `None` default on the `Action`
    /// trait against a future refactor that gives it a real value.
    #[test]
    fn non_spell_actions_have_no_school() {
        use crate::actions::action_template::Action;
        use crate::actions::monster_attacks::LONGSWORD;
        assert_eq!(LONGSWORD.school(), None);
    }

    /// The cast stack is empty outside any cast, carries the resolving
    /// spell's school and slot level inside one, and unwinds cleanly on
    /// the way out. Pins the push/pop symmetry in `Action::execute` — a
    /// leaked frame would make every later weapon swing look like a
    /// spell to the school-keyed features that read it.
    #[test]
    fn cast_context_opens_and_closes_around_execute() {
        use crate::actions::spells::MAGE_ARMOR;
        use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let wizard = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        assert_eq!(e.current_cast(), None);
        {
            let actor = e.actors.get_mut(&wizard).unwrap();
            actor.give_resource(crate::engine::side_effects::Resource::Action);
            actor.spell_slot_manager.restore_spell_slots();
        }
        for ef in MAGE_ARMOR.execute(&mut e, wizard, None, None, None) {
            ef.apply(&mut e);
        }
        assert_eq!(
            e.current_cast(),
            None,
            "cast frame leaked past the end of execute"
        );
        // The gate helpers agree with an empty stack.
        assert!(!e.casting_leveled_spell_of(SpellSchool::Abjuration));
        // And read the frame correctly when one is open.
        e.enter_cast(Some(SpellSchool::Evocation), 3);
        assert!(e.casting_leveled_spell_of(SpellSchool::Evocation));
        assert!(!e.casting_leveled_spell_of(SpellSchool::Abjuration));
        // Nesting: the innermost frame wins, and unwinding restores the
        // outer one rather than clearing the stack.
        e.enter_cast(Some(SpellSchool::Abjuration), 0);
        assert!(!e.casting_leveled_spell_of(SpellSchool::Evocation));
        assert!(
            e.current_cast()
                .unwrap()
                .is_cantrip_of(SpellSchool::Abjuration)
        );
        e.exit_cast();
        assert!(e.casting_leveled_spell_of(SpellSchool::Evocation));
        e.exit_cast();
        assert_eq!(e.current_cast(), None);
        // Over-popping is tolerated (a panic mid-cast must not corrupt
        // the stack for whatever runs next).
        e.exit_cast();
        assert_eq!(e.current_cast(), None);
    }

    /// Sculpt Spells carves `1 + spell level` allies out of an evocation
    /// blast: they take no damage while an unshielded ally in the same
    /// blast does. Runs the same Fireball twice — once from a baseline
    /// wizard, once from an evoker — so the assertion isolates the
    /// feature rather than the spell.
    #[test]
    fn sculpt_spells_carves_allies_out_of_an_evocation_blast() {
        use crate::actions::spells::FIREBALL;
        use crate::actors::creatures::wizards::{EVOCATION_WIZARD_TEMPLATE, WIZARD_TEMPLATE};
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;

        // Returns the total HP the two allies lost to the caster's blast.
        let ally_damage = |template: &'static CreatureTemplate| -> u32 {
            let mut e = ei_with_terrain(20, 20, &[]);
            let caster = e
                .instantiate_creature(template, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            let a1 = e
                .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(9, 9), 0, 1)
                .unwrap();
            let a2 = e
                .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(10, 9), 0, 2)
                .unwrap();
            {
                let actor = e.actors.get_mut(&caster).unwrap();
                actor.give_resource(crate::engine::side_effects::Resource::Action);
                actor.spell_slot_manager.restore_spell_slots();
            }
            let before: u32 = e.actors[&a1].hitpoints() + e.actors[&a2].hitpoints();
            let point = vec![Coordinate::new(9, 9)];
            for ef in FIREBALL.execute(&mut e, caster, None, Some(&point), None) {
                ef.apply(&mut e);
            }
            before - (e.actors[&a1].hitpoints() + e.actors[&a2].hitpoints())
        };

        assert!(
            ally_damage(&WIZARD_TEMPLATE) > 0,
            "baseline wizard's Fireball should hurt its own allies"
        );
        assert_eq!(
            ally_damage(&EVOCATION_WIZARD_TEMPLATE),
            0,
            "Sculpt Spells should spare both allies from a level-3 blast \
             (1 + 3 = 4 shields available)"
        );
    }

    /// Sculpt Spells is gated on the school of the spell being resolved,
    /// not on the caster: the same evoker's Hypnotic Pattern
    /// (enchantment) shields nobody. Guards against the gate degrading
    /// into "this caster protects allies from everything".
    #[test]
    fn sculpt_spells_does_not_shield_on_non_evocation_casts() {
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::actors::creatures::wizards::EVOCATION_WIZARD_TEMPLATE;
        let mut e = ei_with_terrain(20, 20, &[]);
        let evoker = e
            .instantiate_creature(&EVOCATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        e.instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(9, 9), 0, 1)
            .unwrap();
        // Evocation: the ally is carved out.
        e.enter_cast(Some(SpellSchool::Evocation), 3);
        assert_eq!(
            e.auto_pass_shielded_allies(evoker, Coordinate::new(9, 9), 3)
                .len(),
            1
        );
        e.exit_cast();
        // Enchantment: nobody is.
        e.enter_cast(Some(SpellSchool::Enchantment), 3);
        assert!(
            e.auto_pass_shielded_allies(evoker, Coordinate::new(9, 9), 3)
                .is_empty()
        );
        e.exit_cast();
        // Outside any cast: nobody is.
        assert!(
            e.auto_pass_shielded_allies(evoker, Coordinate::new(9, 9), 3)
                .is_empty()
        );
    }

    /// Empowered Evocation adds the caster's INT modifier to an
    /// evocation damage roll exactly once, and nothing to a
    /// non-evocation roll. Uses the shared roll chokepoint directly so
    /// the assertion is exact rather than statistical: a 0d6 pool rolls
    /// 0, leaving only the flat bonus.
    #[test]
    fn empowered_evocation_adds_int_mod_to_evocation_damage_only() {
        use crate::actors::creatures::wizards::{EVOCATION_WIZARD_TEMPLATE, WIZARD_TEMPLATE};
        use crate::engine::types::AbilityScoreType;
        let mut e = ei_with_terrain(15, 15, &[]);
        let evoker = e
            .instantiate_creature(&EVOCATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let baseline = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(5, 2), 0, 1)
            .unwrap();
        let int_mod = e.actors[&evoker].ability_modifier(AbilityScoreType::Intelligence) as u32;
        assert!(int_mod > 0, "the wizard chassis should have a positive INT mod");

        e.enter_cast(Some(SpellSchool::Evocation), 3);
        assert_eq!(e.roll_empowered_sum(evoker, 0, 6), int_mod);
        assert_eq!(
            e.roll_empowered_sum(baseline, 0, 6),
            0,
            "a wizard without the feature gets no bonus"
        );
        e.exit_cast();

        e.enter_cast(Some(SpellSchool::Necromancy), 3);
        assert_eq!(
            e.roll_empowered_sum(evoker, 0, 6),
            0,
            "Empowered Evocation fired on a necromancy cast"
        );
        e.exit_cast();

        // Cantrips qualify per RAW ("any wizard evocation spell").
        e.enter_cast(Some(SpellSchool::Evocation), 0);
        assert_eq!(e.roll_empowered_sum(evoker, 0, 6), int_mod);
        e.exit_cast();

        // Outside a cast the bonus is inert — a weapon swing routed
        // through this helper must not pick it up.
        assert_eq!(e.roll_empowered_sum(evoker, 0, 6), 0);
    }

    /// Every spell the engine tags as Evocation must actually report it
    /// through the `&dyn Action` the engine holds. Drift-prevention for
    /// the evocation half of the `school()` lane, mirroring
    /// `abjuration_spells_report_their_school` — a spell added to the
    /// evoker's loadout without the override silently stops feeding
    /// Sculpt Spells and Empowered Evocation.
    #[test]
    fn evocation_spells_report_their_school() {
        use crate::actions::action_template::Action;
        use crate::actions::spells::{
            BURNING_HANDS, CONE_OF_COLD, FIREBALL, FIRE_BOLT, LIGHTNING_BOLT, MAGIC_MISSILE,
            METEOR_SWARM, SHATTER, THUNDERWAVE,
        };
        let tagged: Vec<&dyn Action> = vec![
            &*FIRE_BOLT,
            &*MAGIC_MISSILE,
            &*BURNING_HANDS,
            &*THUNDERWAVE,
            &*SHATTER,
            &*FIREBALL,
            &*LIGHTNING_BOLT,
            &*CONE_OF_COLD,
            &*METEOR_SWARM,
        ];
        for action in tagged {
            assert_eq!(
                action.school(),
                Some(SpellSchool::Evocation),
                "{} lost its evocation school tag",
                action.name()
            );
        }
    }

    /// The two shielding features union rather than override: a caster
    /// holding both Careful Spell (primed) and Sculpt Spells shields the
    /// larger of the two prefixes, and the Careful Spell prime is still
    /// consumed. Pins the "an evoker/sorcerer multiclass gets both"
    /// contract on `auto_pass_shielded_allies`.
    #[test]
    fn careful_spell_and_sculpt_spells_union() {
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::actors::creatures::wizards::EVOCATION_WIZARD_TEMPLATE;
        let mut e = ei_with_terrain(20, 20, &[]);
        let evoker = e
            .instantiate_creature(&EVOCATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        for (i, x) in [9isize, 10, 11].into_iter().enumerate() {
            e.instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(x, 9), 0, i + 1)
                .unwrap();
        }
        e.actors
            .get_mut(&evoker)
            .unwrap()
            .add_condition(Condition::CarefulSpelling, ConditionTimer::Rounds(10));
        // A cantrip-level evocation cast: Sculpt Spells alone would
        // shield 1 (1 + 0). Careful Spell shields CHA-mod (min 1). The
        // union is still at least one, and the prime is spent.
        e.enter_cast(Some(SpellSchool::Evocation), 0);
        let shielded = e.auto_pass_shielded_allies(evoker, Coordinate::new(10, 9), 3);
        e.exit_cast();
        assert!(!shielded.is_empty());
        assert!(
            !e.actors[&evoker].has_condition(Condition::CarefulSpelling),
            "the Careful Spell prime should be consumed when it shields someone"
        );
    }

    /// Potent Cantrip turns a saved cantrip from a clean miss into half
    /// damage, and leaves everything else alone: a leveled spell that
    /// also zeroes on a save (the `NoneOnSave` policy is shared with
    /// Disintegrate) must not be lifted, and a caster without the
    /// feature must not be either.
    #[test]
    fn potent_cantrip_leaves_half_damage_on_a_saved_cantrip() {
        use crate::actors::creatures::wizards::{EVOCATION_WIZARD_TEMPLATE, WIZARD_TEMPLATE};
        use crate::engine::saves::SaveDamagePolicy;
        use crate::engine::types::AbilityScoreType;
        let mut e = ei_with_terrain(15, 15, &[]);
        let evoker = e
            .instantiate_creature(&EVOCATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let baseline = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(4, 2), 0, 1)
            .unwrap();
        let target = e
            .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(8, 8), 1, 0)
            .unwrap();

        // Cantrip frame: the evoker's saved cantrip still lands half.
        e.enter_cast(Some(SpellSchool::Evocation), 0);
        assert_eq!(
            e.resolve_post_save_damage(
                evoker,
                target,
                AbilityScoreType::Wisdom,
                SaveDamagePolicy::NoneOnSave,
                10,
                true
            ),
            5
        );
        // A failed save is unchanged — the feature only touches the
        // successful-save cell of the table.
        assert_eq!(
            e.resolve_post_save_damage(
                evoker,
                target,
                AbilityScoreType::Wisdom,
                SaveDamagePolicy::NoneOnSave,
                10,
                false
            ),
            10
        );
        // A wizard without the feature still gets nothing on a save.
        assert_eq!(
            e.resolve_post_save_damage(
                baseline,
                target,
                AbilityScoreType::Wisdom,
                SaveDamagePolicy::NoneOnSave,
                10,
                true
            ),
            0
        );
        e.exit_cast();

        // Leveled frame: Disintegrate-shaped `NoneOnSave` spells share
        // the policy but must not be lifted.
        e.enter_cast(Some(SpellSchool::Transmutation), 6);
        assert_eq!(
            e.resolve_post_save_damage(
                evoker,
                target,
                AbilityScoreType::Wisdom,
                SaveDamagePolicy::NoneOnSave,
                10,
                true
            ),
            0
        );
        e.exit_cast();
    }

    /// Potent Cantrip and Evasion compose in the order
    /// `resolve_post_save_damage` runs them: the cantrip is lifted into
    /// the half-on-save class first, which is exactly the class Evasion
    /// zeroes, so an evasive rogue who makes the DEX save still takes
    /// nothing. Running them the other way round would leave the rogue
    /// eating half, so this pins the ordering rather than just the
    /// result.
    #[test]
    fn potent_cantrip_and_evasion_compose() {
        use crate::actors::creatures::rogues::ROGUE_TEMPLATE;
        use crate::actors::creatures::wizards::EVOCATION_WIZARD_TEMPLATE;
        use crate::engine::saves::SaveDamagePolicy;
        use crate::engine::types::AbilityScoreType;
        let mut e = ei_with_terrain(15, 15, &[]);
        let evoker = e
            .instantiate_creature(&EVOCATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let rogue = e
            .instantiate_creature(&ROGUE_TEMPLATE, Coordinate::new(8, 8), 1, 0)
            .unwrap();
        assert!(e.actors[&rogue].has_evasion());
        e.enter_cast(Some(SpellSchool::Evocation), 0);
        // Passed DEX save: Potent Cantrip lifts to half, Evasion zeroes it.
        assert_eq!(
            e.resolve_post_save_damage(
                evoker,
                rogue,
                AbilityScoreType::Dexterity,
                SaveDamagePolicy::NoneOnSave,
                10,
                true
            ),
            0
        );
        // Failed DEX save: Evasion halves what Potent Cantrip lifted.
        assert_eq!(
            e.resolve_post_save_damage(
                evoker,
                rogue,
                AbilityScoreType::Dexterity,
                SaveDamagePolicy::NoneOnSave,
                10,
                false
            ),
            5
        );
        // A non-DEX save skips Evasion entirely on both cells.
        assert_eq!(
            e.resolve_post_save_damage(
                evoker,
                rogue,
                AbilityScoreType::Wisdom,
                SaveDamagePolicy::NoneOnSave,
                10,
                true
            ),
            5
        );
        e.exit_cast();
    }

    /// Vicious Mockery's disadvantage rider is gated on a *failed* save,
    /// not on damage landing. Under Potent Cantrip a saved target eats
    /// half the psychic damage but must not pick up `Mocked` — RAW's
    /// "takes half the damage but suffers no additional effect". Runs
    /// the cantrip across many seeds so both save outcomes occur, and
    /// asserts the invariant on every one.
    #[test]
    fn potent_vicious_mockery_never_mocks_on_a_successful_save() {
        use crate::actions::spells::VICIOUS_MOCKERY;
        use crate::actors::creatures::wizards::EVOCATION_WIZARD_TEMPLATE;
        let mut saved_seen = false;
        let mut failed_seen = false;
        for seed in 0..80u64 {
            let mut e = ei_with_terrain(15, 15, &[]);
            let evoker = e
                .instantiate_creature(&EVOCATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            let target = e
                .instantiate_creature(&ZOMBIE_TEMPLATE, Coordinate::new(5, 5), 1, 0)
                .unwrap();
            e.actors
                .get_mut(&evoker)
                .unwrap()
                .give_resource(crate::engine::side_effects::Resource::Action);
            e.roller = crate::engine::dice::FastRandRoller::with_seed(seed);
            let hp_before = e.actors[&target].hitpoints();
            let targets = vec![target];
            for ef in VICIOUS_MOCKERY.execute(&mut e, evoker, Some(&targets), None, None) {
                ef.apply(&mut e);
            }
            let mocked = e.actors[&target].has_condition(Condition::Mocked);
            let damaged = e.actors[&target].hitpoints() < hp_before;
            if mocked {
                failed_seen = true;
            } else if damaged {
                // Damage without the rider is the Potent Cantrip cell:
                // the save succeeded and half got through anyway.
                saved_seen = true;
            }
        }
        assert!(failed_seen, "no failed save across 80 seeds");
        assert!(
            saved_seen,
            "Potent Cantrip never produced a saved-but-damaged Vicious Mockery \
             across 80 seeds — is the cantrip resolver wired up?"
        );
    }

    /// Every cantrip in the engine declares a `school()`, and no
    /// non-spell action does. Together those two facts are what makes
    /// `CastContext::is_cantrip` — and therefore every cantrip-gated
    /// feature, Potent Cantrip today — able to tell a cantrip apart
    /// from a weapon swing, given that `Action::execute` opens a cast
    /// frame at level 0 for both.
    ///
    /// A new cantrip added without the override doesn't break anything
    /// loudly: it just silently stops participating in cantrip-gated
    /// features. This list is where that gets caught.
    #[test]
    fn every_cantrip_declares_its_school() {
        use crate::actions::action_template::Action;
        use crate::actions::spells::*;
        let cantrips: Vec<&dyn Action> = vec![
            &*SACRED_FLAME,
            &*SACRED_BURST,
            &*FIRE_BOLT,
            &*RAY_OF_FROST,
            &*ACID_SPLASH,
            &*CHILL_TOUCH,
            &*POISON_SPRAY,
            &*THORN_WHIP,
            &*SPARE_THE_DYING,
            &*TOLL_THE_DEAD,
            &*VICIOUS_MOCKERY,
            &*SHOCKING_GRASP,
            &*ELDRITCH_BLAST,
            &*MIND_SLIVER,
            &*TRUE_STRIKE,
            &*WORD_OF_RADIANCE,
            &*BOOMING_BLADE,
            &*MAGIC_STONE,
            &*FROSTBITE,
            &*LIGHTNING_LURE,
            &*SHILLELAGH,
            &*THUNDERCLAP,
            &*GUIDANCE,
            &*SWORD_BURST,
            &*BLADE_WARD,
            &*TELEKINETIC,
            &*GREEN_FLAME_BLADE,
            &*PRIMAL_SAVAGERY,
            &*SAPPING_STING,
            &*PRODUCE_FLAME,
            &*CREATE_BONFIRE,
            &*INFESTATION,
        ];
        for action in &cantrips {
            assert!(
                action.school().is_some(),
                "cantrip '{}' has no school() override — it will be invisible \
                 to every cantrip-gated feature",
                action.name()
            );
        }
        // The other half of the invariant: non-spell actions must stay
        // untagged, or they'd start reading as cantrips at level 0.
        use crate::actions::monster_attacks::{LONGSWORD, SCIMITAR};
        assert_eq!(LONGSWORD.school(), None);
        assert_eq!(SCIMITAR.school(), None);
    }

    /// Overchannel maximizes the damage dice of a level 1-5 spell and
    /// leaves everything outside that window rolling normally. Uses the
    /// shared damage-roll chokepoint directly so the assertion is exact:
    /// a maximized 4d6 is always 24, which a real roll reaches with
    /// probability 1/1296.
    #[test]
    fn overchannel_maximizes_damage_inside_its_level_window() {
        use crate::actors::creatures::wizards::EVOCATION_WIZARD_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let evoker = e
            .instantiate_creature(&EVOCATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let prime = |e: &mut EncounterInstance| {
            e.actors
                .get_mut(&evoker)
                .unwrap()
                .add_condition(Condition::Overchanneling, ConditionTimer::Rounds(2));
        };

        // Inside the window: maximized, and the prime is spent.
        prime(&mut e);
        e.enter_cast(Some(SpellSchool::Evocation), 3);
        let int_mod = e.actors[&evoker]
            .ability_modifier(crate::engine::types::AbilityScoreType::Intelligence)
            as u32;
        // 4d6 maxed = 24, plus Empowered Evocation's flat +INT.
        assert_eq!(e.roll_empowered_sum(evoker, 4, 6), 24 + int_mod);
        assert!(!e.actors[&evoker].has_condition(Condition::Overchanneling));
        e.exit_cast();

        // Above the window (level 6+): RAW excludes it, and the prime
        // survives for a cast that can actually use it.
        prime(&mut e);
        e.enter_cast(Some(SpellSchool::Evocation), 6);
        let rolled = e.roll_empowered_sum(evoker, 4, 6);
        assert!(rolled >= 4 + int_mod && rolled <= 24 + int_mod);
        assert!(
            e.actors[&evoker].has_condition(Condition::Overchanneling),
            "a level-6 cast should not burn the prime"
        );
        e.exit_cast();

        // Cantrips are outside the window too, on the same reasoning.
        e.enter_cast(Some(SpellSchool::Evocation), 0);
        e.roll_empowered_sum(evoker, 4, 6);
        assert!(e.actors[&evoker].has_condition(Condition::Overchanneling));
        e.exit_cast();
    }

    /// The backlash ramp: the first use since a long rest is free, the
    /// second costs 2d12 per spell level, the third 3d12, and a long
    /// rest resets the ramp. Asserts through the post-cast trigger so
    /// the two halves of the feature — maximize during the cast, charge
    /// immediately after — are exercised together.
    ///
    /// Reads the die pool off the backlash log line rather than the HP
    /// delta, because the ramp outruns the wizard chassis almost
    /// immediately: a 2d12 hit already averages more than the 2d6+2
    /// frame's hit points, so by the third use there'd be no HP left to
    /// measure a delta against. The die pool is the thing under test
    /// anyway — the HP delta is just `DealDamage` doing its usual job.
    #[test]
    fn overchannel_backlash_escalates_and_resets_on_a_long_rest() {
        use crate::actors::creatures::wizards::EVOCATION_WIZARD_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let evoker = e
            .instantiate_creature(&EVOCATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();

        // Runs one maximized level-`lvl` cast and returns the backlash
        // die pool the post-cast trigger charged, or None when the use
        // was free. Deliberately drops the trigger's side-effects
        // unapplied: the ramp is what's under test, and letting a
        // third-use backlash actually land would just kill the evoker
        // partway through the sequence.
        let overchannel_once = |e: &mut EncounterInstance, lvl: u32| -> Option<String> {
            e.actors
                .get_mut(&evoker)
                .unwrap()
                .add_condition(Condition::Overchanneling, ConditionTimer::Rounds(2));
            e.enter_cast(Some(SpellSchool::Evocation), lvl);
            e.roll_empowered_sum(evoker, 2, 6);
            e.exit_cast();
            let log_before = e.messages().len();
            let _ =
                e.dispatch_post_cast_triggers(evoker, lvl, &[], Some(SpellSchool::Evocation), None);
            e.messages()[log_before..]
                .iter()
                .find(|m| m.contains("overchannel backlash"))
                .and_then(|m| {
                    m.split_whitespace()
                        .find(|w| w.starts_with(|c: char| c.is_ascii_digit()) && w.contains("d12"))
                        .map(|w| w.split('(').next().unwrap_or(w).to_string())
                })
        };

        assert_eq!(
            overchannel_once(&mut e, 1),
            None,
            "the first use since a long rest is free"
        );
        assert_eq!(overchannel_once(&mut e, 1).as_deref(), Some("2d12"));
        assert_eq!(overchannel_once(&mut e, 1).as_deref(), Some("3d12"));
        // The pool scales with the spell level too, not just the ramp:
        // fourth use at level 3 is 4 x 3 = 12d12.
        assert_eq!(overchannel_once(&mut e, 3).as_deref(), Some("12d12"));
        assert_eq!(e.actors[&evoker].overchannel_uses(), 4);

        // A long rest resets the ramp — the next use is free again.
        e.actors.get_mut(&evoker).unwrap().long_rest();
        assert_eq!(e.actors[&evoker].overchannel_uses(), 0);
        assert_eq!(overchannel_once(&mut e, 1), None);
    }
    /// A Divination Wizard's Portent pool is dormant until something
    /// actually rolls a d20 in the encounter: the template flag alone
    /// hands out no forecast, and a baseline wizard never gets one at
    /// all. Pins the lazy fill's two ends — `has_portent` is template
    /// state, `portent_forecast` is run state — so a future eager fill
    /// at instantiation time can't slip in unnoticed and shift every
    /// seeded encounter's RNG stream by three rolls.
    #[test]
    fn portent_is_dormant_until_the_first_d20() {
        use crate::actors::creatures::wizards::{DIVINATION_WIZARD_TEMPLATE, WIZARD_TEMPLATE};
        let mut e = ei_with_terrain(15, 15, &[]);
        let diviner = e
            .instantiate_creature(&DIVINATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let baseline = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(4, 2), 0, 1)
            .unwrap();
        assert!(e.actors[&diviner].has_portent());
        assert!(!e.actors[&baseline].has_portent());
        assert_eq!(e.actors[&diviner].portent_dice_max(), 3);
        // Nothing forecast yet, and nothing banked.
        assert!(!e.actors[&diviner].portent_forecast());
        assert!(e.actors[&diviner].portent_pool().is_empty());

        // The first d20 anyone rolls fills the bank. The triggering roll
        // is itself a substitution candidate, so the bank lands at
        // either 3 (nothing was decisive) or 2 (the best face was worth
        // spending on the diviner's own roll) — never 0 or 1.
        let _ = e.roll_d20_lucky(diviner, RollMode::Normal);
        assert!(e.actors[&diviner].portent_forecast());
        let banked = e.actors[&diviner].portent_pool().len();
        assert!(
            banked == 3 || banked == 2,
            "the forecast banks 3 faces, at most one of which the triggering \
             roll can immediately consume; got {}",
            banked
        );
    }

    /// A high foretold face is spent on a roll the diviner wants to
    /// succeed — their own, or an ally's — and the substituted value is
    /// returned verbatim in place of the d20. Also pins that the die
    /// leaves the pool exactly once, that the *highest* eligible face is
    /// the one chosen, and that a second roll can't reuse it.
    #[test]
    fn portent_substitutes_its_best_face_on_a_friendly_roll() {
        use crate::actors::creatures::wizards::DIVINATION_WIZARD_TEMPLATE;
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let diviner = e
            .instantiate_creature(&DIVINATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let ally = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(4, 2), 0, 1)
            .unwrap();
        // Seed the bank directly rather than letting the lazy fill roll
        // it, so the assertion is about the spend policy and not about
        // what the seeded roller happened to produce.
        e.actors
            .get_mut(&diviner)
            .unwrap()
            .set_portent_pool(vec![11, 20, 18]);

        // The ally's roll takes the best face, not merely a good one.
        assert_eq!(e.roll_d20_lucky(ally, RollMode::Normal), 20);
        assert_eq!(e.actors[&diviner].portent_pool(), &[11, 18]);
        // The diviner's own roll takes the next best.
        assert_eq!(e.roll_d20_lucky(diviner, RollMode::Normal), 18);
        assert_eq!(e.actors[&diviner].portent_pool(), &[11]);
        // 11 is not decisive, so it stays banked and a real d20 is rolled.
        let rolled = e.roll_d20_lucky(ally, RollMode::Normal);
        assert!((1..=20).contains(&rolled));
        assert_eq!(e.actors[&diviner].portent_pool(), &[11]);
    }

    /// A low foretold face is spent on an enemy's roll — the direction
    /// flip that makes Portent the first feature in the engine to reach
    /// into another actor's d20. Pins that the *lowest* face is chosen
    /// (not the highest, which would be catastrophically backwards) and
    /// that a merely-mediocre face is held rather than wasted.
    #[test]
    fn portent_substitutes_its_worst_face_on_an_enemy_roll() {
        use crate::actors::creatures::wizards::DIVINATION_WIZARD_TEMPLATE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let diviner = e
            .instantiate_creature(&DIVINATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let goblin = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(4, 2), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&diviner)
            .unwrap()
            .set_portent_pool(vec![4, 20, 1]);

        assert_eq!(e.roll_d20_lucky(goblin, RollMode::Normal), 1);
        assert_eq!(e.actors[&diviner].portent_pool(), &[4, 20]);
        assert_eq!(e.roll_d20_lucky(goblin, RollMode::Normal), 4);
        assert_eq!(e.actors[&diviner].portent_pool(), &[20]);
        // The 20 is worthless against an enemy — it stays banked even
        // though the pool is non-empty.
        let rolled = e.roll_d20_lucky(goblin, RollMode::Normal);
        assert!((1..=20).contains(&rolled));
        assert_eq!(e.actors[&diviner].portent_pool(), &[20]);
        // ...and is still there for the ally who needs it.
        assert_eq!(e.roll_d20_lucky(diviner, RollMode::Normal), 20);
        assert!(e.actors[&diviner].portent_pool().is_empty());
    }

    /// RAW gates the substitution on "a creature that you can see", with
    /// the diviner's own rolls exempt from the sight clause. Pins four
    /// branches, the last two of which are also the sharpest available
    /// test of the Third Eye's piercing tier: a blinded diviner can't
    /// sink an enemy's roll; an *Invisible* enemy is still reachable
    /// (The Third Eye is permanent See Invisibility); a *Blurred* one is
    /// not (See Invisibility stops at invisibility, and Blur is a
    /// different lie); and neither gate touches the diviner's own d20.
    #[test]
    fn portent_needs_sight_of_anyone_but_the_diviner() {
        use crate::actors::creatures::wizards::DIVINATION_WIZARD_TEMPLATE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        let seeded = |blind_diviner: bool, goblin_cover: Option<Condition>| -> Vec<u32> {
            let mut e = ei_with_terrain(15, 15, &[]);
            let diviner = e
                .instantiate_creature(&DIVINATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            let goblin = e
                .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(4, 2), 1, 0)
                .unwrap();
            e.actors
                .get_mut(&diviner)
                .unwrap()
                .set_portent_pool(vec![2]);
            if blind_diviner {
                e.actors
                    .get_mut(&diviner)
                    .unwrap()
                    .add_condition(Condition::Blinded, ConditionTimer::Permanent);
            }
            if let Some(c) = goblin_cover {
                e.actors
                    .get_mut(&goblin)
                    .unwrap()
                    .add_condition(c, ConditionTimer::Permanent);
            }
            let _ = e.roll_d20_lucky(goblin, RollMode::Normal);
            e.actors[&diviner].portent_pool().to_vec()
        };
        assert!(seeded(false, None).is_empty(), "plain sight: the 2 lands");
        assert_eq!(
            seeded(true, None),
            vec![2],
            "a blinded diviner foresees nothing they can act on"
        );
        assert!(
            seeded(false, Some(Condition::Invisible)).is_empty(),
            "The Third Eye is See Invisibility — an Invisible target is still reachable"
        );
        assert_eq!(
            seeded(false, Some(Condition::Blurred)),
            vec![2],
            "See Invisibility stops at invisibility; Blur still hides the target"
        );

        // The sight gates never apply to the diviner's own roll.
        let mut e = ei_with_terrain(15, 15, &[]);
        let diviner = e
            .instantiate_creature(&DIVINATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        e.actors
            .get_mut(&diviner)
            .unwrap()
            .set_portent_pool(vec![19]);
        e.actors
            .get_mut(&diviner)
            .unwrap()
            .add_condition(Condition::Blinded, ConditionTimer::Permanent);
        assert_eq!(e.roll_d20_lucky(diviner, RollMode::Normal), 19);
    }

    /// End-to-end through `roll_save`: a foretold 1 sinks an enemy's
    /// saving throw outright. The value matters as much as the pass /
    /// fail — a substituted face is the save's d20, so the modifier
    /// stack still applies on top of it, and a target whose bonus is
    /// large enough would still pass on a foretold 1.
    #[test]
    fn portent_sinks_an_enemy_save_through_roll_save() {
        use crate::actors::creatures::wizards::DIVINATION_WIZARD_TEMPLATE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let diviner = e
            .instantiate_creature(&DIVINATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let goblin = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(4, 2), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&diviner)
            .unwrap()
            .set_portent_pool(vec![1]);
        // A goblin's +2 DEX save clears DC 8 on any natural 6 or better,
        // so the failure is unlikely without the substitution — and the
        // emptied pool below is what actually proves the foretold 1 was
        // the die that got used.
        assert!(
            !e.roll_save(goblin, AbilityScoreType::Dexterity, 8).passed(),
            "a foretold 1 sinks the save"
        );
        assert!(e.actors[&diviner].portent_pool().is_empty());
    }

    /// The forecast is rolled once and only once per long rest, and the
    /// long rest re-arms it. Pins the latch semantics the lazy fill
    /// depends on: `set_portent_pool` is a no-op against an already-
    /// forecast holder (so a mid-encounter re-entry can't refill a spent
    /// bank), and `long_rest` clears both the pool and the latch.
    #[test]
    fn portent_forecasts_once_per_long_rest() {
        use crate::actors::creatures::wizards::DIVINATION_WIZARD_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let diviner = e
            .instantiate_creature(&DIVINATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        {
            let a = e.actors.get_mut(&diviner).unwrap();
            a.set_portent_pool(vec![9, 9, 9]);
            // Second seeding bounces off the latch.
            a.set_portent_pool(vec![20, 20, 20]);
            assert_eq!(a.portent_pool(), &[9, 9, 9]);
            // Spending down to empty leaves the latch set, so the lazy
            // fill won't hand out a fresh bank mid-run.
            while a.take_portent_die(true).is_some() {}
            assert!(a.portent_forecast());
        }
        e.forecast_portent(diviner);
        assert!(e.actors[&diviner].portent_pool().is_empty());

        // A long rest re-arms the forecast, and the next d20 fills it.
        e.actors.get_mut(&diviner).unwrap().long_rest();
        assert!(!e.actors[&diviner].portent_forecast());
        e.forecast_portent(diviner);
        assert!(e.actors[&diviner].portent_forecast());
        assert_eq!(e.actors[&diviner].portent_pool().len(), 3);
        assert!(
            e.actors[&diviner]
                .portent_pool()
                .iter()
                .all(|f| (1..=20).contains(f)),
            "every foretold face is a legal d20 result"
        );
    }

    /// A substituted roll consumes no randomness. RAW's "you must
    /// choose to do so before the roll" means the d20 is never thrown —
    /// and because every roll in the engine comes off one seeded
    /// roller, "never thrown" has to mean the roller doesn't advance,
    /// or a spent portent would silently reshuffle every subsequent
    /// die in the encounter.
    ///
    /// Two identically-seeded encounters differing only in whether the
    /// diviner's bank holds a decisive face: the roll *after* the
    /// substitution in the first must be the roll that the second gets
    /// first.
    #[test]
    fn portent_substitution_does_not_advance_the_roller() {
        use crate::actors::creatures::wizards::DIVINATION_WIZARD_TEMPLATE;
        let stream = |bank: Vec<u32>| -> Vec<u32> {
            let mut e = ei_with_terrain(15, 15, &[]);
            let diviner = e
                .instantiate_creature(&DIVINATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            // Seeding the bank — even with an empty vec — latches the
            // forecast, so neither run pays for a lazy fill and the two
            // rollers stay in lockstep.
            e.actors.get_mut(&diviner).unwrap().set_portent_pool(bank);
            (0..4)
                .map(|_| e.roll_d20_lucky(diviner, RollMode::Normal))
                .collect()
        };
        let substituted = stream(vec![20]);
        let untouched = stream(Vec::new());
        assert_eq!(substituted[0], 20, "the foretold face is returned verbatim");
        assert_eq!(
            &substituted[1..],
            &untouched[..3],
            "the roller picks up exactly where it would have without the spend"
        );
    }

    /// Expert Divination refunds the best expended slot below the cast's
    /// level. Pins the band arithmetic (`1..=min(level - 1, 5)`),
    /// highest-first selection inside it, and the three gates: wrong
    /// school, too low a level, and no feature.
    #[test]
    fn expert_divination_refunds_the_best_lower_slot() {
        use crate::actors::creatures::wizards::{DIVINATION_WIZARD_TEMPLATE, WIZARD_TEMPLATE};
        use crate::engine::types::SpellSchool;
        let spent = |e: &EncounterInstance, id: usize, lvl: u32| -> u32 {
            let ssi = e.actors[&id].spell_slot_manager.spell_slots(lvl);
            ssi.max_spell_slots - ssi.spell_slots
        };
        let mut e = ei_with_terrain(15, 15, &[]);
        let diviner = e
            .instantiate_creature(&DIVINATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let baseline = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(4, 2), 0, 1)
            .unwrap();
        for id in [diviner, baseline] {
            let a = e.actors.get_mut(&id).unwrap();
            for lvl in 1..=7 {
                a.spell_slot_manager.consume_spell_slot(lvl);
            }
        }
        // A level-3 divination cast refunds the best slot at or below 2.
        e.trigger_expert_divination(diviner, 3, Some(SpellSchool::Divination));
        assert_eq!(spent(&e, diviner, 2), 0, "the level-2 slot came back");
        assert_eq!(spent(&e, diviner, 1), 1, "the level-1 slot did not");

        // A level-9 cast caps the band at 5 — it can't refund the 7.
        e.trigger_expert_divination(diviner, 9, Some(SpellSchool::Divination));
        assert_eq!(spent(&e, diviner, 5), 0);
        assert_eq!(spent(&e, diviner, 7), 1, "the band never reaches above 5th");

        // Gates: wrong school, cantrip / 1st level, and no feature.
        let before = spent(&e, diviner, 4);
        e.trigger_expert_divination(diviner, 5, Some(SpellSchool::Evocation));
        e.trigger_expert_divination(diviner, 5, None);
        e.trigger_expert_divination(diviner, 1, Some(SpellSchool::Divination));
        e.trigger_expert_divination(diviner, 0, Some(SpellSchool::Divination));
        assert_eq!(spent(&e, diviner, 4), before, "every gate held");
        e.trigger_expert_divination(baseline, 3, Some(SpellSchool::Divination));
        assert_eq!(spent(&e, baseline, 2), 1, "a baseline wizard gets no refund");
    }

    /// Expert Divination end-to-end through `Action::execute`: casting
    /// Mind Spike (level 2, divination) refunds a level-1 slot. Proves
    /// the school tag, the post-cast registry wiring, and the band
    /// arithmetic line up on a real cast rather than only at the hook.
    #[test]
    fn expert_divination_fires_through_action_execute() {
        use crate::actions::spells::MIND_SPIKE;
        use crate::actors::creatures::wizards::DIVINATION_WIZARD_TEMPLATE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let diviner = e
            .instantiate_creature(&DIVINATION_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let goblin = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(4, 2), 1, 0)
            .unwrap();
        {
            let a = e.actors.get_mut(&diviner).unwrap();
            a.give_resource(crate::engine::side_effects::Resource::Action);
            a.spell_slot_manager.consume_spell_slot(1);
        }
        let l1_before = e.actors[&diviner].spell_slot_manager.spell_slots(1).spell_slots;
        for ef in MIND_SPIKE.execute(&mut e, diviner, Some(&vec![goblin]), None, None) {
            ef.apply(&mut e);
        }
        assert_eq!(
            e.actors[&diviner].spell_slot_manager.spell_slots(1).spell_slots,
            l1_before + 1,
            "the level-1 slot came back off the level-2 divination cast"
        );
    }

    /// Drift pin on the divination `school()` tags. Expert Divination is
    /// the only consumer today and it fails closed on an untagged spell,
    /// so an un-tagged divination pickup would silently stop refunding
    /// slots with nothing else to notice.
    #[test]
    fn divination_spells_report_their_school() {
        use crate::actions::spells::{
            FORESIGHT, GUIDANCE, HUNTERS_MARK, MIND_SPIKE, TRUE_SEEING, TRUE_STRIKE,
        };
        use crate::engine::types::SpellSchool;
        let divinations: Vec<&'static dyn crate::actions::action_template::Action> = vec![
            &*TRUE_STRIKE,
            &*GUIDANCE,
            &*HUNTERS_MARK,
            &*MIND_SPIKE,
            &*TRUE_SEEING,
            &*FORESIGHT,
        ];
        for spell in divinations {
            assert_eq!(
                spell.school(),
                Some(SpellSchool::Divination),
                "{} must report the divination school",
                spell.name()
            );
        }
    }
    /// `viewer_can_see` respects walls. The helper answers "can the
    /// viewer see the subject right now", and terrain is the third way
    /// that answer can be no — alongside the viewer being Blinded and
    /// the subject being illusion-concealed. Pinned on both a
    /// consumer-visible path (a Divination Wizard's Portent, which can
    /// only reach a creature it can see) and the helper directly, so a
    /// future refactor can't quietly drop the clause back out.
    #[test]
    fn viewer_can_see_is_blocked_by_walls() {
        use crate::actors::creatures::wizards::DIVINATION_WIZARD_TEMPLATE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        // A full-height wall column at x=3 splits the map in two.
        let wall: Vec<(isize, isize)> = (0..11).map(|y| (3, y)).collect();
        let mut e = ei_with_terrain(11, 11, &wall);
        let diviner = e
            .instantiate_creature(&DIVINATION_WIZARD_TEMPLATE, Coordinate::new(1, 5), 0, 0)
            .unwrap();
        let walled_off = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(6, 5), 1, 0)
            .unwrap();
        let in_the_open = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(1, 8), 1, 1)
            .unwrap();
        assert!(!e.viewer_can_see(diviner, walled_off));
        assert!(e.viewer_can_see(diviner, in_the_open));

        e.actors
            .get_mut(&diviner)
            .unwrap()
            .set_portent_pool(vec![1]);
        // The goblin behind the wall rolls unmolested...
        let rolled = e.roll_d20_lucky(walled_off, RollMode::Normal);
        assert!((1..=20).contains(&rolled));
        assert_eq!(e.actors[&diviner].portent_pool(), &[1]);
        // ...while the one in the open eats the foretold 1.
        assert_eq!(e.roll_d20_lucky(in_the_open, RollMode::Normal), 1);
        assert!(e.actors[&diviner].portent_pool().is_empty());
    }
    /// The piercing tiers are a strict hierarchy, and every tier
    /// pierces exactly its own cohort. Drift pin on the containment
    /// invariant `ConcealmentPiercing` relies on to return the first
    /// (strongest) source it finds rather than unioning cohorts: if a
    /// future concealment condition were added to
    /// `countered_by_see_invisibility` without also joining
    /// `countered_by_truesight`, a Truesight holder would silently stop
    /// seeing through something a See Invisibility holder does.
    #[test]
    fn concealment_piercing_tiers_are_a_strict_hierarchy() {
        for c in [
            Condition::Invisible,
            Condition::Blurred,
            Condition::Displaced,
            Condition::Dodging,
            Condition::Prone,
        ] {
            assert!(
                !c.countered_by_see_invisibility() || c.countered_by_truesight(),
                "{:?} is pierced by See Invisibility but not by Truesight",
                c
            );
            assert!(
                !ConcealmentPiercing::None.pierces(c),
                "the None tier pierces nothing"
            );
            assert_eq!(
                ConcealmentPiercing::All.pierces(c),
                c.countered_by_truesight()
            );
            assert_eq!(
                ConcealmentPiercing::Invisibility.pierces(c),
                c.countered_by_see_invisibility()
            );
        }
        assert!(ConcealmentPiercing::None < ConcealmentPiercing::Invisibility);
        assert!(ConcealmentPiercing::Invisibility < ConcealmentPiercing::All);
    }

    /// `concealment_piercing_of` reports the strongest source the viewer
    /// holds. Walks a single viewer up the ladder — nothing, then See
    /// Invisibility, then True Seeing — and pins that the stronger tier
    /// wins when both are held, which is what makes "return the first
    /// hit" correct rather than merely convenient.
    #[test]
    fn concealment_piercing_reports_the_strongest_source() {
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        let mut e = ei_with_terrain(30, 30, &[]);
        let viewer = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(1, 1), 0, 0)
            .unwrap();
        // Far apart so no 10-ft range-gated piercer could be involved.
        let subject = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(25, 25), 1, 0)
            .unwrap();
        assert_eq!(
            e.concealment_piercing_of(viewer, subject),
            ConcealmentPiercing::None
        );
        assert!(!e.pierces_illusion_of(viewer, subject));

        e.actors
            .get_mut(&viewer)
            .unwrap()
            .add_condition(Condition::SeeingInvisible, ConditionTimer::Rounds(10));
        assert_eq!(
            e.concealment_piercing_of(viewer, subject),
            ConcealmentPiercing::Invisibility
        );
        assert!(
            !e.pierces_illusion_of(viewer, subject),
            "pierces_illusion_of means the whole cohort, which this tier is not"
        );

        e.actors
            .get_mut(&viewer)
            .unwrap()
            .add_condition(Condition::TrueSighted, ConditionTimer::Rounds(10));
        assert_eq!(
            e.concealment_piercing_of(viewer, subject),
            ConcealmentPiercing::All,
            "the stronger source wins when both are held"
        );
        assert!(e.pierces_illusion_of(viewer, subject));
    }

    /// See Invisibility at the attack-mode clauses, on both polarities
    /// and against both halves of the cohort. The interesting cell is
    /// the one a boolean piercer got wrong: a See Invisibility holder
    /// swinging at a Blurred target is still at disadvantage, where a
    /// True Seeing holder is not.
    #[test]
    fn see_invisibility_suppresses_only_the_invisible_row() {
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        let mode = |viewer_sight: Option<Condition>, target_cover: Condition| -> RollMode {
            let mut e = ei_with_terrain(15, 15, &[]);
            let attacker = e
                .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            let target = e
                .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(9, 9), 1, 0)
                .unwrap();
            if let Some(c) = viewer_sight {
                e.actors
                    .get_mut(&attacker)
                    .unwrap()
                    .add_condition(c, ConditionTimer::Rounds(10));
            }
            e.actors
                .get_mut(&target)
                .unwrap()
                .add_condition(target_cover, ConditionTimer::Rounds(10));
            e.compute_attack_mode(attacker, target, false)
        };
        // Baseline: both concealments impose disadvantage.
        assert_eq!(mode(None, Condition::Invisible), RollMode::Disadvantage);
        assert_eq!(mode(None, Condition::Blurred), RollMode::Disadvantage);
        // See Invisibility lifts one of them and only one.
        assert_eq!(
            mode(Some(Condition::SeeingInvisible), Condition::Invisible),
            RollMode::Normal
        );
        assert_eq!(
            mode(Some(Condition::SeeingInvisible), Condition::Blurred),
            RollMode::Disadvantage,
            "Blur is not invisibility — the lv2 spell does nothing here"
        );
        // True Seeing lifts both, which is what the extra four slot
        // levels buy.
        assert_eq!(
            mode(Some(Condition::TrueSighted), Condition::Invisible),
            RollMode::Normal
        );
        assert_eq!(
            mode(Some(Condition::TrueSighted), Condition::Blurred),
            RollMode::Normal
        );

        // Target-side polarity: an Invisible attacker's advantage is
        // suppressed by a defender who can see invisible creatures.
        // Only `Invisible` is in the `grants_self_attack_advantage`
        // cohort — Blur and Displacement make you harder to hit without
        // making you better at hitting — so this polarity has exactly
        // one row for See Invisibility to act on, and the tier
        // distinction that mattered on the attacker side is moot here.
        let target_side = |defender_sight: Option<Condition>, attacker_cover: Condition| -> RollMode {
            let mut e = ei_with_terrain(15, 15, &[]);
            let attacker = e
                .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            let defender = e
                .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(9, 9), 1, 0)
                .unwrap();
            e.actors
                .get_mut(&attacker)
                .unwrap()
                .add_condition(attacker_cover, ConditionTimer::Rounds(10));
            if let Some(c) = defender_sight {
                e.actors
                    .get_mut(&defender)
                    .unwrap()
                    .add_condition(c, ConditionTimer::Rounds(10));
            }
            e.compute_attack_mode(attacker, defender, false)
        };
        assert_eq!(
            target_side(None, Condition::Invisible),
            RollMode::Advantage,
            "baseline: an Invisible attacker swings at advantage"
        );
        assert_eq!(
            target_side(Some(Condition::SeeingInvisible), Condition::Invisible),
            RollMode::Normal,
            "the defender sees them coming"
        );
        assert_eq!(
            target_side(Some(Condition::SeeingInvisible), Condition::Blurred),
            RollMode::Normal,
            "a Blurred attacker never had advantage to suppress"
        );
    }

    /// The See Invisibility spell end-to-end through `Action::execute`:
    /// a level-2 slot, a self-install, and the resulting piercing tier.
    /// Also pins the anti-waste gate — the spell refuses to fire over an
    /// existing sight buff, including the strictly stronger True Seeing.
    #[test]
    fn see_invisibility_installs_the_invisibility_tier() {
        use crate::actions::spells::SEE_INVISIBILITY;
        use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let wizard = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let goblin = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(9, 9), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&wizard)
            .unwrap()
            .give_resource(crate::engine::side_effects::Resource::Action);
        assert!(SEE_INVISIBILITY.custom_validate_input(&e, wizard, None, None, None));
        let l2_before = e.actors[&wizard].spell_slot_manager.spell_slots(2).spell_slots;
        for ef in SEE_INVISIBILITY.execute(&mut e, wizard, None, None, None) {
            ef.apply(&mut e);
        }
        assert!(e.actors[&wizard].has_condition(Condition::SeeingInvisible));
        assert_eq!(
            e.actors[&wizard].spell_slot_manager.spell_slots(2).spell_slots,
            l2_before - 1,
            "a level-2 slot paid for it"
        );
        assert_eq!(
            e.concealment_piercing_of(wizard, goblin),
            ConcealmentPiercing::Invisibility
        );
        // Already buffed — no double-cast.
        assert!(!SEE_INVISIBILITY.custom_validate_input(&e, wizard, None, None, None));
        e.actors
            .get_mut(&wizard)
            .unwrap()
            .remove_condition(Condition::SeeingInvisible);
        e.actors
            .get_mut(&wizard)
            .unwrap()
            .add_condition(Condition::TrueSighted, ConditionTimer::Rounds(10));
        assert!(
            !SEE_INVISIBILITY.custom_validate_input(&e, wizard, None, None, None),
            "True Seeing is a strict superset — the lv2 slot would be thrown away"
        );
    }

    /// The Divination Wizard's Third Eye reaches the same tier as the
    /// spell without spending anything, and stops in the same place.
    /// Pins the passive-feature half of the `Invisibility` tier next to
    /// the condition half.
    #[test]
    fn third_eye_grants_permanent_see_invisibility() {
        use crate::actors::creatures::wizards::{DIVINATION_WIZARD_TEMPLATE, WIZARD_TEMPLATE};
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        let mut e = ei_with_terrain(30, 30, &[]);
        let diviner = e
            .instantiate_creature(&DIVINATION_WIZARD_TEMPLATE, Coordinate::new(1, 1), 0, 0)
            .unwrap();
        let baseline = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(1, 3), 0, 1)
            .unwrap();
        // Far enough that no 10-ft range-gated piercer can be involved.
        let goblin = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(25, 25), 1, 0)
            .unwrap();
        assert_eq!(
            e.concealment_piercing_of(diviner, goblin),
            ConcealmentPiercing::Invisibility,
            "no action, no slot, no condition — the tag alone"
        );
        assert_eq!(
            e.concealment_piercing_of(baseline, goblin),
            ConcealmentPiercing::None
        );
        e.actors
            .get_mut(&goblin)
            .unwrap()
            .add_condition(Condition::Invisible, ConditionTimer::Rounds(10));
        assert!(e.viewer_can_see(diviner, goblin));
        assert!(!e.viewer_can_see(baseline, goblin));
        // ...and stops at invisibility for both the tag and the spell.
        e.actors
            .get_mut(&goblin)
            .unwrap()
            .add_condition(Condition::Blurred, ConditionTimer::Rounds(10));
        assert!(
            !e.viewer_can_see(diviner, goblin),
            "a subject wearing both is hidden on the strength of the Blur"
        );
    }
    /// A charmer can walk away from the creature they charmed without
    /// provoking. The opportunity-attack dispatcher runs the reactor's
    /// attack side-effects directly and never calls `Action::validate`,
    /// so the RAW "can't attack the charmer" restriction used to bind
    /// the charmed creature only on its own turn — every charm in the
    /// engine leaked a free swing the moment the charmer disengaged.
    /// Pinned against the same move made by a *non*-charmer, which must
    /// still eat the OA.
    #[test]
    fn charmed_creature_does_not_opportunity_attack_its_charmer() {
        use crate::actors::creatures::bandits::BANDIT_TEMPLATE;
        use crate::engine::side_effects::SetConditionLink;
        // Observable is the reactor's *reaction slot*, not HP: the OA
        // could roll a miss and leave HP untouched for the wrong reason,
        // but the slot is spent the moment the dispatcher decides the
        // reactor is a candidate.
        let reaction_spent = |charm_the_reactor: bool| -> bool {
            let mut e = ei_with_terrain(15, 15, &[]);
            let charmer = e
                .instantiate_creature(&BANDIT_TEMPLATE, Coordinate::new(5, 5), 0, 0)
                .unwrap();
            let reactor = e
                .instantiate_creature(&BANDIT_TEMPLATE, Coordinate::new(6, 5), 1, 0)
                .unwrap();
            if charm_the_reactor {
                SetConditionLink {
                    target_id: reactor,
                    condition: Condition::Charmed,
                    source: Some(charmer),
                }
                .apply(&mut e);
                e.actors
                    .get_mut(&reactor)
                    .unwrap()
                    .add_condition(Condition::Charmed, ConditionTimer::Rounds(10));
            }
            assert!(e.actors[&reactor].has_reaction());
            e.dispatch_opportunity_attacks(
                charmer,
                Coordinate::new(5, 5),
                Coordinate::new(10, 10),
            );
            !e.actors[&reactor].has_reaction()
        };
        assert!(
            reaction_spent(false),
            "an un-charmed reactor still opportunity-attacks"
        );
        assert!(
            !reaction_spent(true),
            "the charmer walks away without provoking"
        );
    }

    /// Riposte is an attack, so a charmed Battle Master can't fire it at
    /// their charmer — but the purely defensive reactions that share its
    /// eligibility gate (Uncanny Dodge, Deflect Missiles, Parry) stay
    /// available, because RAW forbids attacking the charmer, not
    /// surviving them. Pins the charge, which is the observable the
    /// riposte spends.
    #[test]
    fn charmed_fighter_does_not_riposte_its_charmer() {
        use crate::actions::class_features::RIPOSTE_TAG;
        use crate::actors::creatures::bandits::BANDIT_TEMPLATE;
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::engine::side_effects::SetConditionLink;
        let charge_spent = |charm_the_fighter: bool| -> bool {
            let mut e = ei_with_terrain(15, 15, &[]);
            let fighter = e
                .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
                .unwrap();
            let attacker = e
                .instantiate_creature(&BANDIT_TEMPLATE, Coordinate::new(6, 5), 1, 0)
                .unwrap();
            if charm_the_fighter {
                SetConditionLink {
                    target_id: fighter,
                    condition: Condition::Charmed,
                    source: Some(attacker),
                }
                .apply(&mut e);
                e.actors
                    .get_mut(&fighter)
                    .unwrap()
                    .add_condition(Condition::Charmed, ConditionTimer::Rounds(10));
            }
            assert!(e.actors[&fighter].feature_available(RIPOSTE_TAG));
            crate::engine::attack::try_fire_riposte(&mut e, fighter, attacker);
            !e.actors[&fighter].feature_available(RIPOSTE_TAG)
        };
        assert!(charge_spent(false), "the baseline riposte fires");
        assert!(
            !charge_spent(true),
            "a charmed fighter holds its counter-attack"
        );
    }

    /// The "don't target the charmer" clause binds on every name in a
    /// multi-target action's list, not just the first. The reach / LOS
    /// clauses beside it in `validate` are deliberately first-target-
    /// only — a multi-target action measures its envelope off its
    /// primary — which is exactly why the charm gate had to stop
    /// borrowing their `.first()`.
    #[test]
    fn charm_gate_covers_every_target_in_the_list() {
        use crate::actions::monster_attacks::SCIMITAR;
        use crate::actors::creatures::bandits::BANDIT_TEMPLATE;
        use crate::engine::side_effects::SetConditionLink;
        let mut e = ei_with_terrain(15, 15, &[]);
        let charmer = e
            .instantiate_creature(&BANDIT_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let charmed = e
            .instantiate_creature(&BANDIT_TEMPLATE, Coordinate::new(3, 3), 1, 0)
            .unwrap();
        let bystander = e
            .instantiate_creature(&BANDIT_TEMPLATE, Coordinate::new(4, 3), 2, 0)
            .unwrap();
        SetConditionLink {
            target_id: charmed,
            condition: Condition::Charmed,
            source: Some(charmer),
        }
        .apply(&mut e);
        e.actors
            .get_mut(&charmed)
            .unwrap()
            .add_condition(Condition::Charmed, ConditionTimer::Rounds(10));
        assert!(
            SCIMITAR.validate_input(&e, charmed, Some(&vec![bystander]), None, None),
            "a list without the charmer is fine"
        );
        assert!(
            !SCIMITAR.validate_input(
                &e,
                charmed,
                Some(&vec![bystander, charmer]),
                None,
                None
            ),
            "the charmer named second is still the charmer"
        );
        assert!(e.charm_blocks_hostility(charmed, charmer));
        assert!(!e.charm_blocks_hostility(charmed, bystander));
        assert!(
            !e.charm_blocks_hostility(charmer, charmed),
            "the restriction is one-directional"
        );
    }
    /// Split Enchantment lands a single-target enchantment on a second
    /// creature for free. Driven with Heroism — a no-save, no-attack-
    /// roll level-1 enchantment — so the assertion is about the
    /// doubling and not about a die. Pinned against a baseline wizard
    /// casting the same spell in the same encounter.
    #[test]
    fn split_enchantment_doubles_a_single_target_enchantment() {
        use crate::actions::spells::HEROISM;
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::actors::creatures::wizards::{ENCHANTMENT_WIZARD_TEMPLATE, WIZARD_TEMPLATE};
        let both_blessed = |enchanter: bool| -> (bool, bool) {
            let mut e = ei_with_terrain(15, 15, &[]);
            let template = if enchanter {
                &*ENCHANTMENT_WIZARD_TEMPLATE
            } else {
                &*WIZARD_TEMPLATE
            };
            let caster = e
                .instantiate_creature(template, Coordinate::new(5, 5), 0, 0)
                .unwrap();
            let primary = e
                .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(6, 5), 0, 1)
                .unwrap();
            let second = e
                .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(7, 5), 0, 2)
                .unwrap();
            {
                let a = e.actors.get_mut(&caster).unwrap();
                a.give_resource(crate::engine::side_effects::Resource::BonusAction);
                a.spell_slot_manager.restore_spell_slots();
            }
            for ef in HEROISM.execute(&mut e, caster, Some(&vec![primary]), None, None) {
                ef.apply(&mut e);
            }
            (
                e.actors[&primary].has_condition(Condition::Heroic),
                e.actors[&second].has_condition(Condition::Heroic),
            )
        };
        assert_eq!(
            both_blessed(false),
            (true, false),
            "a baseline wizard's Heroism lands on one ally"
        );
        assert_eq!(
            both_blessed(true),
            (true, true),
            "the enchanter's lands on two"
        );
    }

    /// Split Enchantment's three gates. RAW restricts it to enchantment
    /// spells of 1st level or higher, and the cantrip exclusion is
    /// load-bearing — without it Vicious Mockery and Mind Sliver become
    /// free at-will double-taps.
    #[test]
    fn split_enchantment_gates_on_school_level_and_feature() {
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::actors::creatures::wizards::{ENCHANTMENT_WIZARD_TEMPLATE, WIZARD_TEMPLATE};
        use crate::engine::types::SpellSchool;
        let mut e = ei_with_terrain(15, 15, &[]);
        let enchanter = e
            .instantiate_creature(&ENCHANTMENT_WIZARD_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        let baseline = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(5, 7), 0, 1)
            .unwrap();
        let primary = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(6, 5), 1, 0)
            .unwrap();
        let _second = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(7, 5), 1, 1)
            .unwrap();
        let split = |e: &mut EncounterInstance, caster, school, lvl| {
            e.consume_split_enchantment(caster, "test", school, lvl, true, None, false, primary)
        };
        assert!(
            split(&mut e, enchanter, Some(SpellSchool::Enchantment), 1).is_some(),
            "a level-1 enchantment splits"
        );
        assert!(
            split(&mut e, enchanter, Some(SpellSchool::Enchantment), 0).is_none(),
            "cantrips are excluded — RAW, and the reason at-will control isn't doubled"
        );
        assert!(
            split(&mut e, enchanter, Some(SpellSchool::Evocation), 3).is_none(),
            "wrong school"
        );
        assert!(split(&mut e, enchanter, None, 3).is_none(), "untagged fails closed");
        assert!(
            split(&mut e, baseline, Some(SpellSchool::Enchantment), 3).is_none(),
            "a baseline wizard has no feature"
        );
    }

    /// A caster holding both doubling features doubles once. `execute`
    /// offers the sorcery-point prime first and only falls through to
    /// the free passive if it didn't fire, so the two can never stack
    /// into a triple-target cast.
    #[test]
    fn twinned_spell_and_split_enchantment_do_not_stack() {
        use crate::actions::spells::HEROISM;
        use crate::actors::actor_template::CreatureTemplate;
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::actors::creatures::wizards::ENCHANTMENT_WIZARD_TEMPLATE;
        use std::sync::LazyLock;
        // No shipping template holds both — RAW can't produce one
        // without a multiclass — so the test builds the hypothetical
        // carrier rather than asserting on a build that can't exist.
        static BOTH: LazyLock<CreatureTemplate> = LazyLock::new(|| CreatureTemplate {
            name: "Enchanter/Sorcerer",
            sorcery_points: 5,
            ..ENCHANTMENT_WIZARD_TEMPLATE.clone()
        });
        let mut e = ei_with_terrain(15, 15, &[]);
        let caster = e
            .instantiate_creature(&BOTH, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        let allies: Vec<usize> = (0..3)
            .map(|i| {
                e.instantiate_creature(
                    &FIGHTER_TEMPLATE,
                    Coordinate::new(6 + i as isize, 5),
                    0,
                    1 + i,
                )
                .unwrap()
            })
            .collect();
        {
            let a = e.actors.get_mut(&caster).unwrap();
            a.give_resource(crate::engine::side_effects::Resource::BonusAction);
            a.spell_slot_manager.restore_spell_slots();
            a.add_condition(Condition::TwinnedSpelling, ConditionTimer::Rounds(10));
            a.give_sorcery_points(5);
        }
        for ef in HEROISM.execute(&mut e, caster, Some(&vec![allies[0]]), None, None) {
            ef.apply(&mut e);
        }
        let hit = allies
            .iter()
            .filter(|id| e.actors[id].has_condition(Condition::Heroic))
            .count();
        assert_eq!(hit, 2, "exactly two targets, never three");
        assert!(
            !e.actors[&caster].has_condition(Condition::TwinnedSpelling),
            "the paid prime is what fired, so it was consumed"
        );
    }

    /// Hypnotic Gaze installs the full RAW payload on a failed save:
    /// Charmed *plus* the `Charmed` back-link *plus* Incapacitated. The
    /// link is what makes the two clauses one effect — a gazed creature
    /// can't attack the enchanter on its own turn, and (via the shared
    /// charm gate) can't opportunity-attack or riposte them either.
    ///
    /// Seed-swept because the payload rides a WIS save; the assertion
    /// is over the seeds where the save actually failed, plus a pin
    /// that at least one such seed exists.
    #[test]
    fn hypnotic_gaze_charms_and_incapacitates_on_a_failed_save() {
        use crate::actions::class_features::HYPNOTIC_GAZE;
        use crate::actions::monster_attacks::SCIMITAR;
        use crate::actors::creatures::bandits::BANDIT_TEMPLATE;
        use crate::actors::creatures::wizards::ENCHANTMENT_WIZARD_TEMPLATE;
        let mut failures = 0;
        for seed in 0..40u64 {
            let mut e = ei_with_terrain_seeded(15, 15, &[], seed);
            let enchanter = e
                .instantiate_creature(&ENCHANTMENT_WIZARD_TEMPLATE, Coordinate::new(5, 5), 0, 0)
                .unwrap();
            let victim = e
                .instantiate_creature(&BANDIT_TEMPLATE, Coordinate::new(6, 5), 1, 0)
                .unwrap();
            e.actors
                .get_mut(&enchanter)
                .unwrap()
                .give_resource(crate::engine::side_effects::Resource::Action);
            assert!(
                HYPNOTIC_GAZE.validate_input(&e, enchanter, Some(&vec![victim]), None, None),
                "the gaze is available against an adjacent, un-charmed target"
            );
            for ef in HYPNOTIC_GAZE.execute(&mut e, enchanter, Some(&vec![victim]), None, None) {
                ef.apply(&mut e);
            }
            if !e.actors[&victim].has_condition(Condition::Charmed) {
                // Save made — nothing installs, including the link.
                assert!(!e.actors[&victim].has_condition(Condition::Incapacitated));
                assert_eq!(e.actors[&victim].linked_by(Condition::Charmed), None);
                continue;
            }
            failures += 1;
            assert!(
                e.actors[&victim].has_condition(Condition::Incapacitated),
                "Charmed alone would leave the victim free to hit the enchanter's allies"
            );
            assert_eq!(e.actors[&victim].linked_by(Condition::Charmed), Some(enchanter));
            assert!(e.charm_blocks_hostility(victim, enchanter));
            assert!(
                !SCIMITAR.validate_input(&e, victim, Some(&vec![enchanter]), None, None),
                "the gazed creature can't swing back at the enchanter"
            );
            // ...and the gaze won't be re-spent on an already-locked target.
            assert!(
                !HYPNOTIC_GAZE.validate_input(&e, enchanter, Some(&vec![victim]), None, None)
            );
        }
        assert!(failures > 0, "no seed produced a failed save — test is vacuous");
    }

    /// Drift pin on the enchantment `school()` tags. Split Enchantment
    /// fails closed on an untagged spell, so an un-tagged enchantment
    /// pickup would silently stop doubling with nothing else to notice.
    #[test]
    fn enchantment_spells_report_their_school() {
        use crate::actions::spells::{
            BANE, BLESS, CHARM_MONSTER, CHARM_PERSON, COMMAND, COMPULSION, CONFUSION,
            CROWN_OF_MADNESS, DOMINATE_BEAST, DOMINATE_MONSTER, DOMINATE_PERSON, FEEBLEMIND,
            HEROISM, HOLD_MONSTER, HOLD_PERSON, HYPNOTIC_PATTERN, MASS_SUGGESTION, MIND_SLIVER,
            OTTOS_IRRESISTIBLE_DANCE, POWER_WORD_KILL, POWER_WORD_PAIN, POWER_WORD_STUN, SLEEP,
            SUGGESTION, TASHAS_HIDEOUS_LAUGHTER, VICIOUS_MOCKERY,
        };
        use crate::engine::types::SpellSchool;
        let enchantments: Vec<&'static dyn crate::actions::action_template::Action> = vec![
            &*CHARM_PERSON,
            &*CHARM_MONSTER,
            &*HOLD_PERSON,
            &*HOLD_MONSTER,
            &*COMMAND,
            &*SUGGESTION,
            &*MASS_SUGGESTION,
            &*DOMINATE_PERSON,
            &*DOMINATE_BEAST,
            &*DOMINATE_MONSTER,
            &*CONFUSION,
            &*CROWN_OF_MADNESS,
            &*HYPNOTIC_PATTERN,
            &*SLEEP,
            &*TASHAS_HIDEOUS_LAUGHTER,
            &*COMPULSION,
            &*OTTOS_IRRESISTIBLE_DANCE,
            &*POWER_WORD_STUN,
            &*POWER_WORD_KILL,
            &*POWER_WORD_PAIN,
            &*FEEBLEMIND,
            &*BANE,
            &*BLESS,
            &*HEROISM,
            &*MIND_SLIVER,
            &*VICIOUS_MOCKERY,
        ];
        for spell in enchantments {
            assert_eq!(
                spell.school(),
                Some(SpellSchool::Enchantment),
                "{} must report the enchantment school",
                spell.name()
            );
        }
    }
    /// Regression: a **twinned concentration spell** used to land on the
    /// second target only. `Action::execute` re-runs the spell's
    /// `side_effects` for the twin and appends the result, which for a
    /// concentration spell produced a second `StartConcentration` — and
    /// that effect's first act is `drop_concentration`, which tore the
    /// condition straight back off the first target. Twinned Spell
    /// therefore did nothing for its sorcery points on Hold Person /
    /// Heroism / Bestow Curse / Crown of Madness: exactly the spells
    /// worth twinning.
    ///
    /// Both targets must hold the condition, the caster must be
    /// concentrating on one spell, and dropping it must clean up both —
    /// the last clause is what distinguishes a real merge from an
    /// install that merely skipped the teardown.
    #[test]
    fn twinned_concentration_spell_holds_both_targets() {
        use crate::actions::spells::HEROISM;
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::actors::creatures::sorcerers::SORCERER_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let sorcerer = e
            .instantiate_creature(&SORCERER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        let primary = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(6, 5), 0, 1)
            .unwrap();
        let twin = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(7, 5), 0, 2)
            .unwrap();
        {
            let a = e.actors.get_mut(&sorcerer).unwrap();
            a.give_resource(crate::engine::side_effects::Resource::BonusAction);
            a.spell_slot_manager.restore_spell_slots();
            a.give_sorcery_points(5);
            a.add_condition(Condition::TwinnedSpelling, ConditionTimer::Rounds(10));
        }
        for ef in HEROISM.execute(&mut e, sorcerer, Some(&vec![primary]), None, None) {
            ef.apply(&mut e);
        }
        assert!(
            e.actors[&primary].has_condition(Condition::Heroic),
            "the primary target keeps the buff the caster paid for"
        );
        assert!(e.actors[&twin].has_condition(Condition::Heroic));
        assert!(e.actors[&sorcerer].is_concentrating());

        // One concentration, two targets — and dropping it cleans up
        // both. A merge that only suppressed the second install would
        // leave the twin's buff stranded here.
        e.drop_concentration(sorcerer);
        assert!(!e.actors[&primary].has_condition(Condition::Heroic));
        assert!(!e.actors[&twin].has_condition(Condition::Heroic));
        assert!(!e.actors[&sorcerer].is_concentrating());
    }

    /// Trickery Domain template drift pin. The domain is the only one
    /// that *removes* something from the inherited chassis — RAW gives
    /// every cleric exactly one Divine Strike and varies its typing —
    /// so the assertion that matters most here is the negative one: no
    /// radiant arm, no radiant tag, exactly one level-8 prime.
    #[test]
    fn trickery_cleric_swaps_divine_strike_rather_than_stacking_it() {
        use crate::actions::class_features::{
            DESTROY_UNDEAD_TAG, DIVINE_STRIKE_POISON_TAG, DIVINE_STRIKE_TAG,
            INVOKE_DUPLICITY_TAG, PRESERVE_LIFE_TAG, TURN_UNDEAD_TAG,
        };
        use crate::actors::creatures::clerics::{CLERIC_TEMPLATE, TRICKERY_CLERIC_TEMPLATE};
        let mut e = ei_with_terrain(15, 15, &[]);
        let cleric = e
            .instantiate_creature(&TRICKERY_CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // The poison arm is present and charged; the radiant arm is gone
        // in both of the places it could linger.
        assert!(e.actors[&cleric].has_passive_feature(DIVINE_STRIKE_POISON_TAG));
        assert!(e.actors[&cleric].feature_available(DIVINE_STRIKE_POISON_TAG));
        assert!(
            e.actors[&cleric].find_action("divine strike poison").is_some(),
            "the poison arm needs an action surface"
        );
        assert!(
            !e.actors[&cleric].has_passive_feature(DIVINE_STRIKE_TAG),
            "the radiant tag must be dropped, not merely shadowed"
        );
        assert!(
            e.actors[&cleric].find_action("divine strike").is_none(),
            "the radiant action must be filtered out of the inherited list"
        );
        assert!(
            CLERIC_TEMPLATE.features.contains(DIVINE_STRIKE_TAG),
            "the baseline chassis must actually carry the tag this template removes"
        );
        // Channel Divinity ships and is charged.
        assert!(e.actors[&cleric].has_passive_feature(INVOKE_DUPLICITY_TAG));
        assert!(e.actors[&cleric].feature_available(INVOKE_DUPLICITY_TAG));
        assert!(e.actors[&cleric].find_action("invoke duplicity").is_some());
        // Everything else on the baseline chassis still arrives.
        for tag in [TURN_UNDEAD_TAG, PRESERVE_LIFE_TAG, DESTROY_UNDEAD_TAG] {
            assert!(
                e.actors[&cleric].has_passive_feature(tag),
                "Trickery Cleric should inherit baseline Cleric tag {}",
                tag
            );
        }
    }

    /// Invoke Duplicity buys advantage on the cleric's attack rolls and
    /// spends the short-rest charge doing it — and, unlike every
    /// one-shot prime on the same cohort, the flag survives the swing
    /// that uses it. That persistence is the entire feature: a version
    /// consumed on first attack would be a worse Guided Strike.
    #[test]
    fn invoke_duplicity_grants_persistent_attack_advantage() {
        use crate::actions::action_template::Action;
        use crate::actions::class_features::{INVOKE_DUPLICITY, INVOKE_DUPLICITY_TAG};
        use crate::actors::creatures::clerics::TRICKERY_CLERIC_TEMPLATE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let cleric = e
            .instantiate_creature(&TRICKERY_CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let goblin = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(3, 2), 1, 0)
            .unwrap();
        assert_eq!(e.compute_attack_mode(cleric, goblin, true), RollMode::Normal);
        assert!(INVOKE_DUPLICITY.custom_validate_input(&e, cleric, None, None, None));
        for ef in INVOKE_DUPLICITY.side_effects(&mut e, cleric, None, None, None) {
            ef.apply(&mut e);
        }
        assert!(e.actors[&cleric].has_condition(Condition::Duplicity));
        assert!(!e.actors[&cleric].feature_available(INVOKE_DUPLICITY_TAG));
        assert_eq!(e.compute_attack_mode(cleric, goblin, true), RollMode::Advantage);
        // Re-priming a live illusion is refused, so the charge can't be
        // burned refreshing a timer.
        assert!(!INVOKE_DUPLICITY.custom_validate_input(&e, cleric, None, None, None));
        // A swing does not eat the flag: `Duplicity` is deliberately off
        // `CONSUMED_ON_ATTACK`.
        e.clear_attack_advantage_riders(cleric, goblin);
        assert!(
            e.actors[&cleric].has_condition(Condition::Duplicity),
            "the double stays out for its full duration"
        );
        assert_eq!(e.compute_attack_mode(cleric, goblin, true), RollMode::Advantage);
    }

    /// Both new `ON_HIT_RIDERS` rows land, and land as themselves.
    ///
    /// Driven by installing the flag directly on a monk rather than
    /// through either owning class, because the rider table is keyed by
    /// condition and nothing else — that is the contract worth pinning.
    /// The Trickery cleric's own path (action → flag) is covered by
    /// `trickery_cleric_swaps_divine_strike_rather_than_stacking_it`
    /// and `invoke_duplicity_grants_persistent_attack_advantage`.
    ///
    /// Sweeps seeds so at least one swing connects. A row that silently
    /// kept a neighbour's damage typing or label would pass every
    /// structural assertion elsewhere and fail only here.
    #[test]
    fn the_new_on_hit_riders_land_with_their_own_typing() {
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::actors::creatures::monks::MONK_TEMPLATE;
        use crate::engine::dice::FastRandRoller;
        for (prime, label) in [
            (Condition::DivineStrikingPoison, "divine strike (poison)"),
            (Condition::FangsOfTheFireSnake, "fangs of the fire snake"),
        ] {
            let mut saw_rider = false;
            for seed in 0..40 {
                let mut e = ei_with_terrain(15, 15, &[]);
                e.roller = FastRandRoller::with_seed(seed);
                let monk = e
                    .instantiate_creature(&MONK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                    .unwrap();
                let goblin = e
                    .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(3, 2), 1, 0)
                    .unwrap();
                e.actors
                    .get_mut(&monk)
                    .unwrap()
                    .add_condition(prime, ConditionTimer::Rounds(2));
                let strike = e.actors[&monk]
                    .find_action("martial arts")
                    .expect("the monk chassis carries its unarmed strike");
                for ef in strike.execute(&mut e, monk, Some(&vec![goblin]), None, None) {
                    ef.apply(&mut e);
                }
                if e.messages().iter().any(|m| m.contains(label)) {
                    saw_rider = true;
                    assert!(
                        !e.actors[&monk].has_condition(prime),
                        "{} is a one-shot prime and must burn off on the hit",
                        label
                    );
                    break;
                }
            }
            assert!(saw_rider, "40 seeds should land at least one {} swing", label);
        }
    }

    /// Four Elements template drift pin: both discipline actions, the
    /// rider tag, the ki-as-slots budget, and the whole baseline Monk
    /// chassis inherited through the `..MONK_TEMPLATE.clone()` tail.
    #[test]
    fn four_elements_monk_ships_its_kit_and_inherits_the_monk_chassis() {
        use crate::actions::class_features::{
            EMPTY_BODY_TAG, FANGS_OF_THE_FIRE_SNAKE_TAG, PURITY_OF_BODY_TAG, STUNNING_STRIKE_TAG,
            UNARMORED_MOVEMENT_TAG,
        };
        use crate::actors::creatures::monks::{FOUR_ELEMENTS_MONK_TEMPLATE, MONK_TEMPLATE};
        let mut e = ei_with_terrain(15, 15, &[]);
        let monk = e
            .instantiate_creature(&FOUR_ELEMENTS_MONK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        assert!(e.actors[&monk].has_passive_feature(FANGS_OF_THE_FIRE_SNAKE_TAG));
        for name in [
            "water whip",
            "fangs of the fire snake",
            // The disciplines proper, one per tier.
            "burning hands",
            "shatter",
            "fireball",
            "stoneskin",
            "cone of cold",
        ] {
            assert!(
                e.actors[&monk].find_action(name).is_some(),
                "the Four Elements kit needs {}",
                name
            );
        }
        // The ki budget is real: a baseline monk has none at all.
        assert_eq!(
            FOUR_ELEMENTS_MONK_TEMPLATE.spell_slots_by_level,
            vec![2, 2, 1, 1, 1]
        );
        assert!(MONK_TEMPLATE.spell_slots_by_level.is_empty());
        // The chassis still arrives whole.
        for tag in [
            STUNNING_STRIKE_TAG,
            PURITY_OF_BODY_TAG,
            EMPTY_BODY_TAG,
            UNARMORED_MOVEMENT_TAG,
        ] {
            assert!(
                e.actors[&monk].has_passive_feature(tag),
                "Four Elements Monk should inherit baseline Monk tag {}",
                tag
            );
        }
        assert!(e.actors[&monk].has_extra_attack());
        assert!(e.actors[&monk].has_diamond_soul());
    }

    /// Water Whip's two halves come apart on the save: prone rides the
    /// failure, the damage rides both at different magnitudes. Sweeps
    /// seeds until each branch is observed so neither can silently
    /// collapse into the other.
    #[test]
    fn water_whip_prones_on_a_failed_save_only() {
        use crate::actions::action_template::Action;
        use crate::actions::class_features::WATER_WHIP;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::actors::creatures::monks::FOUR_ELEMENTS_MONK_TEMPLATE;
        use crate::engine::dice::FastRandRoller;
        let mut saw_fail = false;
        let mut saw_pass = false;
        for seed in 0..60 {
            let mut e = ei_with_terrain(20, 20, &[]);
            e.roller = FastRandRoller::with_seed(seed);
            let monk = e
                .instantiate_creature(&FOUR_ELEMENTS_MONK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            // Out of melee reach but inside the whip's 30 ft — the lash
            // is the monk's only ranged option and this pins that.
            let goblin = e
                .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(9, 2), 1, 0)
                .unwrap();
            for ef in WATER_WHIP.side_effects(&mut e, monk, Some(&vec![goblin]), None, None) {
                ef.apply(&mut e);
            }
            let proned = e
                .actors
                .get(&goblin)
                .is_some_and(|g| g.has_condition(Condition::Prone));
            let failed = e.messages().iter().any(|m| m.contains("fail (full)"));
            if failed {
                saw_fail = true;
                assert!(proned || !e.actors.contains_key(&goblin) || !e.actors[&goblin].is_combat_active(),
                    "a failed save should sweep the target off its feet");
            } else if e.messages().iter().any(|m| m.contains("save (half)")) {
                saw_pass = true;
                assert!(
                    !proned,
                    "a passed save keeps the target on its feet"
                );
            }
            if saw_fail && saw_pass {
                break;
            }
        }
        assert!(saw_fail && saw_pass, "60 seeds should show both save branches");
    }

    /// The promoted save DCs follow the caster's own spellcasting stat
    /// rather than a hardcoded Intelligence. A druid's Thunderwave is
    /// anchored on WIS, a wizard's on INT — before the promotion both
    /// read INT, which quietly handed every non-wizard carrier of these
    /// six spells a DC computed off a stat their class never invests in.
    #[test]
    fn promoted_spell_dcs_follow_the_casters_own_ability() {
        use crate::actors::creatures::druids::DRUID_TEMPLATE;
        use crate::actors::creatures::monks::FOUR_ELEMENTS_MONK_TEMPLATE;
        use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let druid = e
            .instantiate_creature(&DRUID_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let wizard = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(4, 2), 0, 1)
            .unwrap();
        let monk = e
            .instantiate_creature(&FOUR_ELEMENTS_MONK_TEMPLATE, Coordinate::new(6, 2), 0, 2)
            .unwrap();
        let candidates = [
            AbilityScoreType::Intelligence,
            AbilityScoreType::Charisma,
            AbilityScoreType::Wisdom,
        ];
        assert_eq!(
            e.actors[&druid].best_spellcasting_ability(candidates),
            AbilityScoreType::Wisdom
        );
        assert_eq!(
            e.actors[&wizard].best_spellcasting_ability(candidates),
            AbilityScoreType::Intelligence
        );
        assert_eq!(
            e.actors[&monk].best_spellcasting_ability(candidates),
            AbilityScoreType::Wisdom,
            "a Four Elements monk's disciplines have to key off the ki DC stat"
        );
        // And the DC that falls out beats what INT alone would have
        // given the WIS chassis.
        assert!(
            e.actors[&monk].best_spell_save_dc(candidates)
                > e.actors[&monk].spell_save_dc(AbilityScoreType::Intelligence)
        );
    }

    /// Potent Spellcasting adds the cleric's WIS to cantrip damage and
    /// to nothing else. The three assertions that matter are the two
    /// negatives: a levelled spell gets no bonus (the gate is
    /// `is_cantrip`, not "the holder is a cleric"), and a cleric
    /// without the tag gets no bonus (the feature is a template
    /// property, not a class one).
    #[test]
    fn potent_spellcasting_lifts_cantrips_and_only_cantrips() {
        use crate::actions::class_features::POTENT_SPELLCASTING_TAG;
        use crate::actors::creatures::clerics::{CLERIC_TEMPLATE, KNOWLEDGE_CLERIC_TEMPLATE};
        use crate::engine::types::SpellSchool;
        let mut e = ei_with_terrain(15, 15, &[]);
        let knowing = e
            .instantiate_creature(&KNOWLEDGE_CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let plain = e
            .instantiate_creature(&CLERIC_TEMPLATE, Coordinate::new(4, 2), 0, 1)
            .unwrap();
        assert!(e.actors[&knowing].has_passive_feature(POTENT_SPELLCASTING_TAG));
        assert!(!e.actors[&plain].has_passive_feature(POTENT_SPELLCASTING_TAG));
        let wis = e.actors[&knowing]
            .ability_modifier(AbilityScoreType::Wisdom)
            .max(0) as u32;
        assert!(wis > 0, "the chassis has to have a positive WIS for this to say anything");

        // Zero dice isolate the flat bonus from the roll, so the
        // assertions are exact rather than statistical.
        let mut rolled = |caster: usize, level: u32| {
            e.enter_cast(Some(SpellSchool::Evocation), level);
            let out = e.roll_empowered_sum(caster, 0, 8);
            e.exit_cast();
            out
        };
        assert_eq!(rolled(knowing, 0), wis);
        assert_eq!(rolled(knowing, 3), 0, "RAW is cantrips only");
        assert_eq!(rolled(plain, 0), 0, "a cleric without the tag gets nothing");
        // Outside any cast frame — a weapon swing — the feature is
        // inert. The `is_cantrip` gate fails closed on `None`.
        assert_eq!(e.roll_empowered_sum(knowing, 0, 8), 0);
    }

    /// Knowledge Domain template drift pin, and the RAW rule the domain
    /// exists to demonstrate: each Divine Domain gets exactly one
    /// level-8 feature. Knowledge, Light and Arcana take Potent
    /// Spellcasting *instead of* the chassis's radiant Divine Strike;
    /// every other domain keeps the strike.
    #[test]
    fn the_level_eight_slot_holds_exactly_one_feature_per_domain() {
        use crate::actions::class_features::{DIVINE_STRIKE_TAG, POTENT_SPELLCASTING_TAG};
        use crate::actors::creatures::clerics::{
            ARCANA_CLERIC_TEMPLATE, CLERIC_TEMPLATE, FORGE_CLERIC_TEMPLATE,
            KNOWLEDGE_CLERIC_TEMPLATE, LIGHT_CLERIC_TEMPLATE, NATURE_CLERIC_TEMPLATE,
            TEMPEST_CLERIC_TEMPLATE, TRICKERY_CLERIC_TEMPLATE, WAR_CLERIC_TEMPLATE,
        };
        for template in [
            &*KNOWLEDGE_CLERIC_TEMPLATE,
            &*LIGHT_CLERIC_TEMPLATE,
            &*ARCANA_CLERIC_TEMPLATE,
        ] {
            assert!(
                template.features.contains(POTENT_SPELLCASTING_TAG),
                "{} takes Potent Spellcasting at level 8",
                template.name
            );
            assert!(
                !template.features.contains(DIVINE_STRIKE_TAG),
                "{} must not also carry the chassis's Divine Strike",
                template.name
            );
        }
        for template in [
            &*CLERIC_TEMPLATE,
            &*WAR_CLERIC_TEMPLATE,
            &*TEMPEST_CLERIC_TEMPLATE,
            &*FORGE_CLERIC_TEMPLATE,
            &*NATURE_CLERIC_TEMPLATE,
        ] {
            assert!(
                template.features.contains(DIVINE_STRIKE_TAG),
                "{} keeps the chassis's Divine Strike",
                template.name
            );
            assert!(!template.features.contains(POTENT_SPELLCASTING_TAG));
        }
        // Trickery is the third shape: it swaps the strike's *typing*
        // rather than the feature, so it carries neither the radiant
        // tag nor the passive.
        assert!(!TRICKERY_CLERIC_TEMPLATE.features.contains(DIVINE_STRIKE_TAG));
        assert!(
            !TRICKERY_CLERIC_TEMPLATE
                .features
                .contains(POTENT_SPELLCASTING_TAG)
        );
    }

    /// Every damaging cantrip routes its roll through the shared
    /// caster-aware chokepoint, so the three flat / reroll features
    /// that live there reach all of them.
    ///
    /// Driven through Potent Spellcasting because it is the cheapest of
    /// the three to observe: a flat, deterministic +WIS that shows up
    /// in the damage log without any seed sweeping. A cantrip that
    /// rolls with a bare `roll` instead of `roll_empowered_sum` deals
    /// exactly the same damage it always did — nothing crashes, nothing
    /// logs wrong, the bonus is just quietly missing — which is why
    /// four of them had drifted out of the chokepoint unnoticed.
    ///
    /// The Sorcerer's Empowered Spell and the Evocation Wizard's
    /// Empowered Evocation share the chokepoint and therefore share the
    /// guarantee; testing one pins all three.
    #[test]
    fn every_damaging_cantrip_reaches_the_shared_damage_chokepoint() {
        use crate::actions::action_template::TargetingSchema;
        use crate::actions::class_features::POTENT_SPELLCASTING_TAG;
        use crate::actors::creatures::clerics::KNOWLEDGE_CLERIC_TEMPLATE;
        use crate::actors::creatures::ogres::OGRE_TEMPLATE;
        use crate::engine::dice::FastRandRoller;
        // One representative per resolution shape a damaging cantrip
        // can take: single-target save-or-nothing, self-centered burst,
        // point-target burst, spell attack, and the pull-then-damage
        // outlier.
        let cantrips: &[&'static (dyn crate::actions::action_template::Action + Send + Sync)] = &[
            &*crate::actions::spells::SACRED_FLAME,
            &*crate::actions::spells::TOLL_THE_DEAD,
            &*crate::actions::spells::WORD_OF_RADIANCE,
            &*crate::actions::spells::FROSTBITE,
            &*crate::actions::spells::SAPPING_STING,
            &*crate::actions::spells::INFESTATION,
            &*crate::actions::spells::ACID_SPLASH,
            &*crate::actions::spells::THUNDERCLAP,
            &*crate::actions::spells::SWORD_BURST,
            &*crate::actions::spells::LIGHTNING_LURE,
            // The attack-roll lane. Added after a review found the
            // sweep was all-saves, which is exactly the blind spot that
            // let `spell_attack_outcome` keep rolling outside the
            // chokepoint: a Knowledge Cleric's Sacred Flame collected
            // Potent Spellcasting and the same cleric's Thorn Whip did
            // not, and nothing here noticed.
            &*crate::actions::spells::THORN_WHIP,
            &*crate::actions::spells::FIRE_BOLT,
            &*crate::actions::spells::RAY_OF_FROST,
            &*crate::actions::spells::CHILL_TOUCH,
        ];
        for action in cantrips {
            let mut reached = false;
            for seed in 0..60 {
                let mut e = ei_with_terrain(20, 20, &[]);
                e.roller = FastRandRoller::with_seed(seed);
                let cleric = e
                    .instantiate_creature(&KNOWLEDGE_CLERIC_TEMPLATE, Coordinate::new(3, 3), 0, 0)
                    .unwrap();
                assert!(e.actors[&cleric].has_passive_feature(POTENT_SPELLCASTING_TAG));
                // Adjacent so the self-centered bursts and the melee-
                // range cantrips all have a live target.
                let ogre = e
                    .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(4, 3), 1, 0)
                    .unwrap();
                // Feed each action exactly the argument shape its
                // schema declares — `execute` re-validates, and a
                // SingleActor action handed a stray location (or a
                // burst handed a stray id) bails before it ever rolls.
                let at = e.actors[&ogre].location();
                let (ids, locs) = match action.targeting_schema() {
                    TargetingSchema::SingleActor => (Some(vec![ogre]), None),
                    TargetingSchema::SinglePoint | TargetingSchema::Burst { .. } => {
                        (None, Some(vec![at]))
                    }
                    TargetingSchema::NoArgs | TargetingSchema::Custom => (None, None),
                };
                for ef in action.execute(&mut e, cleric, ids.as_ref(), locs.as_ref(), None) {
                    ef.apply(&mut e);
                }
                if e.messages().iter().any(|m| m.contains("potent spellcasting")) {
                    reached = true;
                    break;
                }
            }
            assert!(
                reached,
                "{} rolls its damage outside `roll_empowered_sum`, so Potent \
                 Spellcasting / Empowered Spell / Empowered Evocation all skip it",
                action.name()
            );
        }
    }

    /// A spell's save DC and attack modifier follow the caster's own
    /// spellcasting ability, not the class the spell was first written
    /// for.
    ///
    /// The failure this pins is the quietest kind in the engine: a
    /// warlock casting Fire Bolt off a hardcoded Intelligence anchor
    /// still fires, still logs, still rolls — it just rolls with the
    /// modifier of a stat warlocks dump. Thirty-seven save DCs and
    /// sixteen attack modifiers were anchored that way, every one of
    /// them on a spell three or more classes carry.
    ///
    /// Asserted through the accessor rather than by casting, because
    /// the accessor *is* the contract — every promoted call site reads
    /// it, and a regression would be a site drifting back to a fixed
    /// ability rather than the accessor returning the wrong answer.
    #[test]
    fn spellcasting_dc_and_attack_follow_the_caster_not_the_spell() {
        use crate::actors::creatures::clerics::CLERIC_TEMPLATE;
        use crate::actors::creatures::warlocks::WARLOCK_TEMPLATE;
        use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let wizard = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let warlock = e
            .instantiate_creature(&WARLOCK_TEMPLATE, Coordinate::new(4, 2), 0, 1)
            .unwrap();
        let cleric = e
            .instantiate_creature(&CLERIC_TEMPLATE, Coordinate::new(6, 2), 0, 2)
            .unwrap();
        for (id, expected, label) in [
            (wizard, AbilityScoreType::Intelligence, "wizard"),
            (warlock, AbilityScoreType::Charisma, "warlock"),
            (cleric, AbilityScoreType::Wisdom, "cleric"),
        ] {
            let a = &e.actors[&id];
            assert_eq!(
                a.spellcasting_save_dc(),
                a.spell_save_dc(expected),
                "{} should cast off {:?}",
                label,
                expected
            );
            assert_eq!(
                a.spellcasting_attack_modifier(),
                a.spell_attack_modifier(expected),
                "{} should attack off {:?}",
                label,
                expected
            );
        }
        // And the anchors genuinely differ, so the assertions above
        // aren't three ways of saying the same number.
        assert_ne!(
            e.actors[&wizard].spellcasting_save_dc(),
            e.actors[&wizard].spell_save_dc(AbilityScoreType::Charisma)
        );
        assert_ne!(
            e.actors[&warlock].spellcasting_save_dc(),
            e.actors[&warlock].spell_save_dc(AbilityScoreType::Intelligence)
        );
        assert_ne!(
            e.actors[&cleric].spellcasting_save_dc(),
            e.actors[&cleric].spell_save_dc(AbilityScoreType::Intelligence)
        );
    }

    /// Source-level drift pin: no spell in `spells.rs` rolls damage
    /// dice outside the shared caster-aware chokepoint.
    ///
    /// The behavioral sweep next door
    /// (`every_damaging_cantrip_reaches_the_shared_damage_chokepoint`)
    /// covers ten cantrips by actually casting them, which is the
    /// stronger check but doesn't scale: there are nearly three hundred
    /// spells, most of them needing a bespoke target setup to fire at
    /// all. This one reads the file instead. It cannot tell a damage
    /// roll from a duration roll, so it doesn't try — it asserts on the
    /// shape that distinguished every real offender: a
    /// `let <name> = encounter.roll(&Dice::new(..))` binding whose name
    /// is one of the damage-flavored ones the file uses, in a function
    /// that goes on to queue a `DealDamage`.
    ///
    /// Thirty-four sites matched when this was written, every one of
    /// them a spell the Sorcerer's Empowered Spell metamagic silently
    /// did nothing for. The two surviving exceptions are documented at
    /// their sites and named here, so adding a third is a deliberate
    /// act with a sentence attached rather than an oversight.
    #[test]
    fn no_spell_rolls_damage_outside_the_shared_chokepoint() {
        // The two bursts that roll fresh dice per target instead of
        // sharing one roll — Sickening Radiance because that is how it
        // resolves, Prismatic Spray because RAW gives each target its
        // own ray. Routing either through the chokepoint would pay the
        // flat per-cast bonuses once per victim. Both say so at their
        // roll sites.
        const DOCUMENTED_EXCEPTIONS: &[&str] = &["sickening radiance", "prismatic spray"];
        let src = include_str!("../actions/spells.rs");
        let lines: Vec<&str> = src.lines().collect();
        let damage_bindings = [
            "raw", "dmg", "damage", "dmg_full", "full", "splash", "half_splash",
            "cold_raw", "rad_raw", "thunder", "lightning",
        ];
        let mut offenders: Vec<String> = Vec::new();
        for (i, line) in lines.iter().enumerate() {
            let trimmed = line.trim();
            let Some(rest) = trimmed.strip_prefix("let ") else {
                continue;
            };
            let Some((name, tail)) = rest.split_once(" = ") else {
                continue;
            };
            if !damage_bindings.contains(&name.trim_start_matches("mut ")) {
                continue;
            }
            if !tail.contains("encounter.roll(&") {
                continue;
            }
            // Only flag it if the enclosing region actually deals
            // damage — a duration or a count rolled into a `raw` would
            // otherwise read as an offender.
            let window = lines[i..lines.len().min(i + 30)].join("\n");
            if !window.contains("DealDamage") {
                continue;
            }
            let context = lines[i.saturating_sub(40)..i].join("\n");
            if DOCUMENTED_EXCEPTIONS
                .iter()
                .any(|e| context.contains(e) || window.contains(e))
            {
                continue;
            }
            offenders.push(format!("spells.rs:{} — {}", i + 1, trimmed));
        }
        assert!(
            offenders.is_empty(),
            "these damage rolls bypass `roll_empowered_sum`, so Empowered Spell / \
             Empowered Evocation / Potent Spellcasting silently skip them:\n{}",
            offenders.join("\n")
        );
    }

    /// Beast Master template drift pin plus the behaviour that makes it
    /// a subclass rather than a flavour text: the call actually puts a
    /// friendly body on the board, on the ranger's team, and burns the
    /// once-per-rest charge doing it.
    #[test]
    fn rangers_companion_puts_a_beast_on_the_rangers_team() {
        use crate::actions::action_template::Action;
        use crate::actions::class_features::{RANGERS_COMPANION, RANGERS_COMPANION_TAG};
        use crate::actors::creatures::rangers::{BEAST_MASTER_RANGER_TEMPLATE, RANGER_TEMPLATE};
        let mut e = ei_with_terrain(15, 15, &[]);
        let ranger = e
            .instantiate_creature(&BEAST_MASTER_RANGER_TEMPLATE, Coordinate::new(5, 5), 0, 0)
            .unwrap();
        assert!(e.actors[&ranger].has_passive_feature(RANGERS_COMPANION_TAG));
        assert!(
            !RANGER_TEMPLATE.features.contains(RANGERS_COMPANION_TAG),
            "the baseline ranger must not already carry the bond"
        );
        assert!(RANGERS_COMPANION.custom_validate_input(&e, ranger, None, None, None));
        let before = e.actors.len();
        for ef in RANGERS_COMPANION.side_effects(&mut e, ranger, None, None, None) {
            ef.apply(&mut e);
        }
        assert_eq!(e.actors.len(), before + 1, "the beast should be on the board");
        let beast = *e
            .actors
            .keys()
            .find(|id| **id != ranger)
            .expect("a companion");
        assert_eq!(
            e.actors[&beast].team(),
            e.actors[&ranger].team(),
            "the companion fights for the ranger"
        );
        // Bestial Fury, and the proficiency-bonus AC bump.
        assert!(e.actors[&beast].has_extra_attack());
        assert!(e.actors[&beast].armor_class() > 13);
        // The charge is spent, so a second call is refused — a Beast
        // Master whose beast drops has lost the subclass for the day.
        assert!(!e.actors[&ranger].feature_available(RANGERS_COMPANION_TAG));
        assert!(!RANGERS_COMPANION.custom_validate_input(&e, ranger, None, None, None));
    }

    /// Every summoning action declares itself through
    /// `Action::summons_allies`, which is the hook the AI's summon rung
    /// reads.
    ///
    /// Before that rung existed no AI-driven caster ever summoned
    /// anything: a summon is `is_harmful` but declares no damage types
    /// and targets nothing, so every picker in the ladder filtered it
    /// out and the spells were reachable only by a human typing their
    /// name. This pins the declaration rather than the ladder position
    /// — the position is a judgement call that may be re-tuned, the
    /// declaration is the contract a new summon has to honor to be
    /// visible at all.
    #[test]
    fn every_summoning_action_declares_itself() {
        use crate::actions::action_template::Action;
        let summons: &[&'static (dyn Action + Send + Sync)] = &[
            &*crate::actions::spells::CONJURE_ANIMALS,
            &*crate::actions::spells::CONJURE_ELEMENTAL,
            &*crate::actions::spells::ANIMATE_DEAD,
            &*crate::actions::spells::ANIMATE_OBJECTS,
            &*crate::actions::class_features::RANGERS_COMPANION,
        ];
        for action in summons {
            assert!(
                action.summons_allies(),
                "{} puts bodies on the board and has to say so",
                action.name()
            );
        }
        // The default is false, and it stays false for things that
        // merely make allies better — otherwise the summon rung would
        // start firing on buffs.
        assert!(!crate::actions::spells::BLESS.summons_allies());
        assert!(!crate::actions::spells::FIREBALL.summons_allies());
    }

    /// The flat damage bonuses on the shared chokepoint are once per
    /// *cast*, not once per roll.
    ///
    /// RAW's unit for both Empowered Evocation and Potent Spellcasting
    /// is "one damage roll", meaning the spell. Most spells roll damage
    /// once so the distinction never surfaces — but Storm of Vengeance
    /// rolls thunder and lightning as separate pools, and Acid Arrow
    /// rolls impact and splash, and each of those would otherwise
    /// collect the bonus twice off one slot.
    #[test]
    fn the_flat_damage_bonus_is_paid_once_per_cast() {
        use crate::actions::class_features::POTENT_SPELLCASTING_TAG;
        use crate::actors::creatures::clerics::KNOWLEDGE_CLERIC_TEMPLATE;
        use crate::engine::types::SpellSchool;
        let mut e = ei_with_terrain(15, 15, &[]);
        let cleric = e
            .instantiate_creature(&KNOWLEDGE_CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        assert!(e.actors[&cleric].has_passive_feature(POTENT_SPELLCASTING_TAG));
        let wis = e.actors[&cleric]
            .ability_modifier(AbilityScoreType::Wisdom)
            .max(0) as u32;
        assert!(wis > 0);

        // Zero dice isolate the flat bonus from the roll.
        e.enter_cast(Some(SpellSchool::Evocation), 0);
        assert_eq!(e.roll_empowered_sum(cleric, 0, 8), wis, "first pool pays");
        assert_eq!(
            e.roll_empowered_sum(cleric, 0, 8),
            0,
            "a second damage pool in the same cast does not pay again"
        );
        e.exit_cast();

        // A fresh cast gets a fresh latch.
        e.enter_cast(Some(SpellSchool::Evocation), 0);
        assert_eq!(e.roll_empowered_sum(cleric, 0, 8), wis);
        e.exit_cast();
    }

    /// Symbiotic Entity hands out its shield, installs the melee rider,
    /// and — the clause that needed engine work — goes away the moment
    /// the shield does.
    ///
    /// The two halves are one test because the duration rule is the
    /// interesting part and it is only observable against the grant:
    /// checking that the condition installs proves nothing if the
    /// engine would have left it installed forever.
    #[test]
    fn the_spore_symbiote_lives_exactly_as_long_as_its_temp_hp() {
        use crate::actions::class_features::{
            SYMBIOTIC_ENTITY, SYMBIOTIC_ENTITY_TAG, SYMBIOTIC_ENTITY_TEMP_HP,
        };
        use crate::actors::creatures::druids::SPORES_DRUID_TEMPLATE;
        use crate::engine::side_effects::DealDamage;
        let mut e = ei_with_terrain(15, 15, &[]);
        let druid = e
            .instantiate_creature(&SPORES_DRUID_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        assert!(
            SYMBIOTIC_ENTITY.validate_input(&e, druid, None, None, None),
            "a fresh Spores Druid holds the charge"
        );
        for eff in SYMBIOTIC_ENTITY.side_effects(&mut e, druid, None, None, None) {
            eff.apply(&mut e);
        }
        assert_eq!(e.actors[&druid].temp_hp(), SYMBIOTIC_ENTITY_TEMP_HP);
        assert!(e.actors[&druid].has_condition(Condition::SymbioticEntity));
        assert!(
            !e.actors[&druid].feature_available(SYMBIOTIC_ENTITY_TAG),
            "the once-per-short-rest charge should be spent"
        );
        assert!(
            !SYMBIOTIC_ENTITY.validate_input(&e, druid, None, None, None),
            "a druid already wearing a symbiote should not burn a second charge"
        );

        // Chip the pool down without emptying it: the symbiote holds.
        DealDamage {
            actor_id: druid,
            amount: SYMBIOTIC_ENTITY_TEMP_HP - 1,
            damage_type: DamageType::Force,
        }
        .apply(&mut e);
        assert_eq!(e.actors[&druid].temp_hp(), 1);
        assert!(
            e.actors[&druid].has_condition(Condition::SymbioticEntity),
            "one temp HP left is still temp HP \u{2014} the symbiote stays"
        );

        // Empty it: RAW ends the feature on that tick.
        DealDamage {
            actor_id: druid,
            amount: 1,
            damage_type: DamageType::Force,
        }
        .apply(&mut e);
        assert_eq!(e.actors[&druid].temp_hp(), 0);
        assert!(
            !e.actors[&druid].has_condition(Condition::SymbioticEntity),
            "losing the last temporary hit point ends Symbiotic Entity"
        );
    }

    /// The symbiote dies with its shield down *either* damage lane.
    /// `effective_damage` (resistance-aware, the path `DealDamage`
    /// takes) and `take_damage` (the raw path) both drain temp HP, and
    /// before `drain_temp_hp` existed they did it with two separate
    /// copies of the subtraction. This pins the shared chokepoint.
    #[test]
    fn the_symbiote_ends_on_the_raw_damage_path_too() {
        use crate::actions::class_features::SYMBIOTIC_ENTITY_TEMP_HP;
        use crate::actors::creatures::druids::SPORES_DRUID_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let druid = e
            .instantiate_creature(&SPORES_DRUID_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let a = e.actors.get_mut(&druid).unwrap();
        a.gain_temp_hp(SYMBIOTIC_ENTITY_TEMP_HP);
        a.add_condition(Condition::SymbioticEntity, ConditionTimer::Permanent);
        a.take_damage(SYMBIOTIC_ENTITY_TEMP_HP);
        assert_eq!(a.temp_hp(), 0);
        assert!(
            !a.has_condition(Condition::SymbioticEntity),
            "take_damage drains the same pool, so it must end the feature too"
        );
    }

    /// The halo costs the reaction and nothing else, and the symbiote
    /// makes it hit harder.
    ///
    /// Both branches run off the same seed, which makes the comparison
    /// exact rather than statistical: the Constitution save is rolled
    /// before the damage, so a given seed produces the same save result
    /// either way, and the doubled roll draws the plain roll's die plus
    /// one more from the same stream. Doubled can therefore never come
    /// out *behind* plain on any seed, and must come out ahead on the
    /// aggregate as soon as one save fails.
    #[test]
    fn the_halo_costs_only_a_reaction_and_doubles_under_the_symbiote() {
        use crate::actions::class_features::HALO_OF_SPORES;
        use crate::actors::creatures::druids::SPORES_DRUID_TEMPLATE;
        use crate::actors::creatures::ogres::OGRE_TEMPLATE;
        use crate::engine::side_effects::Resource;

        // The reaction is the whole price: no Action, no Bonus Action,
        // no slot. That is what lets the AI fire it on a turn it is
        // also casting.
        let costs = HALO_OF_SPORES.cost(&ei_with_terrain(15, 15, &[]), 0, None, None, None);
        assert_eq!(costs, vec![Resource::Reaction]);

        let mut plain_total = 0u32;
        let mut doubled_total = 0u32;
        for seed in 0..40u64 {
            for doubled in [false, true] {
                let mut e = ei_with_terrain_seeded(15, 15, &[], seed);
                let druid = e
                    .instantiate_creature(&SPORES_DRUID_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                    .unwrap();
                let ogre = e
                    .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(3, 2), 1, 0)
                    .unwrap();
                if doubled {
                    e.actors
                        .get_mut(&druid)
                        .unwrap()
                        .add_condition(Condition::SymbioticEntity, ConditionTimer::Permanent);
                }
                let before = e.actors[&ogre].hitpoints();
                let targets = vec![ogre];
                assert!(
                    HALO_OF_SPORES.validate_input(&e, druid, Some(&targets), None, None),
                    "an adjacent hostile is in the halo's 10 ft"
                );
                for eff in
                    HALO_OF_SPORES.side_effects(&mut e, druid, Some(&targets), None, None)
                {
                    eff.apply(&mut e);
                }
                let dealt = before - e.actors[&ogre].hitpoints();
                if doubled {
                    doubled_total += dealt;
                } else {
                    plain_total += dealt;
                }
            }
        }
        assert!(
            plain_total > 0,
            "40 seeds against a +3 Constitution save should fail at least once"
        );
        assert!(
            doubled_total > plain_total,
            "rolling the die twice must out-damage rolling it once ({} vs {})",
            doubled_total,
            plain_total
        );
    }

    /// The halo is all-or-nothing on the save — RAW's wording is
    /// "unless it succeeds", not "half as much on a success", and it is
    /// the rare exception in a codebase where nearly every save-gated
    /// burst halves.
    ///
    /// Swept across seeds because the ogre's +3 Constitution against
    /// the druid's DC 16 lands on both sides of the line; the test
    /// asserts the pairing (shrug ⇔ zero damage) on every seed and then
    /// asserts both outcomes were actually observed, so it can't pass
    /// vacuously by never rolling one of them.
    #[test]
    fn the_halo_deals_no_damage_at_all_on_a_successful_save() {
        use crate::actions::class_features::HALO_OF_SPORES;
        use crate::actors::creatures::druids::SPORES_DRUID_TEMPLATE;
        use crate::actors::creatures::ogres::OGRE_TEMPLATE;
        let mut shrugs = 0;
        let mut bites = 0;
        for seed in 0..40u64 {
            let mut e = ei_with_terrain_seeded(15, 15, &[], seed);
            let druid = e
                .instantiate_creature(&SPORES_DRUID_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            let ogre = e
                .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(3, 2), 1, 0)
                .unwrap();
            let before = e.actors[&ogre].hitpoints();
            let messages_before = e.messages().len();
            let targets = vec![ogre];
            for eff in HALO_OF_SPORES.side_effects(&mut e, druid, Some(&targets), None, None) {
                eff.apply(&mut e);
            }
            let shrugged = e.messages()[messages_before..]
                .iter()
                .any(|m| m.contains("shrugs off the spore cloud"));
            let dealt = before - e.actors[&ogre].hitpoints();
            if shrugged {
                assert_eq!(dealt, 0, "seed {}: a passed save takes nothing", seed);
                shrugs += 1;
            } else {
                assert!(
                    (1..=6).contains(&dealt),
                    "seed {}: a failed save takes one full 1d6, got {}",
                    seed,
                    dealt
                );
                bites += 1;
            }
        }
        assert!(shrugs > 0 && bites > 0, "the sweep should see both outcomes");
    }

    /// Aura of Conquest roots a Frightened enemy and bleeds it, and does
    /// neither to anyone who isn't both frightened and in range.
    ///
    /// All four combinations in one test because the aura is a
    /// conjunction and a conjunction is only pinned by checking the
    /// corners: a bug that dropped either half of the gate would still
    /// pass a test that only ever set up the passing case.
    #[test]
    fn the_conquest_aura_roots_only_frightened_enemies_standing_in_it() {
        use crate::actors::creatures::ogres::OGRE_TEMPLATE;
        use crate::actors::creatures::paladins::CONQUEST_PALADIN_TEMPLATE;

        // (frightened?, tiles away, should the aura bite?)
        let cases = [
            (true, 1, true),
            (true, 9, false),
            (false, 1, false),
            (false, 9, false),
        ];
        for (frightened, gap, expect_bite) in cases {
            let mut e = ei_with_terrain(20, 20, &[]);
            let paladin = e
                .instantiate_creature(&CONQUEST_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            let ogre = e
                .instantiate_creature(
                    &OGRE_TEMPLATE,
                    Coordinate::new(2 + gap, 2),
                    1,
                    0,
                )
                .unwrap();
            assert!(e.actors.contains_key(&paladin));
            if frightened {
                e.actors
                    .get_mut(&ogre)
                    .unwrap()
                    .add_condition(Condition::Frightened, ConditionTimer::Rounds(10));
            }
            let hp_before = e.actors[&ogre].hitpoints();
            e.start_turn_for(ogre);
            let rooted = e.actors[&ogre].remaining_movement() <= 0.0;
            let bled = e.actors[&ogre].hitpoints() < hp_before;
            assert_eq!(
                rooted, expect_bite,
                "frightened={} gap={}: speed-0 clause",
                frightened, gap
            );
            assert_eq!(
                bled, expect_bite,
                "frightened={} gap={}: psychic drip clause",
                frightened, gap
            );
        }
    }

    /// The aura is hostile-scoped: a Conquest Paladin does not root
    /// their own frightened allies.
    ///
    /// Worth its own test because `aura_emitters` grew a team-side
    /// parameter to support this, and every other caller passes the
    /// opposite value — a wire-up that flipped the argument would leave
    /// all five ally auras working and only this one wrong.
    #[test]
    fn the_conquest_aura_spares_the_paladins_own_frightened_allies() {
        use crate::actors::creatures::ogres::OGRE_TEMPLATE;
        use crate::actors::creatures::paladins::CONQUEST_PALADIN_TEMPLATE;
        let mut e = ei_with_terrain(20, 20, &[]);
        let _paladin = e
            .instantiate_creature(&CONQUEST_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        // Same team as the paladin.
        let ally = e
            .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(3, 2), 0, 0)
            .unwrap();
        e.actors
            .get_mut(&ally)
            .unwrap()
            .add_condition(Condition::Frightened, ConditionTimer::Rounds(10));
        let hp_before = e.actors[&ally].hitpoints();
        e.start_turn_for(ally);
        assert!(
            e.actors[&ally].remaining_movement() > 0.0,
            "an ally standing in the aura keeps their movement"
        );
        assert_eq!(
            e.actors[&ally].hitpoints(),
            hp_before,
            "an ally standing in the aura takes no psychic damage"
        );
    }

    /// Scornful Rebuke answers ranged attacks, which is what separates
    /// it from every other reflect in the engine.
    ///
    /// Driven through an ordinary swing rather than by poking the table
    /// directly, so the test also proves the lane is wired into the
    /// shared attack chokepoint and not just declared.
    #[test]
    fn scornful_rebuke_answers_an_arrow_the_way_it_answers_a_sword() {
        use crate::actors::creatures::paladins::CONQUEST_PALADIN_TEMPLATE;
        use crate::actors::creatures::scouts::SCOUT_TEMPLATE;
        let cha_mod =
            crate::engine::util::modifier_from_score(CONQUEST_PALADIN_TEMPLATE.charisma).max(1)
                as u32;

        // Sweep seeds so the assertion rests on the shots that land
        // rather than on one lucky roll.
        let mut rebukes = 0;
        for seed in 0..30u64 {
            let mut e = ei_with_terrain_seeded(20, 20, &[], seed);
            let paladin = e
                .instantiate_creature(&CONQUEST_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            // Well outside melee: nothing on the melee reflect lane can
            // reach, so anything the archer loses is the rebuke.
            let archer = e
                .instantiate_creature(&SCOUT_TEMPLATE, Coordinate::new(10, 2), 1, 0)
                .unwrap();
            let bow = e.actors[&archer]
                .actions
                .iter()
                .copied()
                .find(|a| a.name().contains("longbow"))
                .expect("the scout carries a longbow");
            let archer_hp_before = e.actors[&archer].hitpoints();
            let targets = vec![paladin];
            for eff in bow.side_effects(&mut e, archer, Some(&targets), None, None) {
                eff.apply(&mut e);
            }
            let lost = archer_hp_before - e.actors[&archer].hitpoints();
            if lost > 0 {
                assert_eq!(
                    lost, cha_mod,
                    "seed {}: the rebuke is exactly the paladin's CHA modifier",
                    seed
                );
                rebukes += 1;
            }
        }
        assert!(
            rebukes > 0,
            "30 seeds of longbow fire should connect at least once"
        );
    }

    /// An incapacitated paladin rebukes nobody — RAW writes the clause
    /// into the feature, and the reflect lane enforces it for every row
    /// rather than per-row.
    #[test]
    fn an_incapacitated_paladin_has_no_rebuke_left() {
        use crate::actors::creatures::ogres::OGRE_TEMPLATE;
        use crate::actors::creatures::paladins::CONQUEST_PALADIN_TEMPLATE;
        let mut e = ei_with_terrain(20, 20, &[]);
        let paladin = e
            .instantiate_creature(&CONQUEST_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let ogre = e
            .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(3, 2), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&paladin)
            .unwrap()
            .add_condition(Condition::Stunned, ConditionTimer::Permanent);
        let mut effects: Vec<Box<dyn crate::engine::side_effects::ApplicableSideEffect>> =
            Vec::new();
        crate::engine::attack::push_any_attack_reflect_riders(
            &mut e, &mut effects, ogre, paladin,
        );
        assert!(
            effects.is_empty(),
            "a stunned paladin queues no rebuke payload"
        );
    }

    /// Bladesong lights up all four of its clauses off one condition,
    /// and each one lands on a different engine lane.
    ///
    /// One test rather than four because the clauses share a single
    /// install and the interesting failure is a lane that never got
    /// wired — which a per-clause test would catch just as well, and
    /// which a combined test catches while also proving they all come
    /// from the same button.
    #[test]
    fn bladesong_buys_ac_speed_concentration_and_damage_at_once() {
        use crate::actions::class_features::{BLADESONG, BLADESONG_TAG};
        use crate::actors::creatures::wizards::BLADESINGER_WIZARD_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let wiz = e
            .instantiate_creature(&BLADESINGER_WIZARD_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let int_mod = e.actors[&wiz]
            .ability_modifier(AbilityScoreType::Intelligence)
            .max(1);
        assert!(int_mod > 0, "the chassis is INT-primary");

        let ac_before = e.actors[&wiz].armor_class() as i32;
        let speed_before = e.actors[&wiz].speed();

        assert!(BLADESONG.validate_input(&e, wiz, None, None, None));
        for eff in BLADESONG.side_effects(&mut e, wiz, None, None, None) {
            eff.apply(&mut e);
        }
        assert!(
            !e.actors[&wiz].feature_available(BLADESONG_TAG),
            "the once-per-short-rest charge is spent"
        );
        assert_eq!(
            e.actors[&wiz].armor_class() as i32 - ac_before,
            int_mod,
            "AC clause: the ability-scaled cohort adds exactly INT"
        );
        assert!(
            (e.actors[&wiz].speed() - speed_before - 10.0).abs() < 0.01,
            "speed clause: +10 ft"
        );
        assert!(
            !BLADESONG.validate_input(&e, wiz, None, None, None),
            "a wizard already singing should not burn a second charge"
        );
    }

    /// The concentration bonus is scoped to concentration saves and to
    /// nothing else.
    ///
    /// This is the whole reason `roll_save_with_extra_mode_and_bonus`
    /// exists: putting Bladesong's +INT on `condition_save_bonus` would
    /// have been a two-line change that also handed the squishiest
    /// chassis in the game a blanket bonus on every poison save and
    /// every Fireball it ducks. The test compares a plain Constitution
    /// save against a concentration one at the same DC across seeds —
    /// only the second may improve.
    #[test]
    fn the_bladesong_save_bonus_reaches_concentration_and_nothing_else() {
        use crate::actors::creatures::wizards::BLADESINGER_WIZARD_TEMPLATE;
        // A DC the CON save can land on either side of, so a +INT swing
        // is actually observable in the pass rate.
        const DC: i32 = 15;
        let mut plain_passes = [0usize; 2];
        let mut conc_passes = [0usize; 2];
        for (i, singing) in [false, true].into_iter().enumerate() {
            for seed in 0..60u64 {
                let mut e = ei_with_terrain_seeded(15, 15, &[], seed);
                let wiz = e
                    .instantiate_creature(
                        &BLADESINGER_WIZARD_TEMPLATE,
                        Coordinate::new(2, 2),
                        0,
                        0,
                    )
                    .unwrap();
                if singing {
                    e.actors
                        .get_mut(&wiz)
                        .unwrap()
                        .add_condition(Condition::Bladesinging, ConditionTimer::Rounds(10));
                }
                if e.roll_save(wiz, AbilityScoreType::Constitution, DC).passed() {
                    plain_passes[i] += 1;
                }
            }
            for seed in 0..60u64 {
                let mut e = ei_with_terrain_seeded(15, 15, &[], seed);
                let wiz = e
                    .instantiate_creature(
                        &BLADESINGER_WIZARD_TEMPLATE,
                        Coordinate::new(2, 2),
                        0,
                        0,
                    )
                    .unwrap();
                if singing {
                    e.actors
                        .get_mut(&wiz)
                        .unwrap()
                        .add_condition(Condition::Bladesinging, ConditionTimer::Rounds(10));
                }
                if e.roll_concentration_save(wiz, DC).passed() {
                    conc_passes[i] += 1;
                }
            }
        }
        assert_eq!(
            plain_passes[0], plain_passes[1],
            "an ordinary Constitution save must not notice the song \u{2014} \
             {} passes without it, {} with",
            plain_passes[0], plain_passes[1]
        );
        assert!(
            conc_passes[1] > conc_passes[0],
            "a concentration save must notice it \u{2014} {} passes without the song, {} with",
            conc_passes[0],
            conc_passes[1]
        );
    }

    /// Song of Victory rides the shared caster-side melee bump table, so
    /// it lands on an ordinary shortsword swing and only while the song
    /// is up.
    ///
    /// Same seed on both sides, so the to-hit rolls and damage dice are
    /// identical and the entire difference between the two totals is
    /// the bump. The expected size of that difference is read off the
    /// log rather than assumed to be one INT modifier: the Bladesinger
    /// has Extra Attack, so a single `side_effects` call can land two
    /// swings, and each connecting swing earns its own bump.
    #[test]
    fn song_of_victory_adds_int_to_the_bladesingers_steel() {
        use crate::actors::creatures::ogres::OGRE_TEMPLATE;
        use crate::actors::creatures::wizards::BLADESINGER_WIZARD_TEMPLATE;
        let mut compared = 0;
        for seed in 0..40u64 {
            let mut totals = [0u32; 2];
            let mut int_mod = 0;
            let mut bumps_logged = 0;
            for (i, singing) in [false, true].into_iter().enumerate() {
                let mut e = ei_with_terrain_seeded(15, 15, &[], seed);
                let wiz = e
                    .instantiate_creature(
                        &BLADESINGER_WIZARD_TEMPLATE,
                        Coordinate::new(2, 2),
                        0,
                        0,
                    )
                    .unwrap();
                let ogre = e
                    .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(3, 2), 1, 0)
                    .unwrap();
                int_mod = e.actors[&wiz]
                    .ability_modifier(AbilityScoreType::Intelligence)
                    .max(1) as u32;
                if singing {
                    e.actors
                        .get_mut(&wiz)
                        .unwrap()
                        .add_condition(Condition::Bladesinging, ConditionTimer::Rounds(10));
                }
                let sword = e.actors[&wiz]
                    .actions
                    .iter()
                    .copied()
                    .find(|a| a.name() == "shortsword")
                    .expect("the Bladesinger carries a shortsword");
                let before = e.actors[&ogre].hitpoints();
                let messages_before = e.messages().len();
                let targets = vec![ogre];
                for eff in sword.side_effects(&mut e, wiz, Some(&targets), None, None) {
                    eff.apply(&mut e);
                }
                totals[i] = before - e.actors[&ogre].hitpoints();
                if singing {
                    bumps_logged = e.messages()[messages_before..]
                        .iter()
                        .filter(|m| m.contains("song of victory"))
                        .count() as u32;
                }
            }
            // Only compare seeds where the swing actually connected; a
            // miss carries no damage to bump. The rolls are
            // seed-identical, so the two runs agree on hit-or-miss.
            if totals[0] > 0 {
                assert!(bumps_logged > 0, "seed {}: a landed swing sings", seed);
                assert_eq!(
                    totals[1] - totals[0],
                    int_mod * bumps_logged,
                    "seed {}: the song adds exactly INT per connecting swing",
                    seed
                );
                compared += 1;
            } else {
                assert_eq!(
                    bumps_logged, 0,
                    "seed {}: a whiffed swing earns no bump",
                    seed
                );
            }
        }
        assert!(compared > 0, "40 seeds should land at least one swing");
    }

    /// Ancestral Protectors marks exactly one creature per turn, moves
    /// the mark rather than accumulating it, and does nothing at all
    /// when the barbarian isn't raging.
    ///
    /// The three clauses are one test because they are one row on
    /// `ON_HIT_CONDITION_MARKS` and each is a distinct way that row can
    /// be wired wrong: a missing `holder_gate` marks out of rage, a
    /// missing once-per-turn check marks twice, and a missing move
    /// sweep leaves the old target haunted.
    #[test]
    fn the_ancestral_mark_is_exclusive_moves_and_needs_the_rage() {
        use crate::actors::creatures::barbarians::ANCESTRAL_GUARDIAN_BARBARIAN_TEMPLATE;
        use crate::actors::creatures::ogres::OGRE_TEMPLATE;

        // Deterministic hits: pick a seed where the greataxe connects,
        // then drive the whole scenario on it.
        let swing = |e: &mut EncounterInstance, barb: usize, target: usize| {
            let axe = e.actors[&barb]
                .actions
                .iter()
                .copied()
                .find(|a| a.name() == "greataxe")
                .expect("the barbarian carries a greataxe");
            let targets = vec![target];
            for eff in axe.side_effects(e, barb, Some(&targets), None, None) {
                eff.apply(e);
            }
        };

        let mut proved_no_rage = false;
        let mut proved_exclusive = false;
        for seed in 0..40u64 {
            let mut e = ei_with_terrain_seeded(20, 20, &[], seed);
            let barb = e
                .instantiate_creature(
                    &ANCESTRAL_GUARDIAN_BARBARIAN_TEMPLATE,
                    Coordinate::new(2, 2),
                    0,
                    0,
                )
                .unwrap();
            let first = e
                .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(3, 2), 1, 0)
                .unwrap();
            let second = e
                .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(2, 3), 1, 0)
                .unwrap();

            // Out of rage: a landed hit marks nobody.
            let unhurt = e.actors[&first].hitpoints();
            swing(&mut e, barb, first);
            if e.actors[&first].hitpoints() < unhurt {
                assert!(
                    !e.actors[&first].has_condition(Condition::AncestrallyHaunted),
                    "seed {}: a hit outside the rage marks nobody",
                    seed
                );
                proved_no_rage = true;
            }

            // In rage: the first landed hit of the turn marks, the
            // second does not, and a mark laid on a later turn moves.
            e.actors
                .get_mut(&barb)
                .unwrap()
                .add_condition(Condition::Raging, ConditionTimer::Rounds(10));
            swing(&mut e, barb, first);
            if !e.actors[&first].has_condition(Condition::AncestrallyHaunted) {
                // The swing missed on this seed; nothing to check.
                continue;
            }
            assert_eq!(
                e.actors[&first].linked_by(Condition::AncestrallyHaunted),
                Some(barb),
                "seed {}: the mark links back to the barbarian",
                seed
            );
            swing(&mut e, barb, second);
            assert!(
                !e.actors[&second].has_condition(Condition::AncestrallyHaunted),
                "seed {}: only the turn's *first* hit marks",
                seed
            );

            // New turn, new mark — and the old one lets go.
            e.start_turn_for(barb);
            swing(&mut e, barb, second);
            if e.actors[&second].has_condition(Condition::AncestrallyHaunted) {
                assert!(
                    !e.actors[&first].has_condition(Condition::AncestrallyHaunted),
                    "seed {}: the mark moves rather than accumulating",
                    seed
                );
                proved_exclusive = true;
            }
        }
        assert!(
            proved_no_rage && proved_exclusive,
            "the sweep should exercise both the no-rage and the move cases"
        );
    }

    /// Both clauses of the mark are scoped to the barbarian: the haunted
    /// creature swings at everyone else with disadvantage and for half
    /// damage, and at the barbarian normally.
    ///
    /// The disadvantage half and the damage half are checked together
    /// because the feature is the *pair* — a redirect works only if
    /// hitting the guarded ally is worse on both axes than hitting the
    /// barbarian.
    #[test]
    fn the_haunted_creature_is_worse_off_attacking_anyone_but_the_guardian() {
        use crate::actors::creatures::barbarians::ANCESTRAL_GUARDIAN_BARBARIAN_TEMPLATE;
        use crate::actors::creatures::ogres::OGRE_TEMPLATE;
        use crate::actors::creatures::wizards::WIZARD_TEMPLATE;
        let mut e = ei_with_terrain(20, 20, &[]);
        let barb = e
            .instantiate_creature(
                &ANCESTRAL_GUARDIAN_BARBARIAN_TEMPLATE,
                Coordinate::new(2, 2),
                0,
                0,
            )
            .unwrap();
        let wizard = e
            .instantiate_creature(&WIZARD_TEMPLATE, Coordinate::new(3, 3), 0, 0)
            .unwrap();
        let ogre = e
            .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(3, 2), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&ogre)
            .unwrap()
            .add_condition(Condition::AncestrallyHaunted, ConditionTimer::Rounds(2));
        e.actors
            .get_mut(&ogre)
            .unwrap()
            .set_condition_link(Condition::AncestrallyHaunted, Some(barb));

        assert_eq!(
            e.peek_attack_mode(ogre, barb, true),
            RollMode::Normal,
            "the spirits don't hinder a blow aimed at the barbarian"
        );
        assert_eq!(
            e.peek_attack_mode(ogre, wizard, true),
            RollMode::Disadvantage,
            "any other target draws disadvantage"
        );

        assert_eq!(
            crate::engine::attack::attacker_scoped_damage_reduction(&mut e, ogre, barb, 20),
            20,
            "damage to the barbarian is not reduced"
        );
        assert_eq!(
            crate::engine::attack::attacker_scoped_damage_reduction(&mut e, ogre, wizard, 20),
            10,
            "damage to anyone else is halved"
        );
    }

    /// Form of Dread's fear fires once a turn and the form survives it —
    /// the distinction that made `once_per_turn_tag` necessary.
    ///
    /// `consume_on_trigger`, the table's existing way for a rider to
    /// stop firing, would have stripped the condition and taken the
    /// temp HP and the Frightened immunity with it. This pins that the
    /// rider goes quiet while the form does not.
    #[test]
    fn form_of_dread_frightens_once_a_turn_without_ending_the_form() {
        use crate::actions::class_features::{FORM_OF_DREAD, FORM_OF_DREAD_TAG};
        use crate::actors::creatures::ogres::OGRE_TEMPLATE;
        use crate::actors::creatures::warlocks::UNDEAD_WARLOCK_TEMPLATE;

        let mut saw_a_second_swing = false;
        for seed in 0..40u64 {
            let mut e = ei_with_terrain_seeded(20, 20, &[], seed);
            let warlock = e
                .instantiate_creature(&UNDEAD_WARLOCK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            let ogre = e
                .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(3, 2), 1, 0)
                .unwrap();
            for eff in FORM_OF_DREAD.side_effects(&mut e, warlock, None, None, None) {
                eff.apply(&mut e);
            }
            assert!(e.actors[&warlock].has_condition(Condition::FormOfDread));
            assert!(
                e.actors[&warlock].temp_hp() > 9,
                "1d10 + level 9 is at least 10 temp HP"
            );

            // Eldritch Blast rather than the dagger, deliberately: the
            // rider's RAW trigger is "hit a creature with an attack",
            // and a spell attack only reaches the rider table through
            // the `RiderLane::AnyAttack` lane. A weapon swing would
            // pass this test even if that lane were wired wrong.
            let blade = e.actors[&warlock]
                .actions
                .iter()
                .copied()
                .find(|a| a.name() == "eldritch blast")
                .expect("the warlock carries eldritch blast");
            let targets = vec![ogre];
            for swing in 0..2 {
                let before_marked = e.actors[&warlock].once_per_turn_used(FORM_OF_DREAD_TAG);
                for eff in blade.side_effects(&mut e, warlock, Some(&targets), None, None) {
                    eff.apply(&mut e);
                }
                let after_marked = e.actors[&warlock].once_per_turn_used(FORM_OF_DREAD_TAG);
                if swing == 1 && before_marked {
                    assert!(
                        after_marked,
                        "seed {}: the ledger stays marked for the rest of the turn",
                        seed
                    );
                    saw_a_second_swing = true;
                }
                assert!(
                    e.actors[&warlock].has_condition(Condition::FormOfDread),
                    "seed {}: the form outlives its own rider",
                    seed
                );
            }
        }
        assert!(
            saw_a_second_swing,
            "the sweep should land a first blast and then try a second"
        );
    }

    /// A warlock wearing the form cannot be Frightened, which is the
    /// clause that makes the fear rider safe to lean on.
    #[test]
    fn the_dread_form_cannot_be_frightened_back() {
        use crate::actors::creatures::warlocks::UNDEAD_WARLOCK_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let warlock = e
            .instantiate_creature(&UNDEAD_WARLOCK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        assert!(
            !e.actor_immune_to_condition(warlock, Condition::Frightened),
            "out of the form the warlock is as frightenable as anyone"
        );
        e.actors
            .get_mut(&warlock)
            .unwrap()
            .add_condition(Condition::FormOfDread, ConditionTimer::Rounds(10));
        assert!(
            e.actor_immune_to_condition(warlock, Condition::Frightened),
            "in the form they are not"
        );
    }

    /// A Smite prime stays out of the spell-attack chokepoint even
    /// though the rider table is now walked from both.
    ///
    /// The lane split is the whole safety property of sharing the table:
    /// Divine Smite's RAW is "the next time you hit a creature with a
    /// melee weapon attack", so a paladin holding the prime who reaches
    /// out with a melee *spell* attack must not cash it in. Before
    /// `RiderLane` the guarantee was accidental — the spell path simply
    /// never saw the table — and an accidental guarantee is one nobody
    /// notices losing.
    #[test]
    fn a_smite_prime_survives_a_melee_spell_attack_unspent() {
        use crate::actors::creatures::ogres::OGRE_TEMPLATE;
        use crate::actors::creatures::paladins::PALADIN_TEMPLATE;
        let mut e = ei_with_terrain(15, 15, &[]);
        let paladin = e
            .instantiate_creature(&PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let ogre = e
            .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(3, 2), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&paladin)
            .unwrap()
            .add_condition(Condition::Smiting, ConditionTimer::Rounds(2));
        let mut effects: Vec<Box<dyn crate::engine::side_effects::ApplicableSideEffect>> =
            Vec::new();
        let added = crate::engine::attack::push_on_hit_riders(
            &mut e,
            &mut effects,
            paladin,
            ogre,
            crate::engine::attack::RiderSwing {
                is_melee: true,
                is_spell: true,
                is_crit: false,
                damage_so_far: 0,
            },
        );
        assert_eq!(added, 0, "a melee spell attack adds no smite damage");
        assert!(
            e.actors[&paladin].has_condition(Condition::Smiting),
            "and does not burn the prime"
        );
    }

    /// Kensei's Shot rides ranged weapon hits and nothing else.
    ///
    /// The lane is the whole test: it is the only class feature on the
    /// rider table using `RiderLane::RangedWeapon`, so a wiring mistake
    /// would show up as a monk whose unarmed strikes carry an archery
    /// buff. Both halves are checked against the same primed monk, so
    /// the negative can't pass by the prime simply not being up.
    #[test]
    fn kenseis_shot_rides_the_bow_and_not_the_fist() {
        use crate::actions::class_features::KENSEIS_SHOT;
        use crate::actors::creatures::monks::KENSEI_MONK_TEMPLATE;
        use crate::actors::creatures::ogres::OGRE_TEMPLATE;

        let mut fired_on_bow = 0;
        let mut fired_on_fist = 0;
        for seed in 0..40u64 {
            for weapon in ["longbow", "martial arts"] {
                let mut e = ei_with_terrain_seeded(20, 20, &[], seed);
                let monk = e
                    .instantiate_creature(&KENSEI_MONK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                    .unwrap();
                // Adjacent, so the fist is in reach and the bow is too.
                let ogre = e
                    .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(3, 2), 1, 0)
                    .unwrap();
                assert!(KENSEIS_SHOT.validate_input(&e, monk, None, None, None));
                for eff in KENSEIS_SHOT.side_effects(&mut e, monk, None, None, None) {
                    eff.apply(&mut e);
                }
                assert!(e.actors[&monk].has_condition(Condition::KenseisShot));
                let action = e.actors[&monk]
                    .actions
                    .iter()
                    .copied()
                    .find(|a| a.name() == weapon)
                    .unwrap_or_else(|| panic!("the kensei carries a {}", weapon));
                let messages_before = e.messages().len();
                let targets = vec![ogre];
                for eff in action.side_effects(&mut e, monk, Some(&targets), None, None) {
                    eff.apply(&mut e);
                }
                let rode = e.messages()[messages_before..]
                    .iter()
                    .any(|m| m.contains("kensei's shot:"));
                match weapon {
                    "longbow" if rode => fired_on_bow += 1,
                    "martial arts" if rode => fired_on_fist += 1,
                    _ => {}
                }
            }
        }
        assert!(
            fired_on_bow > 0,
            "40 seeds of bowfire should land at least one primed shot"
        );
        assert_eq!(
            fired_on_fist, 0,
            "a melee swing must never pick up a ranged-only rider"
        );
    }

    /// The prime lasts the turn rather than the shot, and clears on the
    /// monk's next turn-start.
    ///
    /// RAW says "until the end of the current turn", which is why the
    /// row is not `consume_on_trigger` — a Kensei with Extra Attack
    /// gets the rider on both arrows, not just the first.
    #[test]
    fn the_kensei_prime_outlives_its_first_arrow_and_dies_at_turn_start() {
        use crate::actions::class_features::KENSEIS_SHOT;
        use crate::actors::creatures::monks::KENSEI_MONK_TEMPLATE;
        use crate::actors::creatures::ogres::OGRE_TEMPLATE;
        let mut e = ei_with_terrain(20, 20, &[]);
        let monk = e
            .instantiate_creature(&KENSEI_MONK_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let ogre = e
            .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(8, 2), 1, 0)
            .unwrap();
        for eff in KENSEIS_SHOT.side_effects(&mut e, monk, None, None, None) {
            eff.apply(&mut e);
        }
        let bow = e.actors[&monk]
            .actions
            .iter()
            .copied()
            .find(|a| a.name() == "longbow")
            .expect("the kensei carries a longbow");
        let targets = vec![ogre];
        for eff in bow.side_effects(&mut e, monk, Some(&targets), None, None) {
            eff.apply(&mut e);
        }
        assert!(
            e.actors[&monk].has_condition(Condition::KenseisShot),
            "one arrow does not use the prime up"
        );
        assert!(
            !KENSEIS_SHOT.validate_input(&e, monk, None, None, None),
            "nor should the monk re-prime what is already up"
        );
        e.start_turn_for(monk);
        assert!(
            !e.actors[&monk].has_condition(Condition::KenseisShot),
            "the prime ends with the turn it was spent on"
        );
    }

    /// A rooted creature can't Dash its way out of the aura.
    ///
    /// This is the clause the first implementation got wrong. Draining
    /// the movement budget at turn-start reads as "speed 0" right up
    /// until the creature takes the Dash action, which hands the budget
    /// straight back — and Dash is exactly what something frightened and
    /// bleeding five a turn is going to reach for. RAW's second half,
    /// "and it can't benefit from any bonus to its speed", is what
    /// closes that, and a `zeros_movement` condition is what enforces
    /// it: the budget can be refilled all day and
    /// `remaining_movement` still reads zero.
    #[test]
    fn the_conquest_aura_survives_a_dash() {
        use crate::actors::creatures::ogres::OGRE_TEMPLATE;
        use crate::actors::creatures::paladins::CONQUEST_PALADIN_TEMPLATE;
        use crate::engine::side_effects::{ApplicableSideEffect, GiveResource, Resource};
        let mut e = ei_with_terrain(20, 20, &[]);
        let _paladin = e
            .instantiate_creature(&CONQUEST_PALADIN_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let ogre = e
            .instantiate_creature(&OGRE_TEMPLATE, Coordinate::new(3, 2), 1, 0)
            .unwrap();
        e.actors
            .get_mut(&ogre)
            .unwrap()
            .add_condition(Condition::Frightened, ConditionTimer::Rounds(10));
        e.start_turn_for(ogre);
        assert_eq!(e.actors[&ogre].remaining_movement(), 0.0);

        // Hand back a full move, the way Dash does.
        GiveResource {
            actor_id: ogre,
            resource: Resource::Movement(30.0),
        }
        .apply(&mut e);
        assert_eq!(
            e.actors[&ogre].remaining_movement(),
            0.0,
            "a rooted creature can't benefit from a speed bonus, Dash included"
        );

        // And it lets go on its own once the fear does.
        e.actors
            .get_mut(&ogre)
            .unwrap()
            .remove_condition(Condition::Frightened);
        e.start_turn_for(ogre);
        assert!(
            e.actors[&ogre].remaining_movement() > 0.0,
            "the root is re-checked every  turn, so a creature that shakes the fear walks"
        );
    }

    /// The size lane's core promise: a growth condition actually moves
    /// the creature's footprint on the board, and losing the condition
    /// puts it back. Verified through the reconciler rather than through
    /// any one feature, because every growth effect in the engine is
    /// meant to reach the board the same way.
    #[test]
    fn a_growth_condition_moves_the_footprint_and_gives_it_back() {
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::engine::types::Size;

        let mut e = ei_with_terrain(20, 20, &[]);
        let f = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(4, 4), 0, 0)
            .unwrap();
        assert_eq!(e.actors[&f].size(), Size::Medium);
        // A Medium creature stamps a 2x2 box; the tile just outside it
        // is free before the growth and claimed after.
        assert_eq!(e.actor_id_at(Coordinate::new(6, 6)), None);

        e.get_actor(f)
            .unwrap()
            .add_condition(Condition::Enlarged, ConditionTimer::Rounds(10));
        e.reconcile_footprints();
        assert_eq!(
            e.actors[&f].size(),
            Size::Large,
            "the reconciler should have granted the growth"
        );
        assert_eq!(
            e.actor_id_at(Coordinate::new(6, 6)),
            Some(f),
            "a Large footprint is 4 tiles wide, so (6,6) is now the fighter"
        );

        e.get_actor(f).unwrap().remove_condition(Condition::Enlarged);
        e.reconcile_footprints();
        assert_eq!(e.actors[&f].size(), Size::Medium);
        assert_eq!(
            e.actor_id_at(Coordinate::new(6, 6)),
            None,
            "shrinking back has to release the tiles it claimed"
        );
    }

    /// RAW grows a creature only "if there is enough room". A fighter
    /// boxed in by walls keeps the condition and stays Medium — and
    /// grows the moment the wall stops being in the way, because the
    /// reconciler re-asks the question on every pump rather than
    /// deciding once.
    #[test]
    fn a_growth_with_no_room_waits_until_there_is_room() {
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::engine::terrain::TerrainType;
        use crate::engine::types::Size;

        // Walls along the two edges a growing footprint would expand
        // into (anchored top-left, growth claims x+2..x+3 / y+2..y+3).
        let walls: Vec<(isize, isize)> = (4..8).flat_map(|n| [(6, n), (n, 6)]).collect();
        let mut e = ei_with_terrain(20, 20, &walls);
        let f = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(4, 4), 0, 0)
            .unwrap();
        e.get_actor(f)
            .unwrap()
            .add_condition(Condition::Enlarged, ConditionTimer::Rounds(10));
        e.reconcile_footprints();
        assert_eq!(
            e.actors[&f].size(),
            Size::Medium,
            "there is no room, so the growth waits"
        );
        assert!(
            e.actors[&f].has_condition(Condition::Enlarged),
            "the effect is still on the fighter — only the board refused"
        );

        // Knock the walls down and pump again.
        for (x, y) in &walls {
            let idx = e.idx(Coordinate::new(*x, *y)).unwrap();
            e.terrain[idx].terrain_type = TerrainType::Floor;
        }
        e.reconcile_footprints();
        assert_eq!(
            e.actors[&f].size(),
            Size::Large,
            "the same condition should grow the fighter once the room appears"
        );
    }

    /// Enlarge and Reduce cancel. RAW says each spell "has no effect on
    /// a creature already under the other's influence"; the engine gets
    /// there by summing ladder steps, so holding both is the same as
    /// holding neither — no precedence rule, no ordering question.
    #[test]
    fn enlarge_and_reduce_cancel_on_the_ladder() {
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::engine::types::Size;

        let mut e = ei_with_terrain(20, 20, &[]);
        let f = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(4, 4), 0, 0)
            .unwrap();
        let actor = e.get_actor(f).unwrap();
        actor.add_condition(Condition::Enlarged, ConditionTimer::Rounds(10));
        actor.add_condition(Condition::Reduced, ConditionTimer::Rounds(10));
        assert_eq!(e.actors[&f].desired_size(), Size::Medium);
        e.reconcile_footprints();
        assert_eq!(e.actors[&f].size(), Size::Medium);

        // Drop the growth and the shrink is left holding the ladder.
        e.get_actor(f).unwrap().remove_condition(Condition::Enlarged);
        e.reconcile_footprints();
        assert_eq!(e.actors[&f].size(), Size::Small);
    }

    /// Two stacked growth effects still only buy one category — the
    /// clamp in `desired_size` is what keeps a Rune Knight who is also
    /// the target of an Enlarge from becoming Huge.
    #[test]
    fn stacked_growths_only_buy_one_category() {
        use crate::actors::creatures::fighters::RUNE_KNIGHT_FIGHTER_TEMPLATE;
        use crate::engine::types::Size;

        let mut e = ei_with_terrain(20, 20, &[]);
        let f = e
            .instantiate_creature(&RUNE_KNIGHT_FIGHTER_TEMPLATE, Coordinate::new(4, 4), 0, 0)
            .unwrap();
        let actor = e.get_actor(f).unwrap();
        actor.add_condition(Condition::Enlarged, ConditionTimer::Rounds(10));
        actor.add_condition(Condition::GiantsMight, ConditionTimer::Rounds(10));
        e.reconcile_footprints();
        assert_eq!(e.actors[&f].size(), Size::Large);
    }

    /// Growing widens the ring the fighter threatens: a Large Rune
    /// Knight reaches a target a Medium one cannot. This is the half of
    /// Giant's Might that isn't a damage die, and the reason the size
    /// lane is worth having at all.
    #[test]
    fn giants_might_extends_the_fighters_reach() {
        use crate::actors::creatures::fighters::RUNE_KNIGHT_FIGHTER_TEMPLATE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;

        let mut e = ei_with_terrain(20, 20, &[]);
        let f = e
            .instantiate_creature(&RUNE_KNIGHT_FIGHTER_TEMPLATE, Coordinate::new(4, 4), 0, 0)
            .unwrap();
        // The Medium fighter's footprint is (4,4)-(5,5); the goblin sits
        // far enough east to be outside a melee envelope measured from
        // it.
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(8, 5), 1, 0)
            .unwrap();
        let reach = crate::actions::action_template::MELEE_REACH;
        assert!(
            e.footprint_distance(f, g).unwrap() > reach,
            "the goblin should start out of reach"
        );

        e.get_actor(f)
            .unwrap()
            .add_condition(Condition::GiantsMight, ConditionTimer::Rounds(10));
        e.reconcile_footprints();
        assert!(
            e.footprint_distance(f, g).unwrap() <= reach,
            "a Large footprint reaches a tile the Medium one could not"
        );
    }

    /// Giant's Might's damage rider fires once per turn and no more —
    /// the growth lasts a minute, so without the ledger the first swing
    /// of the fight would be paying for every swing after it.
    #[test]
    fn giants_might_rider_fires_once_per_turn() {
        use crate::actions::class_features::GIANTS_MIGHT_RIDER_TAG;
        use crate::actors::creatures::fighters::RUNE_KNIGHT_FIGHTER_TEMPLATE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::engine::attack::{RiderSwing, push_on_hit_riders};

        let mut e = ei_with_terrain(20, 20, &[]);
        let f = e
            .instantiate_creature(&RUNE_KNIGHT_FIGHTER_TEMPLATE, Coordinate::new(4, 4), 0, 0)
            .unwrap();
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(8, 8), 1, 0)
            .unwrap();
        e.get_actor(f)
            .unwrap()
            .add_condition(Condition::GiantsMight, ConditionTimer::Rounds(10));

        let mut effects: Vec<Box<dyn crate::engine::side_effects::ApplicableSideEffect>> =
            Vec::new();
        let swing = RiderSwing {
            is_melee: true,
            is_spell: false,
            is_crit: false,
            damage_so_far: 0,
        };
        let first = push_on_hit_riders(&mut e, &mut effects, f, g, swing);
        assert!(first > 0, "the first swing of the turn carries the rider");
        assert!(e.actors[&f].once_per_turn_used(GIANTS_MIGHT_RIDER_TAG));
        let second = push_on_hit_riders(&mut e, &mut effects, f, g, swing);
        assert_eq!(second, 0, "the second swing of the same turn does not");
        assert!(
            e.actors[&f].has_condition(Condition::GiantsMight),
            "the growth itself outlives the turn's rider"
        );
    }

    /// The Reduce half of Enlarge / Reduce shrinks its target, takes a
    /// die off their swings, and turns their STR saves sour — the three
    /// clauses RAW gives it, each landing on a different shared table.
    #[test]
    fn reduce_shrinks_and_weakens_its_target() {
        use crate::actors::creatures::fighters::FIGHTER_TEMPLATE;
        use crate::engine::types::{AbilityScoreType, Size};

        let mut e = ei_with_terrain(20, 20, &[]);
        let f = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(4, 4), 0, 0)
            .unwrap();
        assert!(matches!(
            e.compute_save_mode(f, AbilityScoreType::Strength),
            RollMode::Normal
        ));

        e.get_actor(f)
            .unwrap()
            .add_condition(Condition::Reduced, ConditionTimer::Rounds(10));
        e.reconcile_footprints();
        assert_eq!(e.actors[&f].size(), Size::Small);
        assert!(
            matches!(
                e.compute_save_mode(f, AbilityScoreType::Strength),
                RollMode::Disadvantage
            ),
            "Reduce sours STR saves"
        );
        // ...and Enlarge sweetens them, off the same table.
        let g = e
            .instantiate_creature(&FIGHTER_TEMPLATE, Coordinate::new(10, 10), 0, 1)
            .unwrap();
        e.get_actor(g)
            .unwrap()
            .add_condition(Condition::Enlarged, ConditionTimer::Rounds(10));
        assert!(matches!(
            e.compute_save_mode(g, AbilityScoreType::Strength),
            RollMode::Advantage
        ));
    }

    /// Fire Rune spends its charge on the prime, and the prime is
    /// consumed by the swing that cashes it — both halves of a
    /// once-per-rest resource, checked together so a regression in
    /// either shows up here.
    #[test]
    fn fire_rune_primes_once_and_is_spent_by_the_swing() {
        use crate::actions::class_features::{FIRE_RUNE, FIRE_RUNE_TAG};
        use crate::actors::creatures::fighters::RUNE_KNIGHT_FIGHTER_TEMPLATE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::engine::attack::{RiderSwing, push_on_hit_riders};

        let mut e = ei_with_terrain(20, 20, &[]);
        let f = e
            .instantiate_creature(&RUNE_KNIGHT_FIGHTER_TEMPLATE, Coordinate::new(4, 4), 0, 0)
            .unwrap();
        let g = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(8, 8), 1, 0)
            .unwrap();
        assert!(e.actors[&f].feature_available(FIRE_RUNE_TAG));
        assert!(FIRE_RUNE.validate_input(&e, f, None, None, None));
        for eff in FIRE_RUNE.side_effects(&mut e, f, None, None, None) {
            eff.apply(&mut e);
        }
        assert!(e.actors[&f].has_condition(Condition::FireRuneInvoked));
        assert!(
            !e.actors[&f].feature_available(FIRE_RUNE_TAG),
            "priming the rune spends its charge"
        );
        assert!(
            !FIRE_RUNE.validate_input(&e, f, None, None, None),
            "and a spent rune cannot be primed again"
        );

        let mut effects: Vec<Box<dyn crate::engine::side_effects::ApplicableSideEffect>> =
            Vec::new();
        let rider = push_on_hit_riders(
            &mut e,
            &mut effects,
            f,
            g,
            RiderSwing {
                is_melee: true,
                is_spell: false,
                is_crit: false,
                damage_so_far: 0,
            },
        );
        assert!((2..=12).contains(&rider), "2d6 fire, got {}", rider);
        assert!(
            !e.actors[&f].has_condition(Condition::FireRuneInvoked),
            "the swing consumes the prime"
        );
    }

    /// Reaper doubles a single-target necromancy cantrip onto a second
    /// creature standing beside the first — the Death Domain's headline
    /// feature, and the only member of the cast-doubling family that
    /// fires on cantrips.
    #[test]
    fn reaper_doubles_a_necromancy_cantrip_onto_a_neighbour() {
        use crate::actions::spells::CHILL_TOUCH;
        use crate::actors::creatures::clerics::DEATH_CLERIC_TEMPLATE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;

        // Chill Touch is an attack roll, so sweep seeds until one lands
        // on both. What is under test is that the second goblin is
        // *reached at all* — before Reaper, nothing could touch it.
        let mut doubled = false;
        for seed in 0..40u64 {
            let mut e = ei_with_terrain_seeded(20, 20, &[], seed);
            let cleric = e
                .instantiate_creature(&DEATH_CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
                .unwrap();
            let first = e
                .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(8, 8), 1, 0)
                .unwrap();
            // Second goblin footprint-adjacent to the first, which is
            // RAW's "within 5 feet of each other".
            let second = e
                .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(10, 8), 1, 1)
                .unwrap();
            let before = e.actors[&second].hitpoints();
            let targets = vec![first];
            for eff in CHILL_TOUCH.execute(&mut e, cleric, Some(&targets), None, None) {
                eff.apply(&mut e);
            }
            if e.actors.get(&second).is_none_or(|a| a.hitpoints() < before) {
                doubled = true;
                break;
            }
        }
        assert!(
            doubled,
            "Reaper should carry Chill Touch onto the neighbouring goblin"
        );
    }

    /// Reaper's two gates, both negative cases. It is cantrips only —
    /// the exact inverse of Split Enchantment — and the second creature
    /// has to be beside the first, not merely in the caster's range.
    #[test]
    fn reaper_declines_a_leveled_spell_and_a_distant_second_target() {
        use crate::actions::spells::CHILL_TOUCH;
        use crate::actors::creatures::clerics::DEATH_CLERIC_TEMPLATE;
        use crate::actors::creatures::goblins::GOBLIN_TEMPLATE;
        use crate::engine::types::SpellSchool;

        let mut e = ei_with_terrain(30, 30, &[]);
        let cleric = e
            .instantiate_creature(&DEATH_CLERIC_TEMPLATE, Coordinate::new(2, 2), 0, 0)
            .unwrap();
        let first = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(8, 8), 1, 0)
            .unwrap();
        // Well inside Chill Touch's 48-tile reach, but nowhere near the
        // first goblin.
        e.instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(20, 20), 1, 1)
            .unwrap();
        assert_eq!(
            e.consume_reaper(
                cleric,
                CHILL_TOUCH.name(),
                Some(SpellSchool::Necromancy),
                0,
                true,
                CHILL_TOUCH.reach_tiles(),
                CHILL_TOUCH.requires_los(),
                first,
            ),
            None,
            "the pair has to be within 5 ft of each other"
        );

        // Move the second goblin next door and the same call finds it —
        // then the level gate refuses the identical situation.
        let neighbour = e
            .instantiate_creature(&GOBLIN_TEMPLATE, Coordinate::new(10, 8), 1, 2)
            .unwrap();
        assert_eq!(
            e.consume_reaper(
                cleric,
                CHILL_TOUCH.name(),
                Some(SpellSchool::Necromancy),
                0,
                true,
                CHILL_TOUCH.reach_tiles(),
                CHILL_TOUCH.requires_los(),
                first,
            ),
            Some(neighbour)
        );
        assert_eq!(
            e.consume_reaper(
                cleric,
                "inflict wounds",
                Some(SpellSchool::Necromancy),
                1,
                true,
                CHILL_TOUCH.reach_tiles(),
                CHILL_TOUCH.requires_los(),
                first,
            ),
            None,
            "Reaper is cantrips only"
        );
    }

    /// A cleric without the Death Domain gets nothing: the tag is the
